{
  "schema_version": 1,
  "id": "common",
  "default": true,
  "description": "AgentStart-managed capabilities loaded into every managed harness session.",
  "resources": {
    "skills": "skills",
    "guidance": "guidance/AGENTS.md",
    "claude": "claude",
    "pi_extensions": "pi/extensions",
    "pi_prompt_templates": "pi/prompt-templates"
  }
}

// Pi status line — the fleet statusline's pi renderer.
//
// AgentStart owns this file; ~/.pi/agent/extensions/agentstart-statusline.ts
// links at it. It draws the same fields in the same order as the claude
// renderer beside it, minus the two pi cannot know: Anthropic subscription
// rate limits, and which account a balanced launch picked (codex-swap pins
// pi's account by swapping auth in place, so nothing in the environment
// names it — claude-swap's CLAUDE_CONFIG_DIR has no counterpart here).
//
// Why: no type import from the pi package. The structural interfaces below are
// the subset this file actually touches, all of it optional so a pi whose API
// has moved renders a shorter bar instead of throwing.

import { execFile } from "node:child_process"
import { readFileSync, realpathSync } from "node:fs"
import { basename, dirname, join } from "node:path"

interface Theme {
  fg(color: string, text: string): string
}

interface FooterData {
  getGitBranch(): string | null
  onBranchChange(callback: () => void): () => void
}

interface Ctx {
  cwd: string
  mode?: string
  model?: { id?: string; name?: string; contextWindow?: number }
  getContextUsage?(): { tokens: number | null; contextWindow: number; percent: number | null } | undefined
  getThinkingLevel?(): string
  ui: {
    setFooter?(factory: unknown): void
  }
}

interface Api {
  on(event: string, handler: (event: unknown, ctx: Ctx) => void | Promise<void>): void
  getThinkingLevel?(): string
}

const SEP = " │ "

/** Git facts for one working tree, all from the single status call below. */
interface GitState {
  project: string
  branch: string
  dirty: boolean
  ahead: number
  behind: number
  insertions: number
  deletions: number
}

const EMPTY_GIT: GitState = {
  project: "",
  branch: "",
  dirty: false,
  ahead: 0,
  behind: 0,
  insertions: 0,
  deletions: 0,
}

function runGit(cwd: string, args: string[]): Promise<string> {
  return new Promise((resolve) => {
    try {
      execFile(
        "git",
        ["-C", cwd, "--no-optional-locks", ...args],
        { encoding: "utf8", timeout: 2_000, maxBuffer: 256 * 1024 },
        (error, stdout) => resolve(error ? "" : stdout),
      )
    } catch {
      resolve("")
    }
  })
}

async function probeGit(cwd: string): Promise<GitState> {
  const [status, shortstat, topLevel] = await Promise.all([
    runGit(cwd, ["status", "--porcelain=v2", "--branch"]),
    runGit(cwd, ["diff", "--shortstat"]),
    runGit(cwd, ["rev-parse", "--show-toplevel"]),
  ])
  if (status === "") return { ...EMPTY_GIT, project: basename(cwd) || cwd }

  const state: GitState = { ...EMPTY_GIT, project: basename(topLevel.trim()) || basename(cwd) || cwd }
  let oid = ""
  for (const line of status.split("\n")) {
    if (!line.startsWith("#")) {
      if (line.trim() !== "") state.dirty = true
      continue
    }
    const [, key, ...rest] = line.split(" ")
    if (key === "branch.oid") oid = rest[0] ?? ""
    if (key === "branch.head") state.branch = rest[0] ?? ""
    // `branch.ab` is signed: `+2 -1`. An unpublished branch omits the line.
    if (key === "branch.ab") {
      state.ahead = Number.parseInt(rest[0] ?? "0", 10) || 0
      state.behind = Math.abs(Number.parseInt(rest[1] ?? "0", 10) || 0)
    }
  }
  // Git spells a detached head as the literal `(detached)`; name the commit
  // instead, the way the claude renderer does.
  if (state.branch === "(detached)") state.branch = oid === "" ? "" : `@${oid.slice(0, 7)}`
  state.insertions = Number.parseInt(shortstat.match(/(\d+) insertion/)?.[1] ?? "0", 10)
  state.deletions = Number.parseInt(shortstat.match(/(\d+) deletion/)?.[1] ?? "0", 10)
  return state
}

/**
 * Pi's own version. It is not on the extension API, so it comes from the
 * package that owns the running entry point.
 *
 * Why realpath first: pi is normally launched through an npm/nvm bin symlink,
 * and node keeps that launcher path in argv — walking its parents searches the
 * bin tree instead of the installed package. Resolving the link first anchors
 * the walk in the package, while a bundled binary or a direct dist/cli.js
 * launch stays valid.
 *
 * An unresolved version renders no segment rather than a guess: the bar would
 * otherwise state a version the operator cannot act on.
 */
function resolveVersion(entryPath: string = process.argv[1] ?? ""): string {
  let anchor = entryPath
  try {
    anchor = realpathSync(entryPath)
  } catch {
    // A moved install or a transient launcher path still gets the walk below.
  }
  let dir = dirname(anchor)
  for (let depth = 0; depth < 8; depth++) {
    try {
      const pkg = JSON.parse(readFileSync(join(dir, "package.json"), "utf8")) as {
        name?: unknown
        version?: unknown
      }
      // The package name has changed before, so match the stable suffix rather
      // than one exact release spelling.
      if (typeof pkg.name === "string" && pkg.name.includes("coding-agent") && typeof pkg.version === "string") {
        return pkg.version
      }
    } catch {
      // Keep walking toward the package root.
    }
    const parent = dirname(dir)
    if (parent === dir) break
    dir = parent
  }
  return ""
}

/** 452094 -> 452k, 1000000 -> 1.0M — the claude renderer's `human`. */
function human(value: number): string {
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`
  if (value >= 1_000) return `${Math.floor(value / 1_000)}k`
  return `${value}`
}

/** Percentage -> the theme's ok / warn / alert colors, on claude's thresholds. */
function heat(percent: number, warn: number, alert: number): string {
  if (percent >= alert) return "error"
  if (percent >= warn) return "warning"
  return "success"
}

export interface RenderInput {
  git: GitState
  model: string
  effort: string
  contextPercent: number | null
  contextTokens: number | null
  contextWindow: number
  version: string
}

/** Exported for the render test; pi itself only calls the installer below. */
export function renderStatusLine(input: RenderInput, theme: Theme): string {
  const sep = theme.fg("dim", SEP)
  const parts: string[] = []

  if (input.git.project !== "") parts.push(theme.fg("accent", input.git.project))

  if (input.git.branch !== "") {
    let segment = theme.fg("muted", input.git.branch)
    if (input.git.dirty) segment += theme.fg("warning", "●")
    if (input.git.ahead > 0) segment += theme.fg("dim", ` ↑${input.git.ahead}`)
    if (input.git.behind > 0) segment += theme.fg("dim", ` ↓${input.git.behind}`)
    parts.push(segment)
  }

  if (input.model !== "") {
    let segment = theme.fg("text", input.model)
    if (input.effort !== "") segment += ` ${theme.fg("dim", input.effort)}`
    parts.push(segment)
  }

  if (input.contextPercent !== null) {
    const percent = Math.round(input.contextPercent)
    let segment = theme.fg(heat(percent, 60, 80), `${percent}%`)
    segment += theme.fg("dim", " ctx")
    if (input.contextWindow > 0 && input.contextTokens !== null) {
      segment += theme.fg("dim", ` ${human(input.contextTokens)}/${human(input.contextWindow)}`)
    }
    parts.push(segment)
  }

  if (input.git.insertions !== 0 || input.git.deletions !== 0) {
    parts.push(theme.fg("success", `+${input.git.insertions}`) + " " + theme.fg("error", `-${input.git.deletions}`))
  }

  if (input.version !== "") parts.push(theme.fg("dim", input.version))

  return parts.join(sep)
}

export default function (pi: Api): void {
  // Resolved once: the running package cannot change mid-session.
  const version = resolveVersion()
  let git: GitState = EMPTY_GIT
  let requestRender = (): void => {}
  let refresh = (_ctx: Ctx): void => {}
  let installed = false

  const install = (ctx: Ctx): void => {
    // The footer is a TUI surface. A headless run (pi exec, an RPC client)
    // has no setFooter and must be left exactly as it was.
    if (installed || ctx.mode !== "tui" || typeof ctx.ui.setFooter !== "function") return
    installed = true

    refresh = (target: Ctx): void => {
      void probeGit(target.cwd)
        .then((next) => {
          git = next
          requestRender()
        })
        .catch(() => {})
    }

    ctx.ui.setFooter((tui: { requestRender(): void }, theme: Theme, footerData: FooterData) => {
      requestRender = () => tui.requestRender()
      const unsubscribe = footerData.onBranchChange(() => {
        refresh(ctx)
      })
      return {
        dispose: unsubscribe,
        invalidate(): void {},
        render(): string[] {
          const usage = ctx.getContextUsage?.()
          return [
            renderStatusLine(
              {
                // The branch pi already watches beats the probe's copy: it is
                // pushed on checkout, while the probe only catches up on the
                // next turn.
                git: { ...git, branch: footerData.getGitBranch() ?? git.branch },
                model: ctx.model?.name ?? ctx.model?.id ?? "",
                effort: ctx.getThinkingLevel?.() ?? pi.getThinkingLevel?.() ?? "",
                contextPercent: usage?.percent ?? null,
                contextTokens: usage?.tokens ?? null,
                contextWindow: usage?.contextWindow ?? ctx.model?.contextWindow ?? 0,
                version,
              },
              theme,
            ),
          ]
        },
      }
    })
    refresh(ctx)
  }

  // A custom footer is cosmetic: pi must stay usable if any of this throws.
  const guard = (handler: (ctx: Ctx) => void) => async (_event: unknown, ctx: Ctx): Promise<void> => {
    try {
      handler(ctx)
    } catch {
      // Leave pi's own footer in place.
    }
  }

  pi.on("session_start", guard(install))
  // The diff counters and the dirty flag only move when the agent edits, so
  // a turn boundary is the cheapest honest moment to re-probe git. Install
  // is idempotent; a session that started headless and never gets a footer
  // simply keeps returning here.
  pi.on("turn_end", guard((ctx) => {
    install(ctx)
    refresh(ctx)
  }))
}

// installed by herdr
// managed by herdr; reinstalling or updating the integration overwrites this file.
// add custom hooks/plugins beside this file instead of editing it.
// HERDR_INTEGRATION_ID=pi
// HERDR_INTEGRATION_VERSION=8
// @ts-nocheck

import net from "node:net";

const HERDR_ENV = process.env.HERDR_ENV;
const socketPath = process.env.HERDR_SOCKET_PATH;
const socketEndpoint =
  process.platform === "win32" && socketPath ? `\\\\.\\pipe\\${socketPath}` : socketPath;
const paneId = process.env.HERDR_PANE_ID;
const source = "herdr:pi";

function enabled() {
  return HERDR_ENV === "1" && !!socketPath && !!paneId;
}

function sendRequestAttempt(request: unknown, timeoutMs: number): Promise<boolean> {
  if (!enabled()) {
    return Promise.resolve(true);
  }

  return new Promise((resolve) => {
    let done = false;
    let timeout: ReturnType<typeof setTimeout> | undefined;
    const finish = (delivered: boolean) => {
      if (done) return;
      done = true;
      if (timeout) {
        clearTimeout(timeout);
      }
      socket.destroy();
      resolve(delivered);
    };

    const socket = net.createConnection(socketEndpoint!);
    socket.on("error", () => finish(false));
    socket.on("connect", () => socket.write(`${JSON.stringify(request)}\n`));
    socket.on("data", () => finish(true));
    socket.on("end", () => finish(false));
    timeout = setTimeout(() => finish(false), timeoutMs);
    timeout.unref?.();
  });
}

async function sendRequest(request: unknown): Promise<void> {
  if (await sendRequestAttempt(request, 500)) {
    return;
  }
  await sendRequestAttempt(request, 1500);
}

type AgentState = "working" | "blocked" | "idle";

type QueuedState = {
  state: AgentState;
  message?: string;
  seq: number;
};

let reportSeq = Date.now() * 1000;
let currentAgentSessionId: string | undefined;
let currentAgentSessionPath: string | undefined;

function nextReportSeq(): number {
  reportSeq += 1;
  return reportSeq;
}

function updateSessionRef(ctx: any): void {
  try {
    const file = ctx?.sessionManager?.getSessionFile?.();
    currentAgentSessionPath =
      typeof file === "string" && file.startsWith("/") ? file : undefined;
  } catch {
    currentAgentSessionPath = undefined;
  }

  try {
    const id = ctx?.sessionManager?.getSessionId?.();
    currentAgentSessionId = typeof id === "string" && id.length > 0 ? id : undefined;
  } catch {
    currentAgentSessionId = undefined;
  }
}

function withSessionRef(params: Record<string, unknown>): Record<string, unknown> {
  if (currentAgentSessionPath) {
    return { ...params, agent_session_path: currentAgentSessionPath };
  }
  if (currentAgentSessionId) {
    return { ...params, agent_session_id: currentAgentSessionId };
  }
  return params;
}

function currentSessionRef(): Record<string, unknown> | undefined {
  if (currentAgentSessionPath) {
    return { agent_session_path: currentAgentSessionPath };
  }
  if (currentAgentSessionId) {
    return { agent_session_id: currentAgentSessionId };
  }
  return undefined;
}

function reportSession(sessionStartSource?: string): Promise<void> {
  const sessionRef = currentSessionRef();
  if (!sessionRef) {
    return Promise.resolve();
  }

  return sendRequest({
    id: `${source}:session:${Date.now()}:${Math.random().toString(36).slice(2)}`,
    method: "pane.report_agent_session",
    params: {
      pane_id: paneId,
      source,
      agent: "pi",
      seq: nextReportSeq(),
      session_start_source: sessionStartSource,
      ...sessionRef,
    },
  });
}

function sendState(state: AgentState, message?: string, seq = nextReportSeq()): Promise<void> {
  return sendRequest({
    id: `${source}:${Date.now()}:${Math.random().toString(36).slice(2)}`,
    method: "pane.report_agent",
    params: withSessionRef({
      pane_id: paneId,
      source,
      agent: "pi",
      state,
      message,
      seq,
    }),
  });
}

let sendInFlight = false;
let queuedState: QueuedState | undefined;

function queueState(state: AgentState, message?: string): void {
  queuedState = { state, message, seq: nextReportSeq() };
  if (!sendInFlight) {
    void drainStateQueue();
  }
}

async function drainStateQueue(): Promise<void> {
  if (sendInFlight) {
    return;
  }

  sendInFlight = true;
  try {
    while (queuedState) {
      const next = queuedState;
      queuedState = undefined;
      await sendState(next.state, next.message, next.seq);
    }
  } finally {
    sendInFlight = false;
    if (queuedState) {
      void drainStateQueue();
    }
  }
}

export default function (pi) {
  if (!enabled()) {
    return;
  }

  let agentActive = false;
  let blockedCount = 0;
  let blockedMessage: string | undefined;
  let lastState: AgentState | undefined;
  let lastMessage: string | undefined;
  let rootSession = false;

  function desiredState() {
    if (blockedCount > 0) {
      return { state: "blocked" as const, message: blockedMessage };
    }
    if (agentActive) {
      return { state: "working" as const, message: undefined };
    }
    return { state: "idle" as const, message: undefined };
  }

  function publishState(force = false) {
    const next = desiredState();
    if (!force && next.state === lastState && next.message === lastMessage) {
      return;
    }
    lastState = next.state;
    lastMessage = next.message;
    queueState(next.state, next.message);
  }

  pi.events.on("herdr:blocked", (data) => {
    if (!rootSession) {
      return;
    }
    if (!data?.active) {
      blockedCount = Math.max(0, blockedCount - 1);
      if (blockedCount === 0) {
        blockedMessage = undefined;
      }
      publishState();
      return;
    }

    blockedCount += 1;
    blockedMessage = data.label;
    publishState();
  });

  pi.on("session_start", async (event, ctx) => {
    // TUI only: RPC/JSON/print modes are headless (no PTY herdr can display),
    // and RPC still reports hasUI=true, so mode is the reliable gate.
    if (ctx?.mode !== "tui") {
      return;
    }
    rootSession = true;
    updateSessionRef(ctx);
    await reportSession(event?.reason);
    // A reload can replace this extension mid-run without emitting another agent_start.
    agentActive = ctx?.isIdle?.() === false;
    publishState(true);
  });

  pi.on("agent_start", (_event, ctx) => {
    if (!rootSession) {
      return;
    }
    updateSessionRef(ctx);
    void reportSession();
    agentActive = true;
    publishState();
  });

  pi.on("agent_settled", (_event, ctx) => {
    if (!rootSession || ctx?.isIdle?.() !== true) {
      return;
    }

    agentActive = false;
    publishState();
  });
}

import * as fs from "node:fs";
import * as path from "node:path";
import { parentPort } from "node:worker_threads";

const ACTIVE_RUN_INDEX_DIR = ".active-runs";
const RESULT_TOMBSTONE_PREFIX = ".deleting-result-";

function compareRelative(left, right) {
	if (left < right) return -1;
	if (left > right) return 1;
	return 0;
}

function insertSmallest(entries, candidate, limit) {
	if (limit <= 0) return;
	const index = entries.findIndex((entry) => compareRelative(candidate.relative, entry.relative) < 0);
	if (index === -1) entries.push(candidate);
	else entries.splice(index, 0, candidate);
	if (entries.length > limit) entries.pop();
}

function streamDirWindow(dir, limit, after, relativePath, usable) {
	if (limit <= 0) return { entries: [], rawReads: 0, exhausted: true, cursorCleared: false };
	let handle;
	try {
		handle = fs.opendirSync(dir);
		const next = [];
		const wrapped = [];
		let rawReads = 0;
		while (true) {
			const entry = handle.readSync();
			if (!entry) break;
			rawReads += 1;
			const relative = relativePath(entry);
			if (!usable(entry, relative)) continue;
			const candidate = { relative, name: entry.name };
			insertSmallest(wrapped, candidate, limit);
			if (after === undefined || compareRelative(relative, after) > 0) insertSmallest(next, candidate, limit);
		}
		const cursorCleared = after !== undefined && next.length === 0;
		return { entries: cursorCleared ? wrapped : next, rawReads, exhausted: true, cursorCleared };
	} catch (error) {
		if (error?.code === "ENOENT") return { entries: [], rawReads: 0, exhausted: true, cursorCleared: false };
		throw error;
	} finally {
		handle?.closeSync();
	}
}

function discover(request) {
	const startedAt = Date.now();
	const cursor = structuredClone(request.cursor);
	const raw = { reads: 0, exhausted: {} };
	const record = (source, scan) => {
		raw.reads += scan.rawReads;
		raw.exhausted[source] = scan.exhausted;
	};
	const runScan = streamDirWindow(
		request.asyncDirRoot,
		request.runBudget,
		cursor.runAfter,
		(entry) => entry.name,
		(entry) => entry.isDirectory() && entry.name !== ACTIVE_RUN_INDEX_DIR,
	);
	record("runs", runScan);
	if (runScan.cursorCleared) delete cursor.runAfter;
	const runCandidates = runScan.entries.slice(0, request.runBudget);
	for (const candidate of runCandidates) cursor.runAfter = candidate.relative;

	const resultCandidates = [];
	const sourceLimit = Math.max(1, Math.ceil(request.resultBudget / 4));
	const addFiles = (dir, kind, cursorTarget, source, budget = sourceLimit) => {
		const remaining = Math.min(budget, request.resultBudget - resultCandidates.length);
		if (remaining <= 0) return 0;
		const before = resultCandidates.length;
		const after = cursorTarget.type === "pending"
			? cursor.resultPendingAfterBySession?.[cursorTarget.session]
			: cursor[cursorTarget.key];
		const scan = streamDirWindow(
			dir,
			remaining,
			after,
			(entry) => path.relative(request.resultsDir, path.join(dir, entry.name)),
			(entry) => entry.isFile() && (entry.name.startsWith(RESULT_TOMBSTONE_PREFIX) || entry.name.endsWith(".json")),
		);
		record(source, scan);
		if (scan.cursorCleared) {
			if (cursorTarget.type === "pending") delete cursor.resultPendingAfterBySession?.[cursorTarget.session];
			else delete cursor[cursorTarget.key];
		}
		for (const candidate of scan.entries.slice(0, remaining)) {
			const tombstone = candidate.name.startsWith(RESULT_TOMBSTONE_PREFIX);
			resultCandidates.push({
				name: candidate.name,
				relative: candidate.relative,
				kind: tombstone ? "tombstone" : kind,
				cursor: cursorTarget,
			});
			if (cursorTarget.type === "pending") {
				cursor.resultPendingAfterBySession ??= {};
				cursor.resultPendingAfterBySession[cursorTarget.session] = candidate.relative;
			} else cursor[cursorTarget.key] = candidate.relative;
		}
		return resultCandidates.length - before;
	};

	addFiles(request.resultsDir, "public", { type: "result", key: "resultPublicAfter" }, "results.public");
	const pendingRoot = path.join(request.resultsDir, "result-pending");
	const pendingRemaining = Math.min(request.resultBudget, sourceLimit, request.resultBudget - resultCandidates.length);
	const pendingScan = streamDirWindow(
		pendingRoot,
		pendingRemaining,
		cursor.pendingSessionAfter,
		(entry) => entry.name,
		(entry) => entry.isDirectory(),
	);
	record("results.pendingSessions", pendingScan);
	const livePendingSessions = new Set(pendingScan.entries.map((entry) => entry.relative));
	if (cursor.resultPendingAfterBySession) {
		let pruned = 0;
		for (const session of Object.keys(cursor.resultPendingAfterBySession).sort()) {
			if (pruned >= request.resultBudget) break;
			if (!livePendingSessions.has(session) && !fs.existsSync(path.join(pendingRoot, session))) {
				delete cursor.resultPendingAfterBySession[session];
				pruned += 1;
			}
		}
		if (Object.keys(cursor.resultPendingAfterBySession).length === 0) delete cursor.resultPendingAfterBySession;
	}
	if (pendingScan.cursorCleared) delete cursor.pendingSessionAfter;
	const pendingSessions = pendingScan.entries.slice(0, pendingRemaining);
	let pendingFileBudget = Math.min(sourceLimit, request.resultBudget - resultCandidates.length);
	for (const session of pendingSessions) {
		if (pendingFileBudget <= 0) break;
		cursor.pendingSessionAfter = session.relative;
		pendingFileBudget -= addFiles(
			path.join(pendingRoot, session.name),
			"pending",
			{ type: "pending", session: session.relative },
			`results.pending.${session.name}`,
			pendingFileBudget,
		);
	}
	addFiles(path.join(request.resultsDir, "completion-replay"), "replay", { type: "result", key: "resultReplayAfter" }, "results.replay");
	addFiles(path.join(request.resultsDir, "output-archives"), "archive", { type: "result", key: "resultArchiveAfter" }, "results.archive");

	const cursorOps = [];
	for (const key of ["runAfter", "resultPublicAfter", "resultReplayAfter", "resultArchiveAfter", "pendingSessionAfter"]) {
		if (cursor[key] === request.cursor[key]) continue;
		cursorOps.push(cursor[key] === undefined ? { type: "delete", key } : { type: "set", key, value: cursor[key] });
	}
	const oldPending = request.cursor.resultPendingAfterBySession ?? {};
	const nextPending = cursor.resultPendingAfterBySession ?? {};
	for (const session of new Set([...Object.keys(oldPending), ...Object.keys(nextPending)])) {
		if (oldPending[session] === nextPending[session]) continue;
		cursorOps.push(nextPending[session] === undefined
			? { type: "delete-pending", session }
			: { type: "set-pending", session, value: nextPending[session] });
	}
	return {
		type: "result",
		passId: request.passId,
		discoveryDurationMs: Math.max(0, Date.now() - startedAt),
		rawReads: raw.reads,
		sourceExhausted: raw.exhausted,
		runCandidates,
		resultCandidates,
		cursorOps,
	};
}

if (!parentPort) throw new Error("Async retention discovery requires a worker parent port.");
parentPort.on("message", (request) => {
	const passId = request?.passId;
	try {
		parentPort.postMessage(discover(request));
	} catch (error) {
		parentPort.postMessage({ type: "error", passId, error: error instanceof Error ? error.message : String(error) });
	}
});

# Workflows and orchestration

How to compose subagents: the recommended pattern, packaged prompt shortcuts, scripted workflows, direct commands, worktree isolation, and child-to-parent coordination.

## Recommended orchestration pattern

Use orchestration as parent-agent guidance, not as a runtime workflow mode. For implementation work, the recommended loop is:

```text
clarify → scout → worker → fresh reviewers → worker
```

Packaged `worker`, `oracle`, and `advisor` default to forked context when a launch omits `context`. If the parent has no persisted session file or current leaf yet, that implicit default falls back to `fresh`. Pass `context: "fresh"` when you intentionally want a fresh child run, or `context: "fork"` when fork must remain strict.

Child-safety boundaries are enforced at runtime:

- Spawned child sessions do not receive the bundled `pi-subagents` skill.
- Forked child context filtering removes parent-only subagent artifacts (including old hidden orchestration-instruction messages, slash/status/control messages, and prior parent `subagent` tool-call/tool-result history) while preserving ordinary prose and unrelated tool calls/results.
- By default, children do not register the `subagent` tool and receive boundary instructions that they are not the parent orchestrator and must not propose or run subagents.
- The explicit exception is an agent whose resolved builtin `tools` includes `subagent`; that child gets a child-safe `subagent` tool for the fanout work the parent assigned, still bounded by `maxSubagentDepth`.

## Prompt shortcuts

The package includes reusable prompt templates for common workflows. You do not need them, but they are handy when you want the same shape every time:

| Prompt | Use it for |
|--------|------------|
| `/parallel-review` | Launch fresh-context reviewers with distinct angles, then synthesize what to fix. |
| `/review-loop` | Run parent-controlled worker, reviewer, and fix-worker cycles until clean or capped. |
| `/parallel-research` | Combine `researcher` and `scout` for external evidence, local code context, and practical tradeoffs. |
| `/gather-context-and-clarify` | Scout/research first, then ask the user the clarification questions that matter. |
| `/parallel-cleanup` | Run review-only cleanup passes after implementation. |

Add `autofix` to `/parallel-review` or `/parallel-cleanup` to apply only the synthesized fixes worth doing now after reviewers return.

## Scripted workflows (workflowScript)

All model-facing subagent execution is expressed through `workflowScript` in the `subagent` tool. Use stable keys and ordinary JavaScript for one child, sequence, and parallelism. For ordinary parallel fanout, use `await runs.all([{ key, agent, task }, ...])`. It resolves to an ordered array, not a key map, so use indexes, destructuring, or `.map(...)`, not `results.<key>`. Do not read `.output` from unawaited `runs.run` launches. Store a `runs.run` promise only when the script later observes it with `await`, `Promise.race`, or `Promise.all`, such as steering a live child before awaiting its result. Scripts are ordinary JavaScript statement bodies. Use an explicit `return` for a useful result:

Child results cross into the script as plain JSON data. Non-JSON host metadata is omitted, so use returned fields such as `runId`, `ok`, `output`, and `structuredOutput` for workflow control.

```js
subagent({ workflowScript: `
  const scan = await runs.run("scan", { agent: "scout", task: "Scan the codebase" });
  const reviews = await runs.all([
    { key: "correctness", agent: "reviewer", task: "Review correctness: " + scan.output },
    { key: "tests", agent: "reviewer", task: "Review tests: " + scan.output }
  ]);
  return reviews.map(result => result.output);
` });
```

Keep helper functions portable across Node and Bun. Use top-level `await`, plain helper functions that return `runs.run(...)`, or explicit Promise chains. Do not define nested `async function` helpers, async arrows, or async methods inside `workflowScript`; native async helpers hide child-launch observation in Bun and are rejected.

```js
subagent({ workflowScript: `
  function scan() {
    return runs.run("scan", { agent: "scout", task: "Scan the codebase" });
  }
  const result = await scan();
  return result.output;
` });
```

Chaining is still supported. The supported form is scripted chaining: await one `runs.run(...)` result, then pass its output into the next step. Parallel fanout uses `runs.all(...)` inside the same script.

```js
subagent({ workflowScript: `
  const plan = await runs.run("plan", { agent: "scout", task: "Plan the migration" });
  const patch = await runs.run("patch", { agent: "worker", task: "Implement this plan:\n" + plan.output });
  return patch.output;
` });
```

### Steering a workflow child

Use `await runs.steer(key, message, options?)` after `runs.run` or `runs.all` has launched that stable key. Scripts do not target raw run ids. The optional fields are `mode: "steer" | "follow_up" | "auto"`, a non-negative child `index`, and a positive `ackTimeoutMs`.

```js
subagent({ workflowScript: `
  const writer = runs.run("writer", { agent: "worker", task: "Implement the change" });
  const evidence = await runs.run("evidence", { agent: "scout", task: "Find the exact contract" });
  const receipt = await runs.steer("writer", "Also check: " + evidence.output, { mode: "follow_up" });
  return { writer: await writer, receipt };
` });
```

The receipt state is `queued`, `delivered`, `missed`, or `failed`. `delivered` means the child Pi session accepted the input. It does not mean the model followed it. `missed` means the keyed child became terminal or had no live route before delivery. This first slice uses the existing foreground and async steering transports but does not start steering recovery. Workflow traces include one steering attempt entry and one receipt entry.

Always await or return a `runs.steer` promise. The workflow waits for an observed steering side effect to settle before it exits and rejects fire-and-forget calls. Use ordinary `Promise.race` when the first child or steering receipt should advance the script. There is no callback API or child inbox access.

### Advanced rolling child runs

`runs.run` starts a keyed child when you call it. You do not need separate `runs.start`, `runs.next`, or `runs.collect` helpers for rolling councils or staged reviews. This is the advanced exception to ordinary `runs.all` fanout: keep launched promises only when the script later observes each one with direct `await`, `Promise.race`, or `Promise.all`. Use `Promise.race` to wait for the next completed child, steer a still-running sibling by its stable key, and use `Promise.all` to collect the remaining children.

```js
subagent({ workflowScript: `
  let pending = [
    { key: "analysis-a", promise: runs.run("analysis-a", { agent: "reviewer", task: "Analyze option A" }).then((result) => ({ key: "analysis-a", result })) },
    { key: "analysis-b", promise: runs.run("analysis-b", { agent: "reviewer", task: "Analyze option B" }).then((result) => ({ key: "analysis-b", result })) },
    { key: "critic", promise: runs.run("critic", { agent: "reviewer", task: "Find the strongest objection" }).then((result) => ({ key: "critic", result })) }
  ];

  const first = await Promise.race(pending.map((child) => child.promise));
  pending = pending.filter((child) => child.key !== first.key);

  const target = pending.find((child) => child.key === "critic") ?? pending[0];
  const receipt = await runs.steer(target.key, "Challenge this early result:\n" + first.result.output, { mode: "auto" });
  const rest = await Promise.all(pending.map((child) => child.promise));

  return { first: first.result.output, rest: rest.map((child) => child.result.output), receipt };
` });
```

The workflow trace records the run completions and steering receipt. Scripts still never see raw async directories, inbox paths, or session files. If the keyed child is terminal, stale, or has no live route when `runs.steer` runs, the receipt reports `missed` or `failed` and the script can decide whether to continue.

Use named outputs when later workflow steps need structured data or durable references:

```js
subagent({ workflowScript: `
  const inventory = await runs.run("inventory", {
    agent: "scout",
    task: "List the files that need review.",
    outputSchema: {
      type: "object",
      properties: { files: { type: "array", items: { type: "string" } } },
      required: ["files"],
      additionalProperties: false
    }
  });
  return runs.run("review", {
    agent: "reviewer",
    task: "Review these files: " + inventory.structuredOutput.files.join(", ")
  });
` });
```

For dynamic fanout, have one step return a structured list, check it in JavaScript, then map the bounded entries into `runs.all(...)`:

```js
subagent({ workflowScript: `
  const targets = await runs.run("targets", {
    agent: "scout",
    task: "Return up to five source files that need review.",
    outputSchema: {
      type: "object",
      properties: { files: { type: "array", items: { type: "string" }, maxItems: 5 } },
      required: ["files"],
      additionalProperties: false
    }
  });
  const files = targets.structuredOutput.files.slice(0, 5);
  return runs.all(files.map((file, index) => ({
    key: "review-" + index,
    agent: "reviewer",
    task: "Review " + file
  })));
` });
```

For intermediate data that only later steps need, prefer the prior child's returned output or `structuredOutput` instead of writing shared files:

```js
subagent({ workflowScript: `
  const scan = await runs.run("scan", { agent: "scout", task: "Find the files that need fixes." });
  return runs.run("fix", { agent: "worker", task: "Implement these findings:\n" + scan.output });
` });
```

`{chain_dir}` remains available inside scripted workflow step templates for legacy-compatible path templates. It expands to the workflow cwd, not to private temporary storage.

### Migrating old chain shapes

Legacy top-level `chain`, `tasks`, `parallel`, `chainDir`, `/chain`, `/parallel`, `/run-chain`, and durable `.chain.md` execution are no longer the public workflow API. Rewrite them as JavaScript:

```js
// Old shape, no longer supported:
// { chain: [{ agent: "scout", task: "Scan" }, { agent: "worker", task: "Fix from {previous}" }] }

// Current shape:
{ workflowScript: `
  const scan = await runs.run("scan", { agent: "scout", task: "Scan" });
  return runs.run("fix", { agent: "worker", task: "Fix from: " + scan.output });
` }
```

```js
// Old shape, no longer supported:
// { tasks: [{ agent: "reviewer", task: "Review API" }, { agent: "reviewer", task: "Review UI" }] }

// Current shape:
{ workflowScript: `
  return runs.all([
    { key: "api", agent: "reviewer", task: "Review API" },
    { key: "ui", agent: "reviewer", task: "Review UI" }
  ]);
` }
```

For long task text with Markdown fences or shell blocks, use quoted lines instead of a raw template literal:

````js
const task = [
  "Run this command:",
  "```bash",
  "npm test",
  "```"
].join("\n");
return runs.run("test", { agent: "worker", task });
````

A plain workflow creates one enclosing mission by default. Its children do not create separate missions. The result exposes the id as `details.missionId`, and human-readable output ends with `Mission: <id> (<status>)`. Pass `mission:false` for an ephemeral workflow with no mission or durable `state` global.

### Repeatable workflows

Use stable child keys and keep process logic in ordinary JavaScript. `runs.run` launches one child, `runs.all` launches independent children together, and later steps can use each completed child's `output`. Put long task text in arrays joined with `"\n"` so Markdown fences do not conflict with the script string.

For a process you run often, save the task as a prompt template under `.pi/prompts/` or `~/.pi/agent/prompts/` and launch it with `/prompt-workflow`. The adapter compiles prompt steps into `workflowScript`, so templates describe the work instead of embedding raw `subagent` tool-call JSON. You can ask the parent agent to create or update these prompt files from a process described in natural language.

```md
---
description: Review a release candidate
subagent: reviewer
fresh: true
---
Review $@. Return concrete findings with source proof, or state that no issue was found.
```

For first-pass review prompts, filter by evidence rather than by severity. Ask the
reviewer to label concrete current findings P0/P1/P2 and end with `Merge verdict:
BLOCK`, `Merge verdict: OK`, or `Merge verdict: OK with notes`. Reserve
`blockers only` for final pre-merge re-checks after P1/P2 findings are already
known, or for explicit emergency hotfix lanes.

```text
/prompt-workflow review-release-candidate v0.51.0
```

For watched same-repo workflows, pass `async:false` only when the parent must block until completion. That blocking mode also shows the live in-chat workflow card. `chatProgress` can force `off` or `live-card` when the automatic policy is not what you want. Blocking workflows default to a 30-minute timeout; async workflows have no default timeout. See the [tool reference](tool-reference.md) for the full parameter list.

The legacy `/chain`, `/parallel`, and `/run-chain` commands are not registered.

## Direct commands

Use `/run <agent> [task] [--bg] [--fork]` for one child.

## Worktree isolation

Scripted workflows can give each writing child a separate managed git worktree by setting `worktree: true` on each `runs.run` / `runs.all` item:

```javascript
const [api, ui] = await runs.all([
  { key: "api", agent: "worker", task: "Implement the API", worktree: true },
  { key: "ui", agent: "worker", task: "Implement the UI", worktree: true }
]);
return { api: api.artifactPaths, ui: ui.artifactPaths };
```

Each child uses the existing worktree lifecycle: it branches from clean HEAD, journals ownership before launch, captures a patch and handoff manifest, then removes cleanly captured temporary worktrees and branches. The handoff manifest path remains available in the child's `artifactPaths`; return or emit it when the orchestrator needs to apply or inspect the patches. `runs.ref` stays concise and intentionally omits full paths.

A top-level `{ workflowScript, worktree: true }` makes isolation the default for every workflow child. An individual child can override that default with `worktree: false`. Keep one writer when parallel writes are not intentionally isolated.

Configure the worktree base directory and setup hook in [configuration.md](configuration.md).

## Supervisor coordination (child asks parent)

Child agents can talk back to the parent Pi session without installing `pi-intercom`. `pi-subagents` provides the child-facing `contact_supervisor` tool and the parent-facing `subagent_supervisor({ action: "reply" })` path natively. Generic `intercom` remains available only when an explicitly loaded external provider supplies it.

Use it for work where the child might need a decision instead of guessing:

```text
Run this implementation in the background. If the worker gets blocked or needs a product decision, have it ask me through the supervisor channel.
```

```text
Ask oracle to review this plan. If it sees a decision I need to make, have it ask me instead of assuming.
```

The child uses one dedicated coordination tool, `contact_supervisor`, with a `reason`:

- `need_decision` — blocking decisions or clarification
- `interview_request` — structured input
- `progress_update` — short non-blocking updates when a discovery changes the plan

Children should not ask for clarification when the only conflict is review-only/no-edit versus progress-writing or artifact-writing instructions; no-edit wins.

The parent replies with `subagent_supervisor({ action: "reply", replyTo, message })` or checks pending requests with `subagent_supervisor({ action: "pending" })`. Supervisor messages are scoped to the exact Pi session id that spawned the child. A second Pi session in the same repository does not receive those requests.

Child-side routine completion handoffs are not expected. If a child appears stalled, needs-attention notices show up in the parent session with useful next actions, such as checking `subagent({ action: "status" })`, interrupting the run, or nudging the child.

If a `workflowScript` child detaches through `contact_supervisor`, the enclosing async workflow stays `paused` until that child exits. Then the extension reconciles it to `complete` or `failed`. Wait on the child until that happens.

If messages do not show up, run `/subagents-doctor`. Advanced users can tune the bridge with `intercomBridge` in [configuration.md](configuration.md).

## Recursion guard

Subagents can call `subagent` only when their resolved builtin tools explicitly include `subagent`. That is meant for delegated fanout agents, not ordinary worker/reviewer children. A depth guard prevents unbounded nesting.

By default, nesting is limited to two levels: main session → subagent → sub-subagent. Deeper calls are blocked with guidance to complete the current task directly. Nested runs appear in the parent status widget and `status` output as a tree, and `status`, `interrupt`, and `resume` can target a nested run by its id.

Configure the limit with:

1. `PI_SUBAGENT_MAX_DEPTH` before starting Pi
2. `config.maxSubagentDepth`
3. `maxSubagentDepth` in agent frontmatter, which can only tighten the inherited limit

```bash
export PI_SUBAGENT_MAX_DEPTH=3
export PI_SUBAGENT_MAX_DEPTH=1
export PI_SUBAGENT_MAX_DEPTH=0
```

`PI_SUBAGENT_DEPTH` is internal and propagated automatically. Do not set it manually.

## Prompt-template integration

`pi-subagents` includes a native prompt-workflow adapter for reusable subagent prompt templates, so you do not need `pi-prompt-template-model` for the common subagent workflow path.

Create a prompt in `.pi/prompts/` or `~/.pi/agent/prompts/`:

```md
---
description: Take a screenshot
model: claude-sonnet-4-20250514
subagent: browser-screenshoter
cwd: /tmp/screenshots
---
Use url in the prompt to take screenshot: $@
```

Then run it through the native adapter:

```text
/prompt-workflow take-screenshot https://example.com
```

The adapter delegates to the named subagent, applies `model`, `skill`, `cwd`, and fork/fresh context metadata, and supports runtime overrides such as `--subagent reviewer`, `--fork`, `--fresh`, and `--bg`.

Prompt templates with `chain:` frontmatter are translated into `workflowScript` and launched through `/prompt-workflow`; `/chain-prompts` is no longer registered.

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import type {} from "./src/types/pi-runtime-compat.d.ts";

const registerParentExtension = process.env.PI_SUBAGENT_CHILD === "1"
	? undefined
	: (await import("./src/extension/index.ts")).default;

export default function registerSubagentExtension(pi: ExtensionAPI): void {
	registerParentExtension?.(pi);
}

import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url);
const { runInspector } = await jiti.import("./src/inspectors/herdr/inspector-runner.ts");

try {
	runInspector();
} catch (cause) {
	process.stderr.write(`Herdr inspector failed: ${cause instanceof Error ? cause.message : String(cause)}\n`);
	process.exitCode = 1;
}

#!/usr/bin/env node

/**
 * pi-subagents installer
 * 
 * Usage:
 *   npx pi-subagents          # Install to ~/.pi/agent/extensions/subagent
 *   npx pi-subagents --remove # Remove the extension
 */

import { execSync } from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";

const EXTENSION_DIR = path.join(os.homedir(), ".pi", "agent", "extensions", "subagent");
const REPO_URL = "https://github.com/nicobailon/pi-subagents.git";

const args = process.argv.slice(2);
const isRemove = args.includes("--remove") || args.includes("-r");
const isHelp = args.includes("--help") || args.includes("-h");

if (isHelp) {
	console.log(`
pi-subagents - Pi extension for delegating tasks to subagents

Usage:
  npx pi-subagents          Install the extension
  npx pi-subagents --remove Remove the extension
  npx pi-subagents --help   Show this help

Installation directory: ${EXTENSION_DIR}
`);
	process.exit(0);
}

if (isRemove) {
	if (fs.existsSync(EXTENSION_DIR)) {
		console.log(`Removing ${EXTENSION_DIR}...`);
		fs.rmSync(EXTENSION_DIR, { recursive: true });
		console.log("pi-subagents removed");
	} else {
		console.log("pi-subagents is not installed");
	}
	process.exit(0);
}

// Install
console.log("Installing pi-subagents...\n");

// Ensure parent directory exists
const parentDir = path.dirname(EXTENSION_DIR);
if (!fs.existsSync(parentDir)) {
	fs.mkdirSync(parentDir, { recursive: true });
}

// Check if already installed
if (fs.existsSync(EXTENSION_DIR)) {
	const isGitRepo = fs.existsSync(path.join(EXTENSION_DIR, ".git"));
	if (isGitRepo) {
		console.log("Updating existing installation...");
		try {
			execSync("git pull", { cwd: EXTENSION_DIR, stdio: "inherit" });
			console.log("\npi-subagents updated");
		} catch (err) {
			console.error("Failed to update. Try removing and reinstalling:");
			console.error("  npx pi-subagents --remove && npx pi-subagents");
			process.exit(1);
		}
	} else {
		console.log(`Directory exists but is not a git repo: ${EXTENSION_DIR}`);
		console.log("Remove it first with: npx pi-subagents --remove");
		process.exit(1);
	}
} else {
	// Fresh install
	console.log(`Cloning to ${EXTENSION_DIR}...`);
	try {
		execSync(`git clone ${REPO_URL} "${EXTENSION_DIR}"`, { stdio: "inherit" });
		console.log("\npi-subagents installed");
	} catch (err) {
		console.error("Failed to clone repository");
		process.exit(1);
	}
}

console.log(`
The extension is now available in pi. Tools added:
  • subagent - Delegate tasks to agents and inspect run status
  • subagent_wait - Block until background subagent runs finish (delivers their results)

Documentation: ${EXTENSION_DIR}/README.md
`);

