type BuiltinAgentName = typeof BUILTIN_AGENT_NAMES[number];
export type ProfileKind = "quota" | "quality";
export type ProbeStatus = "ok" | "unavailable" | "auth" | "timeout" | "error" | "skipped";
export type CostTier = "cheap" | "medium" | "expensive";
export type QualityTier = "weak" | "medium" | "strong";
export type LatencyTier = "fast" | "medium" | "slow";
export type RecommendedRoleTier = "cheap" | "medium" | "strong";

interface ProfileAgentOverride {
	model?: string;
	thinking?: string | false;
	fallbackModels?: string[] | false;
}

export interface SubagentProfileFile {
	subagents: {
		agentOverrides: Record<string, ProfileAgentOverride>;
		disableBuiltins?: boolean;
		[key: string]: unknown;
	};
}

export type ClassificationSource = "official-metadata" | "heuristic-name";

export interface ProviderModelCatalogModel {
	id: string;
	fullId: string;
	observed: {
		availableInRegistry: boolean;
		name?: string;
		reasoning?: boolean;
		thinkingLevels: string[];
		contextWindow?: number;
		maxTokens?: number;
		cost?: {
			input?: number;
			output?: number;
			cacheRead?: number;
			cacheWrite?: number;
		};
		probe: {
			status: ProbeStatus;
			checkedAt: string;
			message?: string;
		};
	};
	derived: {
		profileRank: number;
		costTier: CostTier;
		qualityTier: QualityTier;
		latencyTier: LatencyTier;
		recommendedRoleTier: RecommendedRoleTier;
		recommendedAgents: BuiltinAgentName[];
		classificationSources: ClassificationSource[];
	};
	warnings: string[];
	notes: string[];
}

export interface ProviderModelCatalogFile {
	provider: string;
	refreshedAt: string;
	maxAgeDays: number;
	sources: string[];
	models: ProviderModelCatalogModel[];
}

export interface ProfileCheckResult {
	profileName: string;
	filePath: string;
	results: Array<{
		agent: string;
		model: string;
		inRegistry: boolean;
		probe: { status: ProbeStatus; message?: string };
	}>;
}

function readJsonObjectFile(filePath: string): Record<string, unknown> {
	const raw = fs.readFileSync(filePath, "utf-8");
	const parsed = JSON.parse(raw) as unknown;
	if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
		throw new Error(`File '${filePath}' must contain a JSON object.`);
	}
	return parsed as Record<string, unknown>;
}

function writeJsonFile(filePath: string, value: unknown): void {
	fs.mkdirSync(path.dirname(filePath), { recursive: true });
	fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`, "utf-8");
}

const SAFE_PATH_TOKEN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

function normalizePathToken(value: string, label: string): string {
	const trimmed = value.trim();
	if (!trimmed) throw new Error(`${label} is required.`);
	if (!SAFE_PATH_TOKEN.test(trimmed) || trimmed === "." || trimmed === ".." || trimmed.includes("/") || trimmed.includes("\\")) {
		throw new Error(`${label} must be a safe file name using only letters, numbers, dots, underscores, and hyphens.`);
	}
	return trimmed;
}

function normalizeProfileName(name: string): string {
	const trimmed = name.trim();
	const stem = trimmed.endsWith(".json") ? trimmed.slice(0, -5) : trimmed;
	return normalizePathToken(stem, "Profile name");
}

function normalizeProviderName(provider: string): string {
	return normalizePathToken(provider, "Provider");
}

function validateSubagentProfile(filePath: string, parsed: Record<string, unknown>): SubagentProfileFile {
	const subagents = parsed.subagents;
	if (!subagents || typeof subagents !== "object" || Array.isArray(subagents)) {
		throw new Error(`Profile '${filePath}' must contain a 'subagents' object.`);
	}
	const agentOverrides = (subagents as Record<string, unknown>).agentOverrides;
	if (!agentOverrides || typeof agentOverrides !== "object" || Array.isArray(agentOverrides)) {
		throw new Error(`Profile '${filePath}' must contain 'subagents.agentOverrides' as an object.`);
	}
	for (const [name, value] of Object.entries(agentOverrides)) {
		if (!value || typeof value !== "object" || Array.isArray(value)) {
			throw new Error(`Profile '${filePath}' has invalid override '${name}'; expected an object.`);
		}
		const override = value as Record<string, unknown>;
		const model = override.model;
		if (model !== undefined && typeof model !== "string") {
			throw new Error(`Profile '${filePath}' has invalid model for '${name}'; expected a string.`);
		}
		const thinking = override.thinking;
		if (thinking !== undefined && thinking !== false && typeof thinking !== "string") {
			throw new Error(`Profile '${filePath}' has invalid thinking for '${name}'; expected a string or false.`);
		}
		const fallbackModels = override.fallbackModels;
		if (fallbackModels !== undefined && fallbackModels !== false && (!Array.isArray(fallbackModels) || fallbackModels.some((item) => typeof item !== "string"))) {
			throw new Error(`Profile '${filePath}' has invalid fallbackModels for '${name}'; expected an array of strings or false.`);
		}
	}
	const disableBuiltins = (subagents as Record<string, unknown>).disableBuiltins;
	if (disableBuiltins !== undefined && typeof disableBuiltins !== "boolean") {
		throw new Error(`Profile '${filePath}' has invalid subagents.disableBuiltins; expected a boolean.`);
	}
	return parsed as unknown as SubagentProfileFile;
}

function getUserSettingsPath(): string {
	return path.join(getAgentDir(), "settings.json");
}

function readSettingsFile(filePath: string): Record<string, unknown> {
	if (!fs.existsSync(filePath)) return {};
	return readJsonObjectFile(filePath);
}

function extractVersionScore(id: string): number {
	const match = id.match(/(\d+(?:\.\d+)?)/g);
	if (!match || match.length === 0) return 0;
	return Math.max(...match.map((value) => Number.parseFloat(value)).filter((value) => Number.isFinite(value)));
}

function modelNameTokens(modelName: string): string[] {
	return modelName
		.toLowerCase()
		.replace(/([a-z])([0-9])/g, "$1 $2")
		.replace(/([0-9])([a-z])/g, "$1 $2")
		.split(/[^a-z0-9.]+/)
		.filter(Boolean);
}

function inferProfileBand(modelName: string): 0 | 1 | 2 | 3 | 4 {
	const tokens = new Set(modelNameTokens(modelName));
	if (["spark", "flash", "nano", "tiny", "instant"].some((token) => tokens.has(token))) return 0;
	if (["mini", "haiku", "small"].some((token) => tokens.has(token))) return 1;
	if (["opus", "max", "ultra", "pro"].some((token) => tokens.has(token))) return 4;
	if (["sonnet", "turbo", "plus"].some((token) => tokens.has(token))) return 3;
	return 2;
}

interface ModelClassificationInput {
	id: string;
	name?: string;
	reasoning?: boolean;
	contextWindow?: number;
	maxTokens?: number;
	cost?: {
		input?: number;
		output?: number;
		cacheRead?: number;
		cacheWrite?: number;
	};
}

interface NumericStats {
	min: number;
	max: number;
}

interface ClassificationContext {
	cost?: NumericStats;
	contextWindow?: NumericStats;
	maxTokens?: NumericStats;
}

function combinedCost(cost: ModelClassificationInput["cost"]): number | undefined {
	if (!cost) return undefined;
	const values = [cost.input, cost.output, cost.cacheRead, cost.cacheWrite].filter((value): value is number => typeof value === "number" && Number.isFinite(value));
	if (values.length === 0) return undefined;
	return values.reduce((sum, value) => sum + value, 0);
}

function collectStats(values: Array<number | undefined>): NumericStats | undefined {
	const filtered = values.filter((value): value is number => typeof value === "number" && Number.isFinite(value));
	if (filtered.length === 0) return undefined;
	return { min: Math.min(...filtered), max: Math.max(...filtered) };
}

function normalize(value: number | undefined, stats: NumericStats | undefined): number | undefined {
	if (value === undefined || !stats) return undefined;
	if (stats.max <= stats.min) return 0.5;
	return (value - stats.min) / (stats.max - stats.min);
}

function buildClassificationContext(models: ModelClassificationInput[]): ClassificationContext {
	return {
		cost: collectStats(models.map((model) => combinedCost(model.cost))),
		contextWindow: collectStats(models.map((model) => model.contextWindow)),
		maxTokens: collectStats(models.map((model) => model.maxTokens)),
	};
}

function rankToCostTier(rank: number): CostTier {
	if (rank <= 0.33) return "cheap";
	if (rank <= 0.66) return "medium";
	return "expensive";
}

function scoreToQualityTier(score: number): QualityTier {
	if (score <= 0.33) return "weak";
	if (score <= 0.66) return "medium";
	return "strong";
}

function qualityTierToRoleTier(quality: QualityTier, cost: CostTier): RecommendedRoleTier {
	if (quality === "strong") return "strong";
	if (quality === "medium") return cost === "cheap" ? "cheap" : "medium";
	return "cheap";
}

function agentsForRoleTier(roleTier: RecommendedRoleTier): BuiltinAgentName[] {
	if (roleTier === "cheap") return ["scout", "delegate"];
	if (roleTier === "medium") return ["researcher", "reviewer"];
	return ["worker", "reviewer", "oracle"];
}

function classifyModel(input: ModelClassificationInput, context: ClassificationContext): {
	profileRank: number;
	costTier: CostTier;
	qualityTier: QualityTier;
	latencyTier: LatencyTier;
	recommendedRoleTier: RecommendedRoleTier;
	recommendedAgents: BuiltinAgentName[];
	classificationSources: ClassificationSource[];
} {
	const modelName = input.name?.trim() || input.id;
	const tokens = new Set(modelNameTokens(modelName));
	const band = inferProfileBand(modelName);
	const versionScore = extractVersionScore(input.id);
	const costNorm = normalize(combinedCost(input.cost), context.cost);
	const contextNorm = normalize(input.contextWindow, context.contextWindow);
	const maxTokensNorm = normalize(input.maxTokens, context.maxTokens);
	const hasOfficialMetadata = costNorm !== undefined || contextNorm !== undefined || maxTokensNorm !== undefined;
	const classificationSources: ClassificationSource[] = hasOfficialMetadata
		? ["official-metadata", "heuristic-name"]
		: ["heuristic-name"];
	const heuristicBase = band / 4;
	const qualitySignals = [
		heuristicBase,
		...(contextNorm !== undefined ? [contextNorm] : []),
		...(maxTokensNorm !== undefined ? [maxTokensNorm] : []),
		...(input.reasoning === true ? [1] : []),
		...(input.reasoning === false ? [0] : []),
	];
	const latencyHintsFast = tokens.has("highspeed") || tokens.has("flash") || tokens.has("instant") || tokens.has("turbo");
	const latencyHintsSlow = tokens.has("pro") || tokens.has("ultra") || tokens.has("opus") || tokens.has("max");
	let qualityScore = qualitySignals.reduce((sum, value) => sum + value, 0) / qualitySignals.length;
	if (latencyHintsFast) {
		qualityScore -= 0.2;
	}
	qualityScore = Math.max(0, Math.min(1, qualityScore));
	const costTier = costNorm !== undefined
		? rankToCostTier(costNorm)
		: band === 0 ? "cheap" : band >= 3 ? "expensive" : "medium";
	const qualityTier = scoreToQualityTier(qualityScore);
	const latencyTier: LatencyTier = latencyHintsFast
		? "fast"
		: latencyHintsSlow
			? "slow"
			: costNorm !== undefined
				? (costNorm <= 0.33 ? "fast" : costNorm <= 0.66 ? "medium" : "slow")
				: (band <= 1 ? "fast" : band >= 3 ? "slow" : "medium");
	const recommendedRoleTier = qualityTierToRoleTier(qualityTier, costTier);
	const latencyPenalty = latencyHintsFast ? 125 : 0;
	const profileRank = Math.round((qualityScore * 100) * 10) + Math.round(versionScore * 25) - latencyPenalty;
	return {
		profileRank,
		costTier,
		qualityTier,
		latencyTier,
		recommendedRoleTier,
		recommendedAgents: agentsForRoleTier(recommendedRoleTier),
		classificationSources,
	};
}

function resolveProbeStatus(text: string, timedOut: boolean): ProbeStatus {
	if (timedOut) return "timeout";
	if (!text) return "error";
	if (/(unauthori[sz]ed|forbidden|api key|auth|billing|credit|quota)/i.test(text)) return "auth";
	if (/(not found|unknown model|model unavailable|model disabled|unsupported model|unavailable)/i.test(text)) return "unavailable";
	return "error";
}

async function probeModel(
	pi: Pick<ExtensionAPI, "exec"> | { exec?: ExtensionAPI["exec"] },
	ctx: Pick<ExtensionContext, "cwd">,
	fullId: string,
): Promise<{ status: ProbeStatus; message?: string }> {
	if (typeof pi.exec !== "function") {
		return { status: "skipped", message: "pi.exec is unavailable in this runtime." };
	}
	const spawnSpec = getPiSpawnCommand(["-p", "--model", fullId, "--no-tools", 'Reply with exactly "OK".']);
	const result = await pi.exec(spawnSpec.command, spawnSpec.args, {
		cwd: os.tmpdir(),
		timeout: 45_000,
	} as Record<string, unknown>);
	const stdout = typeof result.stdout === "string" ? result.stdout.trim() : "";
	const stderr = typeof result.stderr === "string" ? result.stderr.trim() : "";
	const combined = [stderr, stdout].filter(Boolean).join("\n").trim();
	if (result.code === 0) return { status: "ok", message: stdout || "Probe succeeded." };
	return { status: resolveProbeStatus(combined, result.killed === true), message: combined || `Probe exited with code ${result.code ?? "unknown"}.` };
}

function roundIndex(count: number, position: number): number {
	if (count <= 1) return 0;
	return Math.max(0, Math.min(count - 1, Math.round((count - 1) * position)));
}

function profilePositions(kind: ProfileKind): { cheap: number; medium: number; strong: number } {
	return kind === "quota"
		? { cheap: 0, medium: 1 / 3, strong: 2 / 3 }
		: { cheap: 1 / 3, medium: 2 / 3, strong: 1 };
}

function pickTierModels(models: ProviderModelCatalogModel[], kind: ProfileKind): { cheap: string; medium: string; strong: string } {
	if (models.length === 0) throw new Error("No provider models are available for profile generation.");
	const selectionPool = kind === "quota" && models.length > 1
		? models.slice(0, -1)
		: models;
	const positions = profilePositions(kind);
	return {
		cheap: selectionPool[roundIndex(selectionPool.length, positions.cheap)]!.fullId,
		medium: selectionPool[roundIndex(selectionPool.length, positions.medium)]!.fullId,
		strong: selectionPool[roundIndex(selectionPool.length, positions.strong)]!.fullId,
	};
}

function observedCombinedCost(model: ProviderModelCatalogModel): number | undefined {
	return combinedCost(model.observed.cost);
}

function dominatesModel(a: ProviderModelCatalogModel, b: ProviderModelCatalogModel): boolean {
	const costA = observedCombinedCost(a);
	const costB = observedCombinedCost(b);
	if (costA === undefined || costB === undefined) return false;
	if (costA > costB) return false;
	if (a.derived.profileRank < b.derived.profileRank) return false;
	if ((a.observed.reasoning === true ? 1 : 0) < (b.observed.reasoning === true ? 1 : 0)) return false;
	if ((a.observed.contextWindow ?? 0) < (b.observed.contextWindow ?? 0)) return false;
	if ((a.observed.maxTokens ?? 0) < (b.observed.maxTokens ?? 0)) return false;
	return costA < costB
		|| a.derived.profileRank > b.derived.profileRank
		|| (a.observed.reasoning === true && b.observed.reasoning !== true)
		|| (a.observed.contextWindow ?? 0) > (b.observed.contextWindow ?? 0)
		|| (a.observed.maxTokens ?? 0) > (b.observed.maxTokens ?? 0);
}

function filterDominatedModels(models: ProviderModelCatalogModel[]): ProviderModelCatalogModel[] {
	return models.filter((candidate, index) => !models.some((other, otherIndex) => otherIndex !== index && dominatesModel(other, candidate)));
}

function buildProfileFile(kind: ProfileKind, models: { cheap: string; medium: string; strong: string }): SubagentProfileFile {
	return {
		subagents: {
			agentOverrides: {
				scout: { model: models.cheap },
				delegate: { model: models.cheap },
				researcher: { model: models.medium },
				worker: { model: models.strong },
				reviewer: { model: models.strong },
				oracle: { model: models.strong },
			},
		},
	};
}

function catalogModelIsUsable(model: ProviderModelCatalogModel): boolean {
	return model.observed.availableInRegistry && model.observed.probe.status !== "unavailable" && model.observed.probe.status !== "auth" && model.observed.probe.status !== "timeout" && model.observed.probe.status !== "error";
}

function modelUsesHeuristicClassification(model: ProviderModelCatalogModel): boolean {
	return model.derived.classificationSources.includes("heuristic-name")
		&& !model.derived.classificationSources.includes("official-metadata");
}

function warningLineForHeuristicFallback(): string {
	return "Classification fell back to name heuristics.";
}

export function countHeuristicFallbackModels(catalog: ProviderModelCatalogFile): number {
	return catalog.models.filter(modelUsesHeuristicClassification).length;
}

function resolveProfilePath(name: string): string {
	const dir = ensureSubagentProfilesDir();
	return path.join(dir, `${normalizeProfileName(name)}.json`);
}

export function getSubagentProfilesRootDir(): string {
	return path.join(getAgentDir(), "profiles", "pi-subagents");
}

export function getSubagentProfilesDir(): string {
	return getSubagentProfilesRootDir();
}

export function ensureSubagentProfilesDir(): string {
	const dir = getSubagentProfilesDir();
	fs.mkdirSync(dir, { recursive: true });
	return dir;
}

export function getProviderModelsDir(): string {
	return path.join(getSubagentProfilesRootDir(), "providers");
}

export function ensureProviderModelsDir(): string {
	const dir = getProviderModelsDir();
	fs.mkdirSync(dir, { recursive: true });
	return dir;
}

export function getProviderModelsPath(provider: string): string {
	return path.join(ensureProviderModelsDir(), `${normalizeProviderName(provider)}.models.json`);
}

export function listSubagentProfiles(): string[] {
	const dir = ensureSubagentProfilesDir();
	return fs.readdirSync(dir, { withFileTypes: true })
		.filter((entry) => entry.isFile() && entry.name.endsWith(".json"))
		.map((entry) => entry.name.slice(0, -5))
		.sort((a, b) => a.localeCompare(b));
}

export function readSubagentProfile(name: string): { filePath: string; profile: SubagentProfileFile } {
	const filePath = resolveProfilePath(name);
	if (!fs.existsSync(filePath)) throw new Error(`Profile not found: ${name}`);
	const parsed = readJsonObjectFile(filePath);
	return { filePath, profile: validateSubagentProfile(filePath, parsed) };
}

export function applySubagentProfile(name: string): { filePath: string; settingsPath: string } {
	const { filePath, profile } = readSubagentProfile(name);
	const settingsPath = getUserSettingsPath();
	const settings = readSettingsFile(settingsPath);
	const existing = settings.subagents && typeof settings.subagents === "object" && !Array.isArray(settings.subagents)
		? settings.subagents as Record<string, unknown>
		: {};
	// A profile owns the complete agent mapping, but unrelated subagent settings
	// (notably disableBuiltins, modelScope, watchdog, etc.) survive profile switches.
	settings.subagents = {
		...existing,
		...profile.subagents,
		agentOverrides: profile.subagents.agentOverrides,
	};
	writeJsonFile(settingsPath, settings);
	return { filePath, settingsPath };
}

export function readProviderModelCatalog(provider: string): ProviderModelCatalogFile | null {
	const filePath = getProviderModelsPath(provider);
	if (!fs.existsSync(filePath)) return null;
	return readJsonObjectFile(filePath) as unknown as ProviderModelCatalogFile;
}

export function isProviderModelCatalogStale(catalog: ProviderModelCatalogFile, maxAgeDays = DEFAULT_PROVIDER_MODELS_MAX_AGE_DAYS): boolean {
	const refreshedAt = Date.parse(catalog.refreshedAt);
	if (!Number.isFinite(refreshedAt)) return true;
	const maxAgeMs = maxAgeDays * 24 * 60 * 60 * 1000;
	return Date.now() - refreshedAt > maxAgeMs;
}

export async function refreshProviderModelCatalog(
	pi: Pick<ExtensionAPI, "exec"> | { exec?: ExtensionAPI["exec"] },
	ctx: Pick<ExtensionContext, "cwd" | "modelRegistry">,
	provider: string,
	options: { force?: boolean; maxAgeDays?: number; probe?: boolean } = {},
): Promise<{ filePath: string; catalog: ProviderModelCatalogFile; reused: boolean; heuristicFallbackCount: number }> {
	const normalizedProvider = normalizeProviderName(provider);
	const maxAgeDays = options.maxAgeDays ?? DEFAULT_PROVIDER_MODELS_MAX_AGE_DAYS;
	const filePath = getProviderModelsPath(normalizedProvider);
	if (!options.force) {
		const existing = readProviderModelCatalog(normalizedProvider);
		if (existing && !isProviderModelCatalogStale(existing, maxAgeDays)) {
			return { filePath, catalog: existing, reused: true, heuristicFallbackCount: countHeuristicFallbackModels(existing) };
		}
	}

	const availableModels = ctx.modelRegistry.getAvailable().filter((model) => model.provider === normalizedProvider);
	if (availableModels.length === 0) {
		throw new Error(`No models found in the current registry for provider '${normalizedProvider}'.`);
	}

	const observedModels = [] as Array<{
		rawModel: typeof availableModels[number];
		modelRecord: Record<string, unknown> & { provider: string; id: string; name?: string };
		fullId: string;
		probe: { status: ProbeStatus; message?: string };
	}>;
	for (const rawModel of availableModels) {
		const modelRecord = rawModel as unknown as Record<string, unknown> & { provider: string; id: string; name?: string };
		const fullId = `${modelRecord.provider}/${modelRecord.id}`;
		const probe = options.probe === false
			? { status: "skipped" as const, message: "Live probing disabled." }
			: await probeModel(pi, ctx, fullId);
		observedModels.push({ rawModel, modelRecord, fullId, probe });
	}
	const classificationContext = buildClassificationContext(observedModels.map(({ modelRecord }) => ({
		id: modelRecord.id,
		...(typeof modelRecord.name === "string" ? { name: modelRecord.name } : {}),
		...(typeof modelRecord.reasoning === "boolean" ? { reasoning: modelRecord.reasoning } : {}),
		...(typeof modelRecord.contextWindow === "number" ? { contextWindow: modelRecord.contextWindow } : {}),
		...(typeof modelRecord.maxTokens === "number" ? { maxTokens: modelRecord.maxTokens } : {}),
		...(modelRecord.cost && typeof modelRecord.cost === "object" ? { cost: modelRecord.cost as ProviderModelCatalogModel["observed"]["cost"] } : {}),
	})));
	const models: ProviderModelCatalogModel[] = [];
	for (const { rawModel, modelRecord, fullId, probe } of observedModels) {
		const classification = classifyModel({
			id: modelRecord.id,
			...(typeof modelRecord.name === "string" ? { name: modelRecord.name } : {}),
			...(typeof modelRecord.reasoning === "boolean" ? { reasoning: modelRecord.reasoning } : {}),
			...(typeof modelRecord.contextWindow === "number" ? { contextWindow: modelRecord.contextWindow } : {}),
			...(typeof modelRecord.maxTokens === "number" ? { maxTokens: modelRecord.maxTokens } : {}),
			...(modelRecord.cost && typeof modelRecord.cost === "object" ? { cost: modelRecord.cost as ProviderModelCatalogModel["observed"]["cost"] } : {}),
		}, classificationContext);
		const warnings = classification.classificationSources.includes("heuristic-name") && !classification.classificationSources.includes("official-metadata")
			? [warningLineForHeuristicFallback()]
			: [];
		models.push({
			id: modelRecord.id,
			fullId,
			observed: {
				availableInRegistry: true,
				...(typeof modelRecord.name === "string" ? { name: modelRecord.name } : {}),
				...(typeof modelRecord.reasoning === "boolean" ? { reasoning: modelRecord.reasoning } : {}),
				thinkingLevels: getSupportedThinkingLevels(toModelInfo(rawModel)).map((level) => level),
				...(typeof modelRecord.contextWindow === "number" ? { contextWindow: modelRecord.contextWindow } : {}),
				...(typeof modelRecord.maxTokens === "number" ? { maxTokens: modelRecord.maxTokens } : {}),
				...(modelRecord.cost && typeof modelRecord.cost === "object" ? { cost: modelRecord.cost as ProviderModelCatalogModel["observed"]["cost"] } : {}),
				probe: {
					status: probe.status,
					checkedAt: new Date().toISOString(),
					...(probe.message ? { message: probe.message } : {}),
				},
			},
			derived: classification,
			warnings,
			notes: [],
		});
	}
	models.sort((a, b) => a.derived.profileRank - b.derived.profileRank || a.fullId.localeCompare(b.fullId));
	const catalog: ProviderModelCatalogFile = {
		provider: normalizedProvider,
		refreshedAt: new Date().toISOString(),
		maxAgeDays,
		sources: ["runtime-registry", ...(options.probe === false ? [] : ["live-probe"]), "heuristic-classifier"],
		models,
	};
	writeJsonFile(filePath, catalog);
	return { filePath, catalog, reused: false, heuristicFallbackCount: countHeuristicFallbackModels(catalog) };
}

export async function generateProfilesForProvider(
	pi: Pick<ExtensionAPI, "exec"> | { exec?: ExtensionAPI["exec"] },
	ctx: Pick<ExtensionContext, "cwd" | "modelRegistry">,
	provider: string,
	options: { maxAgeDays?: number; forceRefresh?: boolean; probe?: boolean } = {},
): Promise<{ quotaPath: string; qualityPath: string; catalogPath: string; quotaModels: { cheap: string; medium: string; strong: string }; qualityModels: { cheap: string; medium: string; strong: string }; heuristicFallbackCount: number; selectedHeuristicFallbackCount: number }> {
	const normalizedProvider = normalizeProviderName(provider);
	const { filePath: catalogPath, catalog, heuristicFallbackCount } = await refreshProviderModelCatalog(pi, ctx, normalizedProvider, {
		maxAgeDays: options.maxAgeDays,
		force: options.forceRefresh,
		probe: options.probe,
	});
	const usableModels = catalog.models.filter(catalogModelIsUsable);
	const profileModels = filterDominatedModels(usableModels);
	if (profileModels.length === 0) {
		throw new Error(`Provider '${normalizedProvider}' has no usable models after filtering.`);
	}
	const quotaModels = pickTierModels(profileModels, "quota");
	const qualityModels = pickTierModels(profileModels, "quality");
	const dir = ensureSubagentProfilesDir();
	const quotaPath = path.join(dir, `${normalizedProvider}.quota.json`);
	const qualityPath = path.join(dir, `${normalizedProvider}.quality.json`);
	writeJsonFile(quotaPath, buildProfileFile("quota", quotaModels));
	writeJsonFile(qualityPath, buildProfileFile("quality", qualityModels));
	const selectedModels = new Set([...Object.values(quotaModels), ...Object.values(qualityModels)]);
	const selectedHeuristicFallbackCount = profileModels.filter((model) => selectedModels.has(model.fullId) && modelUsesHeuristicClassification(model)).length;
	return { quotaPath, qualityPath, catalogPath, quotaModels, qualityModels, heuristicFallbackCount, selectedHeuristicFallbackCount };
}

export async function checkSubagentProfile(
	pi: Pick<ExtensionAPI, "exec"> | { exec?: ExtensionAPI["exec"] },
	ctx: Pick<ExtensionContext, "cwd" | "modelRegistry">,
	name: string,
): Promise<ProfileCheckResult> {
	const { filePath, profile } = readSubagentProfile(name);
	const availableModels = ctx.modelRegistry.getAvailable().map(toModelInfo);
	const entries = Object.entries(profile.subagents.agentOverrides)
		.filter(([, value]) => typeof value?.model === "string" && value.model.trim())
		.map(([agent, value]) => ({ agent, model: value.model!.trim() }));
	const probeCache = new Map<string, { status: ProbeStatus; message?: string }>();
	const results: ProfileCheckResult["results"] = [];
	for (const entry of entries) {
		const modelInfo = findModelInfo(entry.model, availableModels);
		const { thinkingSuffix } = splitKnownThinkingSuffix(entry.model);
		const probeModelId = modelInfo ? `${modelInfo.fullId}${thinkingSuffix}` : entry.model;
		let probe = probeCache.get(probeModelId);
		if (!probe) {
			probe = await probeModel(pi, ctx, probeModelId);
			probeCache.set(probeModelId, probe);
		}
		results.push({
			agent: entry.agent,
			model: entry.model,
			inRegistry: modelInfo !== undefined,
			probe,
		});
	}
	return { profileName: name, filePath, results };
}

import { createHash, randomUUID } from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import { writePrivateAtomicJson } from "../../shared/atomic-json.ts";
import { TEMP_ROOT_DIR, type ActiveAsyncCapacitySnapshot, type AsyncStatus } from "../../shared/types.ts";
import { readStatus } from "../../shared/utils.ts";
import { readProcessTerminal } from "./process-terminal.ts";

export const ACTIVE_ASYNC_CAPACITY_DIR = path.join(TEMP_ROOT_DIR, "session-active-async-capacity");

export interface ActiveAsyncCapacityOwnerV1 {
	version: 1;
	reservationToken: string;
	ownerSessionId: string;
	ownerSessionKey: string;
	slot: number;
	runId: string;
	sourceRunId?: string;
	generation: number;
	kind: "runner" | "workflow";
	asyncDir: string;
	reservedAt: number;
	runnerProcessInstanceId?: string;
	runnerStartedAt?: number;
}

export interface ActiveAsyncCapacityHandle {
	readonly owner: ActiveAsyncCapacityOwnerV1;
	markStarted(runnerProcessInstanceId: string): void;
	markWorkflowStarted(): void;
	rollback(): boolean;
	reconcile(liveWorkflowRunIds?: ReadonlySet<string>): ActiveAsyncCapacitySnapshot;
}

interface CapacityOptions {
	rootDir?: string;
	now?: () => number;
	token?: () => string;
	afterSlotRename?: (releasedDir: string) => void;
}

export type ActiveAsyncCapacityReleaseVerdict =
	| { state: "releasable"; reason: string }
	| { state: "retained"; reason: string }
	| { state: "not-owned"; reason: string };

export interface ActiveAsyncCapacityInspection {
	owner?: ActiveAsyncCapacityOwnerV1;
	relation: "current" | "source" | "none";
	slotDir?: string;
	release: ActiveAsyncCapacityReleaseVerdict;
}

export class ActiveAsyncCapacityError extends Error {
	readonly snapshot: ActiveAsyncCapacitySnapshot;

	constructor(snapshot: ActiveAsyncCapacitySnapshot) {
		super(`Active async run capacity exhausted: ${snapshot.used}/${snapshot.limit} used.`);
		this.name = "ActiveAsyncCapacityError";
		this.snapshot = snapshot;
	}
}

export function resolveMaxActiveAsyncRunsPerSession(value: unknown): number | undefined {
	if (typeof value !== "number" || !Number.isInteger(value) || value < 0) return undefined;
	return value === 0 ? undefined : value;
}

export function activeAsyncCapacitySessionKey(sessionId: string): string {
	return createHash("sha256").update(sessionId).digest("hex");
}

function sessionDir(sessionId: string, rootDir: string): string {
	return path.join(rootDir, activeAsyncCapacitySessionKey(sessionId));
}

function slotDir(poolDir: string, slot: number): string {
	return path.join(poolDir, `slot-${slot}`);
}

function parseOwner(value: unknown): ActiveAsyncCapacityOwnerV1 | undefined {
	if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
	const owner = value as Partial<ActiveAsyncCapacityOwnerV1>;
	if (owner.version !== 1
		|| typeof owner.reservationToken !== "string" || !owner.reservationToken
		|| typeof owner.ownerSessionId !== "string" || !owner.ownerSessionId
		|| typeof owner.ownerSessionKey !== "string" || !owner.ownerSessionKey
		|| typeof owner.slot !== "number" || !Number.isInteger(owner.slot) || owner.slot < 0
		|| typeof owner.runId !== "string" || !owner.runId
		|| typeof owner.generation !== "number" || !Number.isInteger(owner.generation) || owner.generation < 0
		|| (owner.kind !== "runner" && owner.kind !== "workflow")
		|| typeof owner.asyncDir !== "string" || !owner.asyncDir
		|| typeof owner.reservedAt !== "number" || !Number.isFinite(owner.reservedAt)) return undefined;
	if (owner.sourceRunId !== undefined && typeof owner.sourceRunId !== "string") return undefined;
	if (owner.runnerProcessInstanceId !== undefined && (typeof owner.runnerProcessInstanceId !== "string" || !owner.runnerProcessInstanceId)) return undefined;
	if (owner.runnerStartedAt !== undefined && (typeof owner.runnerStartedAt !== "number" || !Number.isFinite(owner.runnerStartedAt))) return undefined;
	return owner as ActiveAsyncCapacityOwnerV1;
}

function readOwner(dir: string): ActiveAsyncCapacityOwnerV1 | undefined {
	try {
		return parseOwner(JSON.parse(fs.readFileSync(path.join(dir, "owner.json"), "utf-8")));
	} catch {
		return undefined;
	}
}

function occupiedSlots(poolDir: string): string[] {
	try {
		return fs.readdirSync(poolDir, { withFileTypes: true })
			.filter((entry) => entry.isDirectory() && /^slot-\d+$/.test(entry.name))
			.map((entry) => path.join(poolDir, entry.name));
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
		throw error;
	}
}

function snapshotFor(sessionId: string, limit: number | undefined, rootDir: string): ActiveAsyncCapacitySnapshot {
	return { used: occupiedSlots(sessionDir(sessionId, rootDir)).length, limit: limit ?? 0 };
}

function matchingOwner(dir: string, expected: ActiveAsyncCapacityOwnerV1): ActiveAsyncCapacityOwnerV1 | undefined {
	const owner = readOwner(dir);
	return owner?.reservationToken === expected.reservationToken
		&& owner.runId === expected.runId
		&& owner.generation === expected.generation
		? owner
		: undefined;
}

function withSlotClaim<T>(dir: string, operation: () => T): { acquired: true; value: T } | { acquired: false } {
	const claimPath = path.join(dir, "capacity.claim");
	const claimToken = randomUUID();
	let claim: number | undefined;
	try {
		claim = fs.openSync(claimPath, "wx", 0o600);
		fs.writeFileSync(claim, claimToken, "utf-8");
		fs.closeSync(claim);
		claim = undefined;
	} catch (error) {
		if (claim !== undefined) fs.closeSync(claim);
		if ((error as NodeJS.ErrnoException).code === "EEXIST" || (error as NodeJS.ErrnoException).code === "ENOENT") return { acquired: false };
		throw error;
	}
	try {
		return { acquired: true, value: operation() };
	} finally {
		try {
			if (fs.readFileSync(claimPath, "utf-8") === claimToken) fs.rmSync(claimPath, { force: true });
		} catch (error) {
			if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
		}
	}
}

function removeOwnedSlot(dir: string, expected: ActiveAsyncCapacityOwnerV1, options: CapacityOptions, requireUnstarted = false): boolean {
	if (requireUnstarted && (expected.runnerProcessInstanceId || expected.runnerStartedAt)) return false;
	const claimed = withSlotClaim(dir, () => {
		const current = matchingOwner(dir, expected);
		if (!current || (requireUnstarted && (current.runnerProcessInstanceId || current.runnerStartedAt))) return false;
		const releasedDir = path.join(path.dirname(dir), `.${path.basename(dir)}.released-${randomUUID()}`);
		fs.renameSync(dir, releasedDir);
		options.afterSlotRename?.(releasedDir);
		fs.rmSync(releasedDir, { recursive: true, force: true });
		return true;
	});
	return claimed.acquired && claimed.value;
}

function terminalState(state: AsyncStatus["state"]): boolean {
	return state !== "queued" && state !== "running" && state !== "paused";
}

function runnerReleaseVerdict(owner: ActiveAsyncCapacityOwnerV1, status: AsyncStatus | null): ActiveAsyncCapacityReleaseVerdict {
	if (!status) return { state: "retained", reason: "status file is missing or unreadable" };
	if (!owner.runnerProcessInstanceId) return { state: "retained", reason: "runner process identity has not been recorded" };
	if (status.sessionId !== owner.ownerSessionId) return { state: "retained", reason: `status session ${status.sessionId ?? "unknown"} does not match owner session ${owner.ownerSessionId}` };
	if (status.runId !== owner.runId) return { state: "retained", reason: `status run ${status.runId} does not match owner run ${owner.runId}` };
	if (!terminalState(status.state)) return { state: "retained", reason: `run is still ${status.state}` };
	if (status.processTerminal?.state === "not-started"
		&& status.processTerminal.runId === owner.runId
		&& status.processTerminal.runnerProcessInstanceId === owner.runnerProcessInstanceId
		&& typeof status.error === "string"
		&& status.error) return { state: "releasable", reason: "run failed before child startup completed" };
	const proof = readProcessTerminal(owner.asyncDir, {
		runId: owner.runId,
		runnerProcessInstanceId: owner.runnerProcessInstanceId,
	});
	return proof?.state === "observed"
		&& proof.runId === owner.runId
		&& proof.runnerProcessInstanceId === owner.runnerProcessInstanceId
		? { state: "releasable", reason: "matching observed process-terminal proof is present" }
		: { state: "retained", reason: `process-terminal proof is ${proof?.state ?? "missing"}` };
}

function workflowReleaseVerdict(owner: ActiveAsyncCapacityOwnerV1, status: AsyncStatus | null, liveWorkflowRunIds: ReadonlySet<string>): ActiveAsyncCapacityReleaseVerdict {
	if (!status) return { state: "retained", reason: "status file is missing or unreadable" };
	if (status.sessionId !== owner.ownerSessionId) return { state: "retained", reason: `status session ${status.sessionId ?? "unknown"} does not match owner session ${owner.ownerSessionId}` };
	if (status.runId !== owner.runId) return { state: "retained", reason: `status run ${status.runId} does not match owner run ${owner.runId}` };
	if (status.mode !== "workflow") return { state: "retained", reason: `status mode is ${status.mode}, not workflow` };
	if (!terminalState(status.state)) return { state: "retained", reason: `workflow is still ${status.state}` };
	if (liveWorkflowRunIds.has(owner.runId)) return { state: "retained", reason: "workflow controller is still live" };
	for (const step of status.steps ?? []) {
		const label = step.workflowKey ?? step.agent;
		if (step.status === "pending" || step.status === "running" || step.status === "paused") return { state: "retained", reason: `workflow child ${label} is still ${step.status}` };
		if (typeof step.async !== "boolean") return { state: "retained", reason: `workflow child ${label} is missing async classification` };
		if (!step.async) continue;
		if (!step.runId) return { state: "retained", reason: `async workflow child ${label} is missing run id` };
		const childDir = path.join(path.dirname(owner.asyncDir), step.runId);
		if (!fs.existsSync(childDir)) return { state: "retained", reason: `async workflow child ${label} directory is missing` };
		const childStatus = readStatus(childDir);
		if (!childStatus) return { state: "retained", reason: `async workflow child ${label} status is missing or unreadable` };
		if (!terminalState(childStatus.state)) return { state: "retained", reason: `async workflow child ${label} is still ${childStatus.state}` };
		if (!childStatus.processTerminal?.runnerProcessInstanceId) return { state: "retained", reason: `async workflow child ${label} has no runner process identity` };
		const proof = readProcessTerminal(childDir, {
			runId: step.runId,
			runnerProcessInstanceId: childStatus.processTerminal.runnerProcessInstanceId,
		});
		if (proof?.state !== "observed" || proof.runId !== step.runId) return { state: "retained", reason: `async workflow child ${label} process-terminal proof is ${proof?.state ?? "missing"}` };
	}
	return { state: "releasable", reason: "workflow is terminal, controller is gone, and async children have observed proof" };
}

function ownerReleaseVerdict(owner: ActiveAsyncCapacityOwnerV1, liveWorkflowRunIds: ReadonlySet<string>): ActiveAsyncCapacityReleaseVerdict {
	const status = readStatus(owner.asyncDir);
	return owner.kind === "runner"
		? runnerReleaseVerdict(owner, status)
		: workflowReleaseVerdict(owner, status, liveWorkflowRunIds);
}

function capacitySessionDirs(rootDir: string, sessionId?: string): string[] {
	if (sessionId) return [sessionDir(sessionId, rootDir)];
	try {
		return fs.readdirSync(rootDir, { withFileTypes: true })
			.filter((entry) => entry.isDirectory())
			.map((entry) => path.join(rootDir, entry.name));
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
		throw error;
	}
}

export function inspectActiveAsyncCapacityOwner(
	input: { runId: string; sessionId?: string; asyncDir?: string },
	options: CapacityOptions & { liveWorkflowRunIds?: ReadonlySet<string> } = {},
): ActiveAsyncCapacityInspection {
	const rootDir = options.rootDir ?? ACTIVE_ASYNC_CAPACITY_DIR;
	const liveWorkflowRunIds = options.liveWorkflowRunIds ?? new Set<string>();
	for (const poolDir of capacitySessionDirs(rootDir, input.sessionId)) {
		for (const dir of occupiedSlots(poolDir)) {
			const owner = readOwner(dir);
			if (!owner) continue;
			const sameRun = owner.runId === input.runId || (input.asyncDir !== undefined && path.resolve(owner.asyncDir) === path.resolve(input.asyncDir));
			const sourceRun = owner.sourceRunId === input.runId;
			if (!sameRun && !sourceRun) continue;
			if (sourceRun && !sameRun) {
				return {
					owner,
					relation: "source",
					slotDir: dir,
					release: { state: "not-owned", reason: `slot was transferred to ${owner.runId}` },
				};
			}
			return { owner, relation: "current", slotDir: dir, release: ownerReleaseVerdict(owner, liveWorkflowRunIds) };
		}
	}
	return { relation: "none", release: { state: "not-owned", reason: "no active-capacity slot records this run" } };
}

export function reconcileActiveAsyncCapacity(
	sessionId: string,
	limit: number | undefined,
	options: CapacityOptions & { liveWorkflowRunIds?: ReadonlySet<string> } = {},
): ActiveAsyncCapacitySnapshot {
	const rootDir = options.rootDir ?? ACTIVE_ASYNC_CAPACITY_DIR;
	const poolDir = sessionDir(sessionId, rootDir);
	const liveWorkflowRunIds = options.liveWorkflowRunIds ?? new Set<string>();
	for (const dir of occupiedSlots(poolDir)) {
		const owner = readOwner(dir);
		if (!owner
			|| owner.ownerSessionId !== sessionId
			|| owner.ownerSessionKey !== activeAsyncCapacitySessionKey(sessionId)
			|| path.basename(dir) !== `slot-${owner.slot}`
			|| ownerReleaseVerdict(owner, liveWorkflowRunIds).state !== "releasable") continue;
		removeOwnedSlot(dir, owner, options);
	}
	return snapshotFor(sessionId, limit, rootDir);
}

export function getActiveAsyncCapacitySnapshot(
	sessionId: string,
	limit: number | undefined,
	options: CapacityOptions & { liveWorkflowRunIds?: ReadonlySet<string> } = {},
): ActiveAsyncCapacitySnapshot {
	return reconcileActiveAsyncCapacity(sessionId, limit, options);
}

function createSlot(poolDir: string, owner: ActiveAsyncCapacityOwnerV1): boolean {
	const destination = slotDir(poolDir, owner.slot);
	fs.mkdirSync(poolDir, { recursive: true, mode: 0o700 });
	try {
		fs.mkdirSync(destination, { mode: 0o700 });
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "EEXIST") return false;
		throw error;
	}
	// If owner persistence fails, the corrupt occupied directory remains and
	// fails closed instead of becoming available to another admission.
	fs.writeFileSync(path.join(destination, "owner.json"), `${JSON.stringify(owner, null, 2)}\n`, { encoding: "utf-8", mode: 0o600 });
	return true;
}

function handleFor(owner: ActiveAsyncCapacityOwnerV1, limit: number, options: CapacityOptions, rollbackOwner?: ActiveAsyncCapacityOwnerV1): ActiveAsyncCapacityHandle {
	const rootDir = options.rootDir ?? ACTIVE_ASYNC_CAPACITY_DIR;
	const dir = slotDir(sessionDir(owner.ownerSessionId, rootDir), owner.slot);
	return {
		owner,
		markStarted(runnerProcessInstanceId) {
			const claimed = withSlotClaim(dir, () => {
				const current = matchingOwner(dir, owner);
				if (!current) return false;
				const next = { ...current, runnerProcessInstanceId, runnerStartedAt: options.now?.() ?? Date.now() };
				// Mark memory first. If persistence fails after the process starts, caller
				// cleanup must retain the occupied slot instead of rolling it back.
				Object.assign(owner, next);
				try {
					writePrivateAtomicJson(path.join(dir, "owner.json"), next);
				} catch (error) {
					console.error(`Failed to bind active async capacity to runner '${runnerProcessInstanceId}'; capacity will remain occupied:`, error);
				}
				return true;
			});
			if (!claimed.acquired || !claimed.value) throw new Error(`Active async capacity ownership changed for run '${owner.runId}'.`);
		},
		markWorkflowStarted() {
			const claimed = withSlotClaim(dir, () => {
				const current = matchingOwner(dir, owner);
				if (!current || current.kind !== "workflow") return false;
				const next = { ...current, runnerStartedAt: options.now?.() ?? Date.now() };
				Object.assign(owner, next);
				try {
					writePrivateAtomicJson(path.join(dir, "owner.json"), next);
				} catch (error) {
					console.error(`Failed to mark async workflow '${owner.runId}' started; capacity will remain occupied:`, error);
				}
				return true;
			});
			if (!claimed.acquired || !claimed.value) throw new Error(`Active async capacity ownership changed for workflow '${owner.runId}'.`);
		},
		rollback() {
			if (!rollbackOwner) return removeOwnedSlot(dir, owner, options, true);
			if (owner.runnerProcessInstanceId || owner.runnerStartedAt) return false;
			const claimed = withSlotClaim(dir, () => {
				const current = matchingOwner(dir, owner);
				if (!current || current.runnerProcessInstanceId || current.runnerStartedAt) return false;
				writePrivateAtomicJson(path.join(dir, "owner.json"), rollbackOwner);
				Object.assign(owner, rollbackOwner);
				return true;
			});
			return claimed.acquired && claimed.value;
		},
		reconcile(liveWorkflowRunIds) {
			return reconcileActiveAsyncCapacity(owner.ownerSessionId, limit, { ...options, rootDir, liveWorkflowRunIds });
		},
	};
}

export function acquireActiveAsyncCapacity(
	input: { sessionId: string; limit: number | undefined; runId: string; kind: "runner" | "workflow"; asyncDir: string },
	options: CapacityOptions & { liveWorkflowRunIds?: ReadonlySet<string> } = {},
): ActiveAsyncCapacityHandle | undefined {
	if (input.limit === undefined) return undefined;
	const rootDir = options.rootDir ?? ACTIVE_ASYNC_CAPACITY_DIR;
	const reconciled = reconcileActiveAsyncCapacity(input.sessionId, input.limit, options);
	if (reconciled.used >= input.limit) throw new ActiveAsyncCapacityError(reconciled);
	const poolDir = sessionDir(input.sessionId, rootDir);
	const token = options.token?.() ?? randomUUID();
	for (let slot = 0; slot < input.limit; slot++) {
		const owner: ActiveAsyncCapacityOwnerV1 = {
			version: 1,
			reservationToken: token,
			ownerSessionId: input.sessionId,
			ownerSessionKey: activeAsyncCapacitySessionKey(input.sessionId),
			slot,
			runId: input.runId,
			generation: 0,
			kind: input.kind,
			asyncDir: input.asyncDir,
			reservedAt: options.now?.() ?? Date.now(),
		};
		if (createSlot(poolDir, owner)) return handleFor(owner, input.limit, { ...options, rootDir });
	}
	throw new ActiveAsyncCapacityError(snapshotFor(input.sessionId, input.limit, rootDir));
}

export function transferActiveAsyncCapacity(
	input: { sessionId: string; limit: number | undefined; sourceRunId: string; runId: string; asyncDir: string },
	options: CapacityOptions = {},
): ActiveAsyncCapacityHandle | undefined {
	const limit = input.limit ?? 0;
	const rootDir = options.rootDir ?? ACTIVE_ASYNC_CAPACITY_DIR;
	const poolDir = sessionDir(input.sessionId, rootDir);
	for (const dir of occupiedSlots(poolDir)) {
		const source = readOwner(dir);
		if (!source || source.ownerSessionId !== input.sessionId || source.runId !== input.sourceRunId) continue;
		const claimed = withSlotClaim(dir, () => {
			const current = matchingOwner(dir, source);
			const status = readStatus(source.asyncDir);
			if (!current || !status || status.runId !== input.sourceRunId || status.state === "queued" || status.state === "running") {
				throw new Error(`Active async capacity source '${input.sourceRunId}' is not transferable.`);
			}
			const next: ActiveAsyncCapacityOwnerV1 = {
				...current,
				runId: input.runId,
				sourceRunId: input.sourceRunId,
				generation: current.generation + 1,
				kind: "runner",
				asyncDir: input.asyncDir,
				reservedAt: options.now?.() ?? Date.now(),
			};
			delete next.runnerProcessInstanceId;
			delete next.runnerStartedAt;
			writePrivateAtomicJson(path.join(dir, "owner.json"), next);
			return handleFor(next, limit, { ...options, rootDir }, current);
		});
		if (!claimed.acquired) throw new Error(`Active async capacity transfer is already in progress for run '${input.sourceRunId}'.`);
		return claimed.value;
	}
	return acquireActiveAsyncCapacity({ sessionId: input.sessionId, limit: input.limit, runId: input.runId, kind: "runner", asyncDir: input.asyncDir }, options);
}

import * as fs from "node:fs";
import * as path from "node:path";
import type { AsyncStatus } from "../../shared/types.ts";
import { readStatus } from "../../shared/utils.ts";
import { encodeIndexSegment } from "./index-segment.ts";
import { updateTerminalRunIndex } from "./terminal-run-index.ts";
import { isStorageCapacityError } from "../../shared/file-system-retry.ts";

export const ACTIVE_RUN_INDEX_DIR = ".active-runs";
export const DEFAULT_STALE_TERMINAL_ACTIVE_MARKER_MS = 24 * 60 * 60 * 1000;

const TOOL_CALL_INDEX_DIR = "tool-calls";

function indexDir(asyncDirRoot: string): string {
	return path.join(asyncDirRoot, ACTIVE_RUN_INDEX_DIR);
}

function toolCallIndexDir(asyncDirRoot: string, toolCallId: string): string {
	return path.join(indexDir(asyncDirRoot), TOOL_CALL_INDEX_DIR, encodeIndexSegment(toolCallId));
}

function toolCallIndexPath(asyncDir: string, toolCallId: string): string {
	return path.join(toolCallIndexDir(path.dirname(asyncDir), toolCallId), path.basename(asyncDir));
}

function markerPath(asyncDir: string): string {
	return path.join(indexDir(path.dirname(asyncDir)), path.basename(asyncDir));
}

function removeEmptyAncestors(start: string, stop: string): void {
	let current = start;
	while (current !== stop && current.startsWith(`${stop}${path.sep}`)) {
		try {
			fs.rmdirSync(current);
		} catch {
			return;
		}
		current = path.dirname(current);
	}
}

export function isActiveAsyncState(state: AsyncStatus["state"]): boolean {
	return state === "queued" || state === "running";
}

function releaseToolCallAliases(asyncDir: string): void {
	const root = path.join(indexDir(path.dirname(asyncDir)), TOOL_CALL_INDEX_DIR);
	let entries: fs.Dirent[];
	try {
		entries = fs.readdirSync(root, { withFileTypes: true });
	} catch (error) {
		const code = (error as NodeJS.ErrnoException).code;
		if (code !== "ENOENT" && code !== "ENOTDIR") {
			console.error(`Failed to inspect async active-run tool-call index root '${root}':`, error);
		}
		return;
	}
	for (const entry of entries) {
		if (!entry.isDirectory()) continue;
		const aliasMarker = path.join(root, entry.name, path.basename(asyncDir));
		try {
			fs.rmSync(aliasMarker, { force: true });
			removeEmptyAncestors(path.dirname(aliasMarker), root);
		} catch {
			// Alias cleanup must not affect the authoritative active-run marker.
		}
	}
}

export function releaseActiveRunIndex(asyncDir: string): void {
	try {
		fs.rmSync(markerPath(asyncDir));
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
	}
	releaseToolCallAliases(asyncDir);
}

export function updateActiveRunIndex(asyncDir: string, state: AsyncStatus["state"], toolCallId?: string, options: { retryCapacityErrors?: boolean } = {}): void {
	const marker = markerPath(asyncDir);
	if (isActiveAsyncState(state)) {
		fs.mkdirSync(path.dirname(marker), { recursive: true });
		fs.writeFileSync(marker, "", { flag: "a" });
		if (toolCallId) {
			try {
				const toolCallMarker = toolCallIndexPath(asyncDir, toolCallId);
				fs.mkdirSync(path.dirname(toolCallMarker), { recursive: true });
				fs.writeFileSync(toolCallMarker, "", { flag: "a" });
			} catch (error) {
				// Tool-call aliases are optional. The authoritative active-run marker
				// must keep the launch discoverable even when alias indexing fails.
				console.error(`Failed to write async active-run tool-call index for '${asyncDir}':`, error);
			}
		}
		return;
	}
	releaseActiveRunIndex(asyncDir);
	const status = readStatus(asyncDir);
	if (status && status.state === state) {
		try {
			updateTerminalRunIndex(asyncDir, status);
		} catch (error) {
			if (options.retryCapacityErrors && isStorageCapacityError(error)) throw error;
			console.error(`Failed to write async terminal-run index for '${asyncDir}':`, error);
		}
	}
}

export function activeRunMarkerAgeMs(asyncDir: string, now = Date.now()): number | undefined {
	try {
		return Math.max(0, now - fs.statSync(markerPath(asyncDir)).mtimeMs);
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
		throw error;
	}
}

export function readActiveRunIndex(asyncDirRoot: string): string[] | undefined {
	try {
		return fs.readdirSync(indexDir(asyncDirRoot), { withFileTypes: true })
			.filter((entry) => entry.isFile())
			.map((entry) => entry.name);
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
		throw error;
	}
}

export function readActiveRunToolCallIndex(asyncDirRoot: string, toolCallId: string): string[] {
	try {
		return fs.readdirSync(toolCallIndexDir(asyncDirRoot, toolCallId), { withFileTypes: true })
			.filter((entry) => entry.isFile())
			.map((entry) => entry.name);
	} catch (error) {
		const code = (error as NodeJS.ErrnoException).code;
		if (code === "ENOENT" || code === "ENOTDIR") return [];
		throw error;
	}
}

