interface AsyncJobTrackerOptions {
	completionRetentionMs?: number;
	/** Slow safety sweep for liveness repair when filesystem events are missed. */
	pollIntervalMs?: number;
	resultsDir?: string;
	widgetEnabled?: boolean;
	platform?: NodeJS.Platform;
	onJobTerminal?: () => void;
	watch?: typeof fs.watch;
	kill?: (pid: number, signal?: NodeJS.Signals | 0) => boolean;
	now?: () => number;
}

const CONTROL_EVENT_READ_CHUNK_BYTES = 64 * 1024;
const MAX_CONTROL_EVENT_LINE_BYTES = 1024 * 1024;
const CONTROL_EVENT_SCAN_WINDOW_BYTES = 2 * 1024 * 1024;
const MAX_RECENT_FLEET_JOBS = 20;
const DEFAULT_LIVENESS_INTERVAL_MS = 5000;
const EVENT_REFRESH_DEBOUNCE_MS = 25;
const WATCH_ATTACHMENT_RETRY_MS = 100;

function rememberFleetJob(state: SubagentState, job: AsyncJobState): void {
	state.fleetJobs ??= new Map();
	state.fleetJobs.set(job.asyncId, job);
	const terminal = [...state.fleetJobs.values()]
		.filter((candidate) => candidate.status === "complete" || candidate.status === "failed" || candidate.status === "paused" || candidate.status === "stopped")
		.sort((left, right) => (right.updatedAt ?? right.startedAt ?? 0) - (left.updatedAt ?? left.startedAt ?? 0));
	for (const stale of terminal.slice(MAX_RECENT_FLEET_JOBS)) state.fleetJobs.delete(stale.asyncId);
}

export function createAsyncJobTracker(pi: Pick<ExtensionAPI, "events">, state: SubagentState, asyncDirRoot: string, options: AsyncJobTrackerOptions = {}): {
	ensurePoller: () => void;
	refreshWidget: (ctx: ExtensionContext) => void;
	handleStarted: (data: unknown) => void;
	handleComplete: (data: unknown) => void;
	resetJobs: (ctx?: ExtensionContext) => void;
	restoreActiveJobs: (ctx?: ExtensionContext) => void;
	dispose: () => void;
} {
	const completionRetentionMs = options.completionRetentionMs ?? 10000;
	const livenessIntervalMs = options.pollIntervalMs ?? DEFAULT_LIVENESS_INTERVAL_MS;
	const resultsDir = options.resultsDir ?? DIRS.results;
	const steeringNoticeSeen = new Map<string, number>();
	const jobWatchers = new Map<string, { watchers: Map<string, fs.FSWatcher>; retryTimer?: ReturnType<typeof setTimeout> }>();
	const refreshTimers = new Map<string, ReturnType<typeof setTimeout>>();
	const runningJobIds = new Set<string>();
	let rootWatcher: fs.FSWatcher | undefined;
	let nextLivenessAt = Date.now() + livenessIntervalMs;
	let nextWidgetAnimationAt = Date.now() + WIDGET_ANIMATION_INTERVAL_MS;
	const watch = options.watch ?? fs.watch;
	const useNativeWatcher = () => shouldUseNativeFsWatch("async-job-tracker", options.platform);
	const terminalStatus = (status: string) => status === "complete" || status === "failed" || status === "paused" || status === "stopped";
	const rerenderWidget = (ctx: ExtensionContext, jobs = Array.from(state.asyncJobs.values())) => {
		if (state.widgetsSuspended) return;
		renderWidget(ctx, options.widgetEnabled === false ? [] : jobs);
		(ctx.ui as { requestRender?: () => void }).requestRender?.();
	};
	const rerenderLastWidget = (jobs = Array.from(state.asyncJobs.values())) => {
		const ctx = state.lastUiContext;
		if (!ctx) return;
		try {
			if (ctx.hasUI) rerenderWidget(ctx, jobs);
		} catch (error) {
			if (error instanceof Error && error.message.includes("extension ctx is stale")) {
				state.lastUiContext = null;
				return;
			}
			throw error;
		}
	};
	const requestLastWidgetRender = () => {
		if (options.widgetEnabled === false) return;
		rerenderLastWidget();
	};
	const refreshWidget = (ctx: ExtensionContext) => rerenderWidget(ctx);
	const restoredControlEventCursor = (asyncDir: string) => {
		try {
			return fs.statSync(path.join(asyncDir, "events.jsonl")).size;
		} catch (error) {
			if ((error as NodeJS.ErrnoException).code === "ENOENT") return 0;
			throw error;
		}
	};
	const findNestedRouteForJob = (runId: string) => {
		try {
			return findNestedRouteForRootId(runId);
		} catch (error) {
			console.error(`Failed to resolve nested event route for '${runId}':`, error);
			return undefined;
		}
	};
	const summaryToJob = (run: AsyncRunSummary): AsyncJobState => {
		const groups = normalizeParallelGroups(run.parallelGroups, run.steps.length, run.chainStepCount ?? run.steps.length);
		const activeGroup = run.currentStep !== undefined
			? groups.find((group) => run.currentStep! >= group.start && run.currentStep! < group.start + group.count)
			: undefined;
		const visibleSteps = activeGroup
			? run.steps.slice(activeGroup.start, activeGroup.start + activeGroup.count).map((step, index) => ({ ...step, index: activeGroup.start + index }))
			: run.steps.map((step, index) => ({ ...step, index }));
		return {
			asyncId: run.id,
			asyncDir: run.asyncDir,
			toolCallId: run.toolCallId,
			status: run.state,
			sessionId: run.sessionId,
			activityState: run.activityState,
			lastActivityAt: run.lastActivityAt,
			currentTool: run.currentTool,
			currentToolStartedAt: run.currentToolStartedAt,
			currentPath: run.currentPath,
			turnCount: run.turnCount,
			toolCount: run.toolCount,
			steering: run.steering,
			mode: run.mode,
			context: run.context,
			cwd: run.cwd,
			sessionRoot: run.sessionRoot,
			agents: visibleSteps.map((step) => step.agent),
			currentStep: run.currentStep,
			chainStepCount: run.chainStepCount,
			parallelGroups: groups,
			steps: visibleSteps,
			stepsTotal: visibleSteps.length,
			runningSteps: visibleSteps.filter((step) => step.status === "running").length,
			completedSteps: visibleSteps.filter((step) => step.status === "complete" || step.status === "completed").length,
			hasParallelGroups: groups.length > 0,
			activeParallelGroup: Boolean(activeGroup),
			startedAt: run.startedAt,
			updatedAt: run.lastUpdate ?? run.startedAt,
			timeoutMs: run.timeoutMs,
			deadlineAt: run.deadlineAt,
			timedOut: run.timedOut,
			stopped: run.stopped,
			turnBudget: run.turnBudget,
			turnBudgetExceeded: run.turnBudgetExceeded,
			wrapUpRequested: run.wrapUpRequested,
			sessionDir: run.sessionDir,
			outputFile: run.outputFile,
			totalTokens: run.totalTokens,
			sessionFile: run.sessionFile,
			controlEventCursor: restoredControlEventCursor(run.asyncDir),
			nestedRoute: findNestedRouteForJob(run.id),
			nestedChildren: run.nestedChildren,
			parentWorkflowRunId: run.parentWorkflowRunId,
			workflowKey: run.workflowKey,
			workflow: run.workflow,
		};
	};
	const cancelCleanup = (asyncId: string) => {
		const existingTimer = state.cleanupTimers.get(asyncId);
		if (!existingTimer) return;
		clearTimeout(existingTimer);
		state.cleanupTimers.delete(asyncId);
	};
	const scheduleCleanup = (asyncId: string) => {
		cancelCleanup(asyncId);
		const timer = setTimeout(() => {
			state.cleanupTimers.delete(asyncId);
			closeJobWatcher(asyncId);
			state.asyncJobs.delete(asyncId);
			rerenderLastWidget();
		}, completionRetentionMs);
		state.cleanupTimers.set(asyncId, timer);
	};
	const emitNewControlEvents = (job: AsyncJobState) => {
		const eventsPath = path.join(job.asyncDir, "events.jsonl");
		let fd: number;
		try {
			fd = fs.openSync(eventsPath, "r");
		} catch (error) {
			if ((error as NodeJS.ErrnoException).code === "ENOENT") return;
			console.error(`Failed to open async control events for '${job.asyncDir}':`, error);
			return;
		}
		try {
			const stat = fs.fstatSync(fd);
			const savedCursor = job.controlEventCursor;
			let cursor = stat.size < (savedCursor ?? 0) ? 0 : (savedCursor ?? 0);
			const startedFromTail = savedCursor === undefined && stat.size > CONTROL_EVENT_SCAN_WINDOW_BYTES;
			if (startedFromTail) cursor = stat.size - CONTROL_EVENT_SCAN_WINDOW_BYTES;
			if (stat.size <= cursor) return;
			const previousByte = Buffer.alloc(1);
			const startsMidLine = cursor > 0
				&& fs.readSync(fd, previousByte, 0, 1, cursor - 1) === 1
				&& previousByte[0] !== 0x0a;
			const scanEnd = Math.min(stat.size, cursor + CONTROL_EVENT_SCAN_WINDOW_BYTES);
			const handleLine = (line: string) => {
				if (!line.trim()) return;
				let parsed: unknown;
				try {
					parsed = JSON.parse(line);
				} catch (error) {
					console.error(`Ignoring malformed async control event in '${eventsPath}':`, error);
					return;
				}
				if (!parsed || typeof parsed !== "object") return;
				if ((parsed as { type?: unknown }).type === "subagent.child-status") {
					const event = parsed as Partial<SubagentChildStatusEvent>;
					if (event.version !== 1 || typeof event.runId !== "string" || typeof event.childId !== "string" || (event.status !== "stopping" && event.status !== "stopped") || typeof event.ts !== "number") return;
					pi.events.emit(SUBAGENT_CHILD_STATUS_EVENT, {
						type: "subagent.child-status",
						version: 1,
						runId: event.runId,
						childId: event.childId,
						status: event.status,
						ts: event.ts,
						...(typeof event.reason === "string" ? { reason: event.reason } : {}),
						source: event.source === "rpc" ? "rpc" : "async",
						asyncDir: job.asyncDir,
						...(typeof event.stepIndex === "number" ? { stepIndex: event.stepIndex } : {}),
						...(typeof event.agent === "string" ? { agent: event.agent } : {}),
						...(typeof event.childRunId === "string" ? { childRunId: event.childRunId } : {}),
						...(typeof event.workflowKey === "string" ? { workflowKey: event.workflowKey } : {}),
						...(typeof event.phase === "string" ? { phase: event.phase } : {}),
						...(typeof event.label === "string" ? { label: event.label } : {}),
					} satisfies SubagentChildStatusEvent);
					return;
				}
				if ((parsed as { type?: unknown }).type === "subagent.steering.notice") {
					const notice = parsed as Partial<SteeringNotice>;
					if (typeof notice.requestId !== "string" || typeof notice.runId !== "string" || (notice.state !== "failed" && notice.state !== "partial" && notice.state !== "recovered") || typeof notice.message !== "string") return;
					if (typeof state.currentSessionId === "string" && notice.currentSessionId !== state.currentSessionId) return;
					const key = `${notice.runId}:${notice.requestId}:${notice.state}`;
					if (steeringNoticeSeen.has(key)) return;
					const now = Date.now();
					steeringNoticeSeen.set(key, now);
					if (steeringNoticeSeen.size > 200) {
						for (const [seenKey, seenAt] of steeringNoticeSeen) {
							if (now - seenAt > 10 * 60 * 1000 || steeringNoticeSeen.size > 200) steeringNoticeSeen.delete(seenKey);
						}
					}
					pi.events.emit(SUBAGENT_STEERING_NOTICE_EVENT, { ...notice, source: "async", asyncDir: job.asyncDir, noticeText: notice.message });
					return;
				}
				if ((parsed as { type?: unknown }).type !== "subagent.control") return;
				const record = parsed as { event?: ControlEvent; channels?: string[]; childIntercomTarget?: string; noticeText?: string; intercom?: { to?: string; message?: string } };
				if (!record.event || !Array.isArray(record.channels)) return;
				const payload = {
					event: record.event,
					source: "async" as const,
					asyncDir: job.asyncDir,
					childIntercomTarget: record.childIntercomTarget,
					noticeText: record.noticeText ?? formatControlNoticeMessage(record.event, record.childIntercomTarget),
				};
				if (record.channels.includes("event")) {
					pi.events.emit(SUBAGENT_CONTROL_EVENT, payload);
				}
				if (record.event.type !== "active_long_running" && record.channels.includes("intercom") && record.intercom?.to && record.intercom.message) {
					pi.events.emit(SUBAGENT_CONTROL_INTERCOM_EVENT, {
						...payload,
						to: record.intercom.to,
						message: record.intercom.message,
					});
				}
			};
			let readCursor = cursor;
			let lastCompleteCursor = cursor;
			let lineParts: Buffer[] = [];
			let lineBytes = 0;
			let skippingOversizedLine = startedFromTail || startsMidLine;
			const appendLineSegment = (segment: Buffer) => {
				if (segment.length === 0 || skippingOversizedLine) return;
				if (lineBytes + segment.length > MAX_CONTROL_EVENT_LINE_BYTES) {
					lineParts = [];
					lineBytes = 0;
					skippingOversizedLine = true;
					return;
				}
				lineParts.push(segment);
				lineBytes += segment.length;
			};
			while (readCursor < scanEnd) {
				const toRead = Math.min(CONTROL_EVENT_READ_CHUNK_BYTES, scanEnd - readCursor);
				const buffer = Buffer.alloc(toRead);
				const bytesRead = fs.readSync(fd, buffer, 0, toRead, readCursor);
				if (bytesRead <= 0) break;
				const chunk = bytesRead === buffer.length ? buffer : buffer.subarray(0, bytesRead);
				let lineStart = 0;
				for (let index = 0; index < chunk.length; index++) {
					if (chunk[index] !== 0x0a) continue;
					appendLineSegment(chunk.subarray(lineStart, index));
					if (!skippingOversizedLine && lineBytes > 0) {
						handleLine(Buffer.concat(lineParts, lineBytes).toString("utf-8"));
					}
					lineParts = [];
					lineBytes = 0;
					skippingOversizedLine = false;
					lastCompleteCursor = readCursor + index + 1;
					lineStart = index + 1;
				}
				appendLineSegment(chunk.subarray(lineStart));
				readCursor += bytesRead;
				if (skippingOversizedLine) job.controlEventCursor = readCursor;
			}
			if (lastCompleteCursor > cursor) job.controlEventCursor = lastCompleteCursor;
			else if (scanEnd < stat.size || startedFromTail) job.controlEventCursor = scanEnd;
		} catch (error) {
			console.error(`Failed to read async control events for '${job.asyncDir}':`, error);
		} finally {
			fs.closeSync(fd);
		}
	};

	const closeJobWatcher = (asyncId: string) => {
		const watched = jobWatchers.get(asyncId);
		if (watched?.retryTimer) clearTimeout(watched.retryTimer);
		for (const watcher of watched?.watchers.values() ?? []) watcher.close();
		jobWatchers.delete(asyncId);
		const timer = refreshTimers.get(asyncId);
		if (timer) clearTimeout(timer);
		refreshTimers.delete(asyncId);
		runningJobIds.delete(asyncId);
	};

	const refreshJob = (job: AsyncJobState): boolean => {
		const widgetExpanded = state.lastUiContext?.hasUI ? state.lastUiContext.ui.getToolsExpanded?.() ?? false : false;
		const widgetStateBefore = widgetRenderKey(job, widgetExpanded);
		let nestedRefreshFailed = false;
		const refreshNestedProjection = () => {
			try {
				updateAsyncJobNestedProjection(job);
			} catch (error) {
				nestedRefreshFailed = true;
				console.error(`Failed to refresh nested async descendants for '${job.asyncDir}':`, error);
			}
		};
		try {
			emitNewControlEvents(job);
			serviceExternalJobBridgeRequests(job.asyncDir);
			try {
				if (job.nestedRoute) reconcileNestedAsyncDescendants(job.nestedRoute, { resultsDir, kill: options.kill, now: options.now });
			} catch (error) {
				nestedRefreshFailed = true;
				console.error(`Failed to refresh nested async descendants for '${job.asyncDir}':`, error);
			}
			refreshNestedProjection();
			const reconciliation = reconcileAsyncRun(job.asyncDir, {
				resultsDir,
				kill: options.kill,
				now: options.now,
				startedRun: {
					runId: job.asyncId,
					pid: job.pid,
					sessionId: job.sessionId,
					completionOwnerId: job.completionOwnerId,
					mode: job.mode,
					agents: job.agents,
					chainStepCount: job.chainStepCount,
					parallelGroups: job.parallelGroups,
					startedAt: job.startedAt,
					sessionFile: job.sessionFile,
				},
			});
			const status = reconciliation.status ?? readStatus(job.asyncDir);
			if (status) {
				const previousStatus = job.status;
				job.status = status.state;
				if (job.status === "running") runningJobIds.add(job.asyncId);
				else runningJobIds.delete(job.asyncId);
				if (job.status !== "complete" && job.status !== "failed" && job.status !== "paused" && job.status !== "stopped") cancelCleanup(job.asyncId);
				job.sessionId = status.sessionId ?? job.sessionId;
				job.activityState = status.activityState;
				job.lastActivityAt = status.lastActivityAt ?? job.lastActivityAt;
				job.currentTool = status.currentTool;
				job.currentToolStartedAt = status.currentToolStartedAt;
				job.currentPath = status.currentPath;
				job.turnCount = status.turnCount ?? job.turnCount;
				job.toolCount = status.toolCount ?? job.toolCount;
				job.steering = status.steering ?? job.steering;
				job.mode = status.mode;
				job.parentWorkflowRunId = status.parentWorkflowRunId ?? job.parentWorkflowRunId;
				job.workflowKey = status.workflowKey ?? job.workflowKey;
				job.workflow = status.workflow ?? job.workflow;
				job.currentStep = status.currentStep ?? job.currentStep;
				job.chainStepCount = status.chainStepCount ?? job.chainStepCount;
				job.startedAt = status.startedAt ?? job.startedAt;
				if (status.lastUpdate !== undefined) job.updatedAt = status.lastUpdate;
				if (status.steps?.length) {
					const groups = normalizeParallelGroups(status.parallelGroups, status.steps.length, status.chainStepCount ?? status.steps.length);
					job.parallelGroups = groups.length ? groups : job.parallelGroups;
					job.hasParallelGroups = groups.length > 0 || job.hasParallelGroups;
					const activeGroup = status.currentStep !== undefined
						? groups.find((group) => status.currentStep! >= group.start && status.currentStep! < group.start + group.count)
						: undefined;
					const visibleSteps = activeGroup
						? status.steps.slice(activeGroup.start, activeGroup.start + activeGroup.count).map((step, index) => ({ ...step, index: activeGroup.start + index }))
						: status.steps.map((step, index) => ({ ...step, index }));
					job.activeParallelGroup = Boolean(activeGroup);
					job.agents = visibleSteps.map((step) => step.agent);
					job.steps = visibleSteps;
					refreshNestedProjection();
					job.stepsTotal = visibleSteps.length;
					job.runningSteps = visibleSteps.filter((step) => step.status === "running").length;
					job.completedSteps = visibleSteps.filter((step) => step.status === "complete" || step.status === "completed").length;
					if (status.state === "complete") job.completedSteps = visibleSteps.length;
				}
				job.sessionDir = status.sessionDir ?? job.sessionDir;
				job.outputFile = status.outputFile ?? job.outputFile;
				job.totalTokens = status.totalTokens ?? job.totalTokens;
				job.timeoutMs = status.timeoutMs ?? job.timeoutMs;
				job.deadlineAt = status.deadlineAt ?? job.deadlineAt;
				job.timedOut = status.timedOut ?? job.timedOut;
				job.stopped = status.stopped ?? job.stopped;
				job.turnBudget = status.turnBudget ?? job.turnBudget;
				job.turnBudgetExceeded = status.turnBudgetExceeded ?? job.turnBudgetExceeded;
				job.wrapUpRequested = status.wrapUpRequested ?? job.wrapUpRequested;
				job.sessionFile = status.sessionFile ?? job.sessionFile;
				if (terminalStatus(job.status)) {
					if (!terminalStatus(previousStatus)) options.onJobTerminal?.();
					rememberFleetJob(state, job);
					if (!nestedRefreshFailed && !hasLiveNestedDescendants(job.nestedChildren) && (previousStatus !== job.status || !state.cleanupTimers.has(job.asyncId))) {
						scheduleCleanup(job.asyncId);
					}
				}
				return widgetRenderKey(job, widgetExpanded) !== widgetStateBefore;
			}
			if (job.status === "queued") {
				job.status = "running";
				job.updatedAt = Date.now();
				runningJobIds.add(job.asyncId);
			}
		} catch (error) {
			if (job.status !== "failed") {
				console.error(`Failed to read async status for '${job.asyncDir}':`, error);
				job.status = "failed";
				job.updatedAt = Date.now();
			}
			runningJobIds.delete(job.asyncId);
			rememberFleetJob(state, job);
			if (!hasLiveNestedDescendants(job.nestedChildren) && !state.cleanupTimers.has(job.asyncId)) scheduleCleanup(job.asyncId);
		}
		return widgetRenderKey(job, widgetExpanded) !== widgetStateBefore;
	};

	const scheduleJobRefresh = (asyncId: string, delayMs = EVENT_REFRESH_DEBOUNCE_MS) => {
		if (refreshTimers.has(asyncId)) return;
		const timer = setTimeout(() => {
			refreshTimers.delete(asyncId);
			const job = state.asyncJobs.get(asyncId);
			if (job && refreshJob(job)) rerenderLastWidget();
		}, delayMs);
		timer.unref?.();
		refreshTimers.set(asyncId, timer);
	};

	const watchJob = (job: AsyncJobState) => {
		if (!useNativeWatcher()) return;
		const watched = jobWatchers.get(job.asyncId) ?? { watchers: new Map<string, fs.FSWatcher>() };
		const active = job.status === "queued" || job.status === "running";
		const watchPath = (watchPath: string): boolean => {
			if (watched.watchers.has(watchPath)) return true;
			const nestedEventSink = job.nestedRoute?.eventSink === watchPath;
			let watcher: fs.FSWatcher;
			try {
				watcher = watch(resolveWatchPath(watchPath), (_event, file) => {
					const rawFileName = file?.toString();
					const fileName = rawFileName ?? path.basename(watchPath);
					const nestedEventFile = nestedEventSink && (!rawFileName || rawFileName.endsWith(".json") || rawFileName.endsWith(".jsonl"));
					if (fileName === "status.json" || fileName === "events.jsonl" || fileName === EXTERNAL_JOB_BRIDGE_REQUEST_DIR || fileName.endsWith(".json") || nestedEventFile) {
						scheduleJobRefresh(job.asyncId);
					}
					if (watchPath !== job.asyncDir && !nestedEventSink) {
						watcher.close();
						watched.watchers.delete(watchPath);
						watchJob(job);
					}
				});
			} catch {
				return false;
			}
			watcher.on("error", () => {
				watcher.close();
				watched.watchers.delete(watchPath);
				if (watchPath.endsWith("status.json") || nestedEventSink) watchJob(job);
			});
			watcher.unref?.();
			watched.watchers.set(watchPath, watcher);
			return true;
		};
		watchPath(job.asyncDir);
		const statusPath = path.join(job.asyncDir, "status.json");
		const hadStatusWatcher = watched.watchers.has(statusPath);
		const statusWatched = watchPath(statusPath);
		if (statusWatched && !hadStatusWatcher) scheduleJobRefresh(job.asyncId);
		watchPath(path.join(job.asyncDir, "events.jsonl"));
		watchPath(path.join(job.asyncDir, EXTERNAL_JOB_BRIDGE_REQUEST_DIR));
		if (job.nestedRoute) watchPath(job.nestedRoute.eventSink);
		if (!statusWatched && active && !watched.retryTimer) {
			watched.retryTimer = setTimeout(() => {
				watched.retryTimer = undefined;
				const current = state.asyncJobs.get(job.asyncId);
				if (current) watchJob(current);
			}, WATCH_ATTACHMENT_RETRY_MS);
			watched.retryTimer.unref?.();
		} else if (statusWatched && watched.retryTimer) {
			clearTimeout(watched.retryTimer);
			watched.retryTimer = undefined;
		}
		if (watched.watchers.size > 0 || watched.retryTimer) jobWatchers.set(job.asyncId, watched);
		else jobWatchers.delete(job.asyncId);
	};

	const watchAsyncRoot = () => {
		if (!useNativeWatcher()) return;
		if (rootWatcher) return;
		try {
			rootWatcher = watch(resolveWatchPath(asyncDirRoot), (_event, file) => {
				const runDirName = file?.toString();
				for (const job of state.asyncJobs.values()) {
					if (jobWatchers.has(job.asyncId) || (runDirName && path.basename(job.asyncDir) !== runDirName)) continue;
					watchJob(job);
					if (jobWatchers.has(job.asyncId)) scheduleJobRefresh(job.asyncId);
				}
			});
			rootWatcher.on("error", () => {
				rootWatcher?.close();
				rootWatcher = undefined;
			});
			rootWatcher.unref?.();
		} catch {
			// The liveness sweep retries if the async root is not available yet.
		}
	};

	const ensurePoller = () => {
		watchAsyncRoot();
		if (state.poller) return;
		nextLivenessAt = Date.now() + livenessIntervalMs;
		state.poller = setInterval(() => {
			if (state.asyncJobs.size === 0) {
				rerenderLastWidget([]);
				if (state.poller) clearInterval(state.poller);
				state.poller = null;
				rootWatcher?.close();
				rootWatcher = undefined;
				return;
			}
			const now = Date.now();
			if (now >= nextLivenessAt) {
				nextLivenessAt = now + livenessIntervalMs;
				let widgetChanged = false;
				for (const job of state.asyncJobs.values()) {
					watchJob(job);
					if (refreshJob(job)) widgetChanged = true;
				}
				if (widgetChanged) rerenderLastWidget();
			}
			if (runningJobIds.size > 0 && now >= nextWidgetAnimationAt) {
				nextWidgetAnimationAt = now + WIDGET_ANIMATION_INTERVAL_MS;
				requestLastWidgetRender();
			}
		}, Math.min(WIDGET_ANIMATION_INTERVAL_MS, livenessIntervalMs));
		state.poller.unref?.();
	};

	const handleStarted = (data: unknown) => {
		const info = data as AsyncStartedEvent;
		if (!info.id) return;
		if (typeof state.currentSessionId === "string" && info.sessionId !== state.currentSessionId) return;
		const now = Date.now();
		const asyncDir = info.asyncDir ?? path.join(asyncDirRoot, info.id);
		const rawAgents = info.agents?.length ? info.agents : info.chain && info.chain.length > 0 ? info.chain : info.agent ? [info.agent] : undefined;
		const validParallelGroups = normalizeParallelGroups(info.parallelGroups, Number.MAX_SAFE_INTEGER, info.chainStepCount ?? Number.MAX_SAFE_INTEGER);
		const firstGroup = validParallelGroups.find((group) => group.start === 0);
		const firstGroupCount = firstGroup?.count;
		const agents = firstGroupCount && firstGroupCount > 0
			? rawAgents?.slice(0, firstGroupCount)
			: rawAgents;
		const sessionRoot = state.liveAsyncSessionRoots?.get(info.id);
		state.liveAsyncSessionRoots?.delete(info.id);
		state.asyncJobs.set(info.id, {
			asyncId: info.id,
			asyncDir,
			...(typeof info.cwd === "string" ? { cwd: path.resolve(info.cwd) } : {}),
			...(sessionRoot ? { sessionRoot } : {}),
			status: "queued",
			pid: typeof info.pid === "number" ? info.pid : undefined,
			...(typeof info.sessionId === "string" ? { sessionId: info.sessionId } : {}),
			...(typeof info.completionOwnerId === "string" ? { completionOwnerId: info.completionOwnerId } : {}),
			mode: info.mode ?? (info.chain ? "chain" : "single"),
			description: info.goal ?? info.task,
			agents,
			chainStepCount: info.chainStepCount,
			parallelGroups: validParallelGroups,
			nestedRoute: info.nestedRoute,
			stepsTotal: firstGroupCount ?? agents?.length,
			hasParallelGroups: validParallelGroups.length > 0,
			activeParallelGroup: Boolean(firstGroupCount && firstGroupCount > 0),
			startedAt: now,
			updatedAt: now,
			timeoutMs: info.timeoutMs,
			deadlineAt: info.deadlineAt,
			turnBudget: info.turnBudget,
			parentWorkflowRunId: info.parentWorkflowRunId,
			workflowKey: info.workflowKey,
			controlEventCursor: 0,
		});
		const job = state.asyncJobs.get(info.id)!;
		rememberFleetJob(state, job);
		watchJob(job);
		scheduleJobRefresh(info.id, 0);
		ensurePoller();
		rerenderLastWidget();
	};

	const handleComplete = (data: unknown) => {
		const result = data as { id?: string; success?: boolean; state?: AsyncJobState["status"]; asyncDir?: string; sessionId?: string; stopped?: boolean };
		if (typeof state.currentSessionId === "string" && result.sessionId !== state.currentSessionId) return;
		const asyncId = result.id;
		if (!asyncId) return;
		const job = state.asyncJobs.get(asyncId);
		let nestedRefreshFailed = false;
		if (job) {
			job.status = result.state ?? (result.success ? "complete" : "failed");
			runningJobIds.delete(asyncId);
			job.stopped = result.stopped ?? job.stopped;
			job.updatedAt = Date.now();
			if (result.asyncDir && result.asyncDir !== job.asyncDir) {
				closeJobWatcher(asyncId);
				job.asyncDir = result.asyncDir;
				watchJob(job);
			}
			try {
				updateAsyncJobNestedProjection(job);
			} catch (error) {
				nestedRefreshFailed = true;
				console.error(`Failed to refresh nested async descendants for '${job.asyncDir}':`, error);
			}
		}
		if (job) rememberFleetJob(state, job);
		rerenderLastWidget();
		if (!nestedRefreshFailed && !hasLiveNestedDescendants(job?.nestedChildren)) scheduleCleanup(asyncId);
	};

	const dispose = () => {
		if (state.poller) clearInterval(state.poller);
		state.poller = null;
		rootWatcher?.close();
		rootWatcher = undefined;
		for (const asyncId of jobWatchers.keys()) closeJobWatcher(asyncId);
		for (const timer of refreshTimers.values()) clearTimeout(timer);
		refreshTimers.clear();
		runningJobIds.clear();
	};

	const resetJobs = (ctx?: ExtensionContext) => {
		dispose();
		for (const timer of state.cleanupTimers.values()) clearTimeout(timer);
		state.cleanupTimers.clear();
		state.asyncJobs.clear();
		state.fleetJobs?.clear();
		state.foregroundControls?.clear();
		state.liveAsyncSessionRoots?.clear();
		state.lastForegroundControlId = null;
		state.resultFileCoalescer.clear();
		if (ctx?.hasUI) {
			state.lastUiContext = ctx;
			rerenderWidget(ctx, []);
		}
	};

	const restoreActiveJobs = (ctx?: ExtensionContext) => {
		if (ctx?.hasUI) state.lastUiContext = ctx;
		if (!state.currentSessionId) return;
		let runs: AsyncRunSummary[];
		try {
			runs = listAsyncRuns(asyncDirRoot, { states: ["queued", "running"], sessionId: state.currentSessionId, resultsDir, kill: options.kill, now: options.now });
		} catch (error) {
			console.error(`Failed to restore active async jobs from '${asyncDirRoot}':`, error);
			return;
		}
		for (const run of runs) {
			const job = summaryToJob(run);
			state.asyncJobs.set(run.id, job);
			if (job.status === "running") runningJobIds.add(job.asyncId);
			rememberFleetJob(state, job);
			watchJob(job);
		}
		if (runs.length === 0) return;
		ensurePoller();
		rerenderLastWidget();
	};

	return { ensurePoller, refreshWidget, handleStarted, handleComplete, resetJobs, restoreActiveJobs, dispose };
}

import * as fs from "node:fs";
import * as path from "node:path";
import { DIRS, type AcceptanceInput, type AsyncStatus, type ResolvedTurnBudget, type SteeringRecoveryDescriptor, type SubagentRunMode } from "../../shared/types.ts";
import type { AgentConfig } from "../../agents/agents.ts";
import { validateAcceptanceInput } from "../shared/acceptance.ts";
import { validateToolBudgetConfig } from "../shared/tool-budget.ts";
import { intersectSubagentCapabilityCeilings, parseSubagentCapabilityCeiling, type ResolvedSubagentCapabilityCeiling } from "../shared/capability-ceiling.ts";
import { validateRunFanoutBudgetDescriptor } from "../shared/run-fanout-budget.ts";
import { resolveTurnBudgetConfig } from "../shared/turn-budget.ts";
import { reconcileAsyncRun } from "./stale-run-reconciler.ts";
import { resultFilePath, resultPayloadPathForIndexedRun } from "./result-files.ts";
import { canScanAsyncRunPrefix, MIN_SAFE_ASYNC_RUN_PREFIX_LENGTH } from "./run-id-query.ts";
import { parallelHandoffPath, resolveRetainedWorktreeCwd } from "../shared/parallel-handoff.ts";
import { intersectThinkingCeilings, parseThinkingLevel, type ThinkingLevel } from "../../shared/thinking-ceiling.ts";

export interface AsyncResumeParams {
	id?: string;
	runId?: string;
	dir?: string;
	index?: number;
}

export interface AsyncResumeDeps {
	asyncDirRoot?: string;
	resultsDir?: string;
	kill?: (pid: number, signal?: NodeJS.Signals | 0) => boolean;
	now?: () => number;
}

export interface AsyncResumeOptions {
	requireSessionFile?: boolean;
	sessionId?: string;
}

export type AsyncResumeTarget = {
	kind: "live" | "revive";
	runId: string;
	asyncDir?: string;
	state: AsyncStatus["state"];
	mode?: SubagentRunMode;
	agent: string;
	index: number;
	cwd?: string;
	sessionFile?: string;
	model?: string;
	thinking?: string;
	thinkingCeiling?: ThinkingLevel;
	recoveryDescriptor?: SteeringRecoveryDescriptor;
	capabilityCeiling?: ResolvedSubagentCapabilityCeiling;
	launchContractDigest?: string;
	runner?: NonNullable<AsyncStatus["steps"]>[number]["runner"];
	externalJob?: NonNullable<AsyncStatus["steps"]>[number]["externalJob"];
};

interface AsyncResultFile {
	id?: string;
	runId?: string;
	agent?: string;
	mode?: string;
	state?: string;
	success?: boolean;
	cwd?: string;
	sessionId?: string;
	sessionFile?: string;
	model?: string;
	thinking?: string;
	launchContractDigest?: string;
	capabilityCeiling?: ResolvedSubagentCapabilityCeiling;
	results?: Array<{ agent?: string; success?: boolean; sessionFile?: string; intercomTarget?: string; model?: string; thinking?: string; launchContractDigest?: string; capabilityCeiling?: ResolvedSubagentCapabilityCeiling }>;
}

export interface AsyncRunLocation {
	asyncDir: string | null;
	resultPath: string | null;
	resolvedId?: string;
}

function getErrorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function ensureObject(value: unknown, source: string): Record<string, unknown> {
	if (!value || typeof value !== "object" || Array.isArray(value)) {
		throw new Error(`Async result file '${source}' must contain a JSON object.`);
	}
	return value as Record<string, unknown>;
}

function validateOptionalString(value: Record<string, unknown>, field: string, source: string, displayField = field): string | undefined {
	const fieldValue = value[field];
	if (fieldValue === undefined) return undefined;
	if (typeof fieldValue !== "string") throw new Error(`Invalid async result file '${source}': ${displayField} must be a string.`);
	return fieldValue;
}

function validateResultFile(value: unknown, resultPath: string): AsyncResultFile {
	const data = ensureObject(value, resultPath);
	const resultsValue = data.results;
	let results: AsyncResultFile["results"];
	if (resultsValue !== undefined) {
		if (!Array.isArray(resultsValue)) throw new Error(`Invalid async result file '${resultPath}': results must be an array.`);
		results = resultsValue.map((entry, index) => {
			const child = ensureObject(entry, `${resultPath} results[${index}]`);
			const agent = validateOptionalString(child, "agent", resultPath, `results[${index}].agent`);
			const sessionFile = validateOptionalString(child, "sessionFile", resultPath, `results[${index}].sessionFile`);
			const intercomTarget = validateOptionalString(child, "intercomTarget", resultPath, `results[${index}].intercomTarget`);
			const model = validateOptionalString(child, "model", resultPath, `results[${index}].model`);
			const thinking = validateOptionalString(child, "thinking", resultPath, `results[${index}].thinking`);
			const launchContractDigest = validateOptionalString(child, "launchContractDigest", resultPath, `results[${index}].launchContractDigest`);
			const capabilityCeiling = child.capabilityCeiling === undefined ? undefined : parseSubagentCapabilityCeiling(child.capabilityCeiling, `async result file '${resultPath}' results[${index}].capabilityCeiling`);
			const success = child.success;
			if (success !== undefined && typeof success !== "boolean") throw new Error(`Invalid async result file '${resultPath}': results[${index}].success must be a boolean.`);
			return { agent, sessionFile, intercomTarget, model, thinking, launchContractDigest, ...(capabilityCeiling ? { capabilityCeiling } : {}), ...(typeof success === "boolean" ? { success } : {}) };
		});
	}
	const success = data.success;
	if (success !== undefined && typeof success !== "boolean") throw new Error(`Invalid async result file '${resultPath}': success must be a boolean.`);
	return {
		id: validateOptionalString(data, "id", resultPath),
		runId: validateOptionalString(data, "runId", resultPath),
		agent: validateOptionalString(data, "agent", resultPath),
		mode: validateOptionalString(data, "mode", resultPath),
		state: validateOptionalString(data, "state", resultPath),
		cwd: validateOptionalString(data, "cwd", resultPath),
		sessionId: validateOptionalString(data, "sessionId", resultPath),
		sessionFile: validateOptionalString(data, "sessionFile", resultPath),
		model: validateOptionalString(data, "model", resultPath),
		thinking: validateOptionalString(data, "thinking", resultPath),
		launchContractDigest: validateOptionalString(data, "launchContractDigest", resultPath),
		...(data.capabilityCeiling === undefined ? {} : { capabilityCeiling: parseSubagentCapabilityCeiling(data.capabilityCeiling, `async result file '${resultPath}' capabilityCeiling`) }),
		...(typeof success === "boolean" ? { success } : {}),
		...(results ? { results } : {}),
	};
}

function readResultFile(resultPath: string): AsyncResultFile {
	let raw: string;
	try {
		raw = fs.readFileSync(resultPath, "utf-8");
	} catch (error) {
		throw new Error(`Failed to read async result file '${resultPath}': ${getErrorMessage(error)}`, {
			cause: error instanceof Error ? error : undefined,
		});
	}
	try {
		return validateResultFile(JSON.parse(raw), resultPath);
	} catch (error) {
		if (error instanceof SyntaxError) {
			throw new Error(`Failed to parse async result file '${resultPath}': ${getErrorMessage(error)}`, {
				cause: error,
			});
		}
		throw error;
	}
}

function assertRunId(value: string | undefined, field: "id" | "runId"): string | undefined {
	if (value === undefined) return undefined;
	if (value.trim() === "") throw new Error(`${field} must not be empty.`);
	if (path.isAbsolute(value) || /[\\/]/.test(value) || value.includes("..")) {
		throw new Error(`${field} must be an async run id or prefix, not a path.`);
	}
	return value;
}

function assertInsideRoot(root: string, target: string, label: string): void {
	const rootPath = path.resolve(root);
	const targetPath = path.resolve(target);
	const relative = path.relative(rootPath, targetPath);
	if (relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative))) return;
	throw new Error(`${label} must be inside ${rootPath}.`);
}

function prefixedRunIds(dir: string, prefix: string, suffix = ""): string[] {
	if (!fs.existsSync(dir)) return [];
	return fs.readdirSync(dir)
		.filter((entry) => entry.startsWith(prefix) && (!suffix || entry.endsWith(suffix)))
		.map((entry) => suffix ? entry.slice(0, -suffix.length) : entry)
		.sort();
}

function exactResultPath(resultsDir: string, runId: string): string | null {
	const indexed = resultPayloadPathForIndexedRun(resultsDir, runId);
	if (indexed) return indexed;
	const resultPath = resultFilePath(resultsDir, runId);
	assertInsideRoot(resultsDir, resultPath, "Async result file");
	return fs.existsSync(resultPath) ? resultPath : null;
}

export function findAsyncRunPrefixMatches(prefix: string, asyncDirRoot: string, resultsDir: string): Array<{ id: string; location: AsyncRunLocation }> {
	const requestedId = assertRunId(prefix, "id");
	if (!requestedId) return [];
	if (!canScanAsyncRunPrefix(requestedId)) return [];
	const asyncRoot = path.resolve(asyncDirRoot);
	const resultRoot = path.resolve(resultsDir);
	const matchingIds = prefixedRunIds(asyncRoot, requestedId).sort();
	return matchingIds.map((id) => {
		const asyncDir = path.join(asyncRoot, id);
		assertInsideRoot(asyncRoot, asyncDir, "Async run directory");
		return {
			id,
			location: {
				asyncDir: fs.existsSync(asyncDir) ? asyncDir : null,
				resultPath: exactResultPath(resultRoot, id),
				resolvedId: id,
			},
		};
	});
}

export function resolveAsyncRunLocation(params: AsyncResumeParams, asyncDirRoot: string, resultsDir: string): AsyncRunLocation {
	const asyncRoot = path.resolve(asyncDirRoot);
	const resultRoot = path.resolve(resultsDir);
	const requestedId = assertRunId(params.id, "id") ?? assertRunId(params.runId, "runId");
	if (params.dir) {
		const asyncDir = path.resolve(params.dir);
		assertInsideRoot(asyncRoot, asyncDir, "Async run directory");
		const resolvedId = requestedId ?? path.basename(asyncDir);
		if (requestedId && requestedId !== path.basename(asyncDir)) {
			throw new Error(`Async run id '${requestedId}' does not match directory '${path.basename(asyncDir)}'.`);
		}
		return { asyncDir, resultPath: exactResultPath(resultRoot, resolvedId), resolvedId };
	}
	if (!requestedId) return { asyncDir: null, resultPath: null };

	const directAsyncDir = path.join(asyncRoot, requestedId);
	assertInsideRoot(asyncRoot, directAsyncDir, "Async run directory");
	const directResultPath = exactResultPath(resultRoot, requestedId);
	if (fs.existsSync(directAsyncDir) || directResultPath) {
		return {
			asyncDir: fs.existsSync(directAsyncDir) ? directAsyncDir : null,
			resultPath: directResultPath,
			resolvedId: requestedId,
		};
	}
	if (requestedId.length < MIN_SAFE_ASYNC_RUN_PREFIX_LENGTH) {
		throw new Error(`Async run id prefix '${requestedId}' is too short. Provide at least ${MIN_SAFE_ASYNC_RUN_PREFIX_LENGTH} characters.`);
	}
	if (!canScanAsyncRunPrefix(requestedId)) return { asyncDir: null, resultPath: null, resolvedId: requestedId };

	const matching = findAsyncRunPrefixMatches(requestedId, asyncRoot, resultRoot);
	if (matching.length === 0) return { asyncDir: null, resultPath: null, resolvedId: requestedId };
	if (matching.length > 1) {
		throw new Error(`Ambiguous async run id prefix '${requestedId}' matched: ${matching.map((match) => match.id).join(", ")}. Provide a longer id.`);
	}
	return matching[0]!.location;
}

function resultState(result: AsyncResultFile): AsyncStatus["state"] {
	if (result.state === "complete" || result.state === "failed" || result.state === "paused" || result.state === "stopped" || result.state === "running" || result.state === "queued") {
		return result.state;
	}
	return result.success ? "complete" : "failed";
}

function validateStatusForResume(status: AsyncStatus | null, source: string): void {
	if (!status) return;
	if (typeof status.runId !== "string") throw new Error(`Invalid async status '${source}': runId must be a string.`);
	if (status.sessionId !== undefined && typeof status.sessionId !== "string") throw new Error(`Invalid async status '${source}': sessionId must be a string.`);
	if (status.cwd !== undefined && typeof status.cwd !== "string") throw new Error(`Invalid async status '${source}': cwd must be a string.`);
	if (status.sessionFile !== undefined && typeof status.sessionFile !== "string") throw new Error(`Invalid async status '${source}': sessionFile must be a string.`);
	if (status.capabilityCeiling !== undefined) status.capabilityCeiling = parseSubagentCapabilityCeiling(status.capabilityCeiling, `async status '${source}' capabilityCeiling`);
	if (status.steps !== undefined) {
		if (!Array.isArray(status.steps)) throw new Error(`Invalid async status '${source}': steps must be an array.`);
		status.steps.forEach((step, index) => {
			if (!step || typeof step !== "object" || Array.isArray(step)) throw new Error(`Invalid async status '${source}': steps[${index}] must be an object.`);
			const stepRecord = step as Record<string, unknown>;
			if (typeof stepRecord.agent !== "string") throw new Error(`Invalid async status '${source}': steps[${index}].agent must be a string.`);
			if (stepRecord.sessionFile !== undefined && typeof stepRecord.sessionFile !== "string") throw new Error(`Invalid async status '${source}': steps[${index}].sessionFile must be a string.`);
			if (stepRecord.model !== undefined && typeof stepRecord.model !== "string") throw new Error(`Invalid async status '${source}': steps[${index}].model must be a string.`);
			if (stepRecord.thinking !== undefined && typeof stepRecord.thinking !== "string") throw new Error(`Invalid async status '${source}': steps[${index}].thinking must be a string.`);
			if (stepRecord.thinkingCeiling !== undefined) stepRecord.thinkingCeiling = parseThinkingLevel(stepRecord.thinkingCeiling, `async status '${source}' steps[${index}].thinkingCeiling`);
			if (stepRecord.launchContractDigest !== undefined && typeof stepRecord.launchContractDigest !== "string") throw new Error(`Invalid async status '${source}': steps[${index}].launchContractDigest must be a string.`);
			if (stepRecord.capabilityCeiling !== undefined) stepRecord.capabilityCeiling = parseSubagentCapabilityCeiling(stepRecord.capabilityCeiling, `async status '${source}' steps[${index}].capabilityCeiling`);
		});
	}
}

function normalizeRecoveryAcceptance(value: unknown, descriptorPath: string): AcceptanceInput {
	const errors = validateAcceptanceInput(value, "recoveryDescriptor.acceptance");
	if (errors.length) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': ${errors.join(" ")}`);
	return value as AcceptanceInput;
}

function normalizeRecoveryTurnBudget(value: unknown, descriptorPath: string): ResolvedTurnBudget {
	if (value && typeof value === "object" && !Array.isArray(value)) {
		const {
			outcome: _outcome,
			turnCount: _turnCount,
			wrapUpRequestedAtTurn: _wrapUpRequestedAtTurn,
			terminationDeferredAtTurn: _terminationDeferredAtTurn,
			exceededAtTurn: _exceededAtTurn,
			...publicTurnBudget
		} = value as Record<string, unknown>;
		value = publicTurnBudget;
	}
	const result = resolveTurnBudgetConfig(value, "recoveryDescriptor.initialTurnBudget");
	if (result.error || !result.turnBudget) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': ${result.error ?? "recoveryDescriptor.initialTurnBudget is invalid."}`);
	return result.turnBudget;
}

export function asyncReviveRequiresRecoveryDescriptor(target: Pick<AsyncResumeTarget, "recoveryDescriptor" | "mode" | "sessionFile">): boolean {
	if (target.recoveryDescriptor) return false;
	return !(target.mode === "workflow" && Boolean(target.sessionFile));
}

function resumeTargetMode(status: AsyncStatus | null, result: AsyncResultFile | undefined): SubagentRunMode | undefined {
	if (status?.mode) return status.mode;
	if (result?.mode === "single" || result?.mode === "parallel" || result?.mode === "chain" || result?.mode === "workflow") return result.mode;
	return undefined;
}

export function readAsyncRecoveryDescriptor(asyncDir: string | undefined): SteeringRecoveryDescriptor | undefined {
	if (!asyncDir) return undefined;
	const descriptorPath = path.join(asyncDir, "recovery-descriptor.json");
	if (!fs.existsSync(descriptorPath)) return undefined;
	let value: unknown;
	try {
		value = JSON.parse(fs.readFileSync(descriptorPath, "utf-8"));
	} catch (error) {
		throw new Error(`Failed to parse async recovery descriptor '${descriptorPath}': ${getErrorMessage(error)}`, { cause: error instanceof Error ? error : undefined });
	}
	if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': expected an object.`);
	const parsed = value as Record<string, unknown>;
	const allowedFields = new Set([
		"version", "launchContractDigest", "sourceRunId", "agentContract", "agent", "sessionFile", "cwd", "model", "modelProvider", "modelOverrideFromParent", "fallbackModels", "thinking", "thinkingCeiling", "tools", "extensions",
		"subagentOnlyExtensions", "mcpDirectTools", "systemPrompt", "systemPromptMode", "inheritProjectContext", "inheritSkills", "skills",
		"skillPath", "agentFilePath", "completionGuard", "memory", "outputPath", "outputMode", "structuredOutputSchema", "acceptance", "sessionDir", "artifactConfig",
		"artifactsDir", "maxOutput", "controlConfig", "context", "intercomBridge", "absoluteDeadlineAt", "initialTurnBudget", "initialToolBudget", "maxSubagentDepth", "share", "capabilityCeiling",
		"launchResolvedExtensions", "runFanoutBudget",
	]);
	for (const field of Object.keys(parsed)) {
		if (!allowedFields.has(field)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': unknown field '${field}'.`);
	}
	const requiredStrings = ["sourceRunId", "agent", "cwd", "systemPromptMode", "outputMode"] as const;
	for (const field of requiredStrings) {
		if (typeof parsed[field] !== "string" || !(parsed[field] as string).trim()) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': ${field} must be a non-empty string.`);
	}
	if (parsed.version !== 1) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': version must be 1.`);
	try {
		parsed.runFanoutBudget = validateRunFanoutBudgetDescriptor(parsed.runFanoutBudget);
	} catch (error) {
		throw new Error(`Invalid async recovery descriptor '${descriptorPath}': ${error instanceof Error ? error.message : String(error)}`);
	}
	if (parsed.capabilityCeiling !== undefined) parsed.capabilityCeiling = parseSubagentCapabilityCeiling(parsed.capabilityCeiling, `async recovery descriptor '${descriptorPath}' capabilityCeiling`);
	if (parsed.thinkingCeiling !== undefined) parsed.thinkingCeiling = parseThinkingLevel(parsed.thinkingCeiling, `async recovery descriptor '${descriptorPath}' thinkingCeiling`);
	if (parsed.agentContract !== undefined) {
		if (!parsed.agentContract || typeof parsed.agentContract !== "object" || Array.isArray(parsed.agentContract)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': agentContract must be an object.`);
		const contract = parsed.agentContract as Record<string, unknown>;
		if (contract.version !== 1 || Object.keys(contract).some((key) => key !== "version")) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': agentContract must be { version: 1 }.`);
	}
	if (parsed.systemPromptMode !== "append" && parsed.systemPromptMode !== "replace") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': systemPromptMode is invalid.`);
	if (parsed.outputMode !== "inline" && parsed.outputMode !== "file-only") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': outputMode is invalid.`);
	if (parsed.context !== undefined && parsed.context !== "fresh" && parsed.context !== "fork") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': context is invalid.`);
	if (parsed.modelOverrideFromParent !== undefined && typeof parsed.modelOverrideFromParent !== "boolean") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': modelOverrideFromParent must be a boolean.`);
	for (const field of ["inheritProjectContext", "inheritSkills", "share"] as const) {
		if (typeof parsed[field] !== "boolean") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': ${field} must be a boolean.`);
	}
	if (!Number.isInteger(parsed.maxSubagentDepth) || (parsed.maxSubagentDepth as number) < 0) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': maxSubagentDepth must be a non-negative integer.`);
	for (const field of ["fallbackModels", "tools", "extensions", "subagentOnlyExtensions", "mcpDirectTools", "skills", "skillPath"] as const) {
		const item = parsed[field];
		if (item !== undefined && (!Array.isArray(item) || item.some((entry) => typeof entry !== "string" || !entry.trim()))) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': ${field} must contain non-empty strings.`);
	}
	if (parsed.systemPrompt !== undefined && typeof parsed.systemPrompt !== "string") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': systemPrompt must be a string.`);
	for (const field of ["launchContractDigest", "sessionFile", "model", "modelProvider", "thinking", "agentFilePath", "outputPath", "sessionDir", "artifactsDir"] as const) {
		if (parsed[field] !== undefined && (typeof parsed[field] !== "string" || !(parsed[field] as string).trim())) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': ${field} must be a non-empty string.`);
	}
	if (parsed.completionGuard !== undefined && typeof parsed.completionGuard !== "boolean") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': completionGuard must be a boolean.`);
	if (parsed.structuredOutputSchema !== undefined && (!parsed.structuredOutputSchema || typeof parsed.structuredOutputSchema !== "object" || Array.isArray(parsed.structuredOutputSchema))) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': structuredOutputSchema must be an object.`);
	if (parsed.memory !== undefined) {
		if (!parsed.memory || typeof parsed.memory !== "object" || Array.isArray(parsed.memory)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': memory must be an object.`);
		const memory = parsed.memory as Record<string, unknown>;
		if ((memory.scope !== "project" && memory.scope !== "user") || typeof memory.path !== "string" || !memory.path.trim()) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': memory is invalid.`);
	}
	if (parsed.absoluteDeadlineAt !== undefined && (!Number.isFinite(parsed.absoluteDeadlineAt) || (parsed.absoluteDeadlineAt as number) <= 0)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': absoluteDeadlineAt must be a positive timestamp.`);
	if (parsed.initialTurnBudget !== undefined) {
		parsed.initialTurnBudget = normalizeRecoveryTurnBudget(parsed.initialTurnBudget, descriptorPath);
	}
	if (parsed.initialToolBudget !== undefined) {
		const result = validateToolBudgetConfig(parsed.initialToolBudget, "recoveryDescriptor.initialToolBudget");
		if (result.error) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': ${result.error}`);
	}
	if (parsed.maxOutput !== undefined) {
		if (!parsed.maxOutput || typeof parsed.maxOutput !== "object" || Array.isArray(parsed.maxOutput)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': maxOutput must be an object.`);
		for (const field of ["bytes", "lines"] as const) {
			const item = (parsed.maxOutput as Record<string, unknown>)[field];
			if (item !== undefined && (!Number.isInteger(item) || (item as number) < 1)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': maxOutput.${field} must be a positive integer.`);
		}
	}
	if (parsed.artifactConfig !== undefined) {
		if (!parsed.artifactConfig || typeof parsed.artifactConfig !== "object" || Array.isArray(parsed.artifactConfig)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': artifactConfig must be an object.`);
		const artifact = parsed.artifactConfig as Record<string, unknown>;
		for (const field of ["enabled", "includeInput", "includeOutput", "includeJsonl", "includeMetadata"] as const) {
			if (typeof artifact[field] !== "boolean") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': artifactConfig.${field} must be a boolean.`);
		}
		if (artifact.includeTranscript !== undefined && typeof artifact.includeTranscript !== "boolean") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': artifactConfig.includeTranscript must be a boolean.`);
		if (!Number.isInteger(artifact.cleanupDays) || (artifact.cleanupDays as number) < 0) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': artifactConfig.cleanupDays must be a non-negative integer.`);
	}
	if (parsed.intercomBridge !== undefined) {
		if (!parsed.intercomBridge || typeof parsed.intercomBridge !== "object" || Array.isArray(parsed.intercomBridge)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': intercomBridge must be an object.`);
		const bridge = parsed.intercomBridge as Record<string, unknown>;
		for (const field of Object.keys(bridge)) {
			if (field !== "mode" && field !== "instructionFile" && field !== "resultDelivery") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': intercomBridge.${field} is not supported.`);
		}
		if (bridge.mode !== undefined && bridge.mode !== "off" && bridge.mode !== "fork-only" && bridge.mode !== "always") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': intercomBridge.mode is invalid.`);
		if (bridge.instructionFile !== undefined && typeof bridge.instructionFile !== "string") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': intercomBridge.instructionFile must be a string.`);
		if (bridge.resultDelivery !== undefined && typeof bridge.resultDelivery !== "boolean") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': intercomBridge.resultDelivery must be a boolean.`);
	}
	if (parsed.controlConfig !== undefined) {
		if (!parsed.controlConfig || typeof parsed.controlConfig !== "object" || Array.isArray(parsed.controlConfig)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': controlConfig must be an object.`);
		const control = parsed.controlConfig as Record<string, unknown>;
		if (typeof control.enabled !== "boolean") throw new Error(`Invalid async recovery descriptor '${descriptorPath}': controlConfig.enabled must be a boolean.`);
		for (const field of ["needsAttentionAfterMs", "activeNoticeAfterMs", "failedToolAttemptsBeforeAttention"] as const) {
			if (!Number.isInteger(control[field]) || (control[field] as number) < 1) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': controlConfig.${field} must be a positive integer.`);
		}
		for (const field of ["activeNoticeAfterTurns", "activeNoticeAfterTokens"] as const) {
			if (control[field] !== undefined && (!Number.isInteger(control[field]) || (control[field] as number) < 1)) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': controlConfig.${field} must be a positive integer.`);
		}
		if (!Array.isArray(control.notifyOn) || control.notifyOn.some((item) => item !== "active_long_running" && item !== "needs_attention")) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': controlConfig.notifyOn is invalid.`);
		if (!Array.isArray(control.notifyChannels) || control.notifyChannels.some((item) => item !== "event" && item !== "async" && item !== "intercom")) throw new Error(`Invalid async recovery descriptor '${descriptorPath}': controlConfig.notifyChannels is invalid.`);
	}
	if (parsed.acceptance !== undefined) parsed.acceptance = normalizeRecoveryAcceptance(parsed.acceptance, descriptorPath);
	return parsed as unknown as SteeringRecoveryDescriptor;
}

function validateResumeSessionFile(runId: string, sessionFile: string): string {
	if (path.extname(sessionFile) !== ".jsonl") throw new Error(`Async run '${runId}' session file must be a .jsonl file: ${sessionFile}`);
	const resolved = path.resolve(sessionFile);
	if (!fs.existsSync(resolved)) throw new Error(`Async run '${runId}' session file does not exist: ${sessionFile}`);
	return resolved;
}

function validateResumeCwd(runId: string, cwd: string | undefined): string | undefined {
	if (!cwd) return undefined;
	const resolved = path.resolve(cwd);
	try {
		if (!fs.statSync(resolved).isDirectory()) throw new Error("path is not a directory");
	} catch (error) {
		throw new Error(`Async run '${runId}' required cwd does not exist: ${cwd}`, { cause: error instanceof Error ? error : undefined });
	}
	return resolved;
}

export function resolveAsyncResumeTarget(params: AsyncResumeParams, deps: AsyncResumeDeps = {}, options: AsyncResumeOptions = {}): AsyncResumeTarget {
	const asyncDirRoot = deps.asyncDirRoot ?? DIRS.async;
	const resultsDir = deps.resultsDir ?? DIRS.results;
	const requireSessionFile = options.requireSessionFile ?? true;
	const location = resolveAsyncRunLocation(params, asyncDirRoot, resultsDir);
	if (!location.asyncDir && !location.resultPath) {
		throw new Error("Async run not found. Provide id or dir.");
	}

	const reconciliation = location.asyncDir
		? reconcileAsyncRun(location.asyncDir, { resultsDir, kill: deps.kill, now: deps.now })
		: undefined;
	const status = reconciliation?.status ?? null;
	validateStatusForResume(status, location.asyncDir ? path.join(location.asyncDir, "status.json") : "status.json");
	const recoveryDescriptor = readAsyncRecoveryDescriptor(location.asyncDir ?? undefined);
	const result = location.resultPath ? readResultFile(location.resultPath) : undefined;
	const runId = status?.runId ?? result?.runId ?? result?.id ?? location.resolvedId ?? (location.asyncDir ? path.basename(location.asyncDir) : "unknown");
	const mode = resumeTargetMode(status, result);
	if (options.sessionId && ((status && status.sessionId !== options.sessionId) || (result && result.sessionId !== options.sessionId))) {
		throw new Error(`Async run '${runId}' was not found in the active session.`);
	}
	if (recoveryDescriptor && recoveryDescriptor.sourceRunId !== runId) throw new Error(`Async run '${runId}' has a recovery descriptor for a different source run.`);
	const state = status?.state ?? (result ? resultState(result) : undefined);
	if (!state) throw new Error(`Status file not found for async run '${runId}'.`);
	if (state === "stopped") throw new Error(`Async run '${runId}' was stopped and cannot be resumed. Start a new run instead.`);

	const statusSteps = status?.steps ?? [];
	const resultSteps = result?.results ?? [];
	const stepCount = statusSteps.length || resultSteps.length || (result?.agent ? 1 : 0);
	const requestedIndex = params.index;
	if (requestedIndex !== undefined && !Number.isInteger(requestedIndex)) throw new Error(`Async run '${runId}' index must be an integer.`);
	const terminalStepStatuses = new Set(["complete", "completed", "failed", "paused"]);

	if (state === "running") {
		if (requestedIndex !== undefined) {
			if (requestedIndex < 0 || requestedIndex >= stepCount) throw new Error(`Async run '${runId}' has ${stepCount} children. Index ${requestedIndex} is out of range.`);
			const selectedStep = statusSteps[requestedIndex];
			if (selectedStep?.status === "running") {
				const capabilityCeiling = intersectSubagentCapabilityCeilings(status?.capabilityCeiling, selectedStep.capabilityCeiling);
				return {
					kind: "live",
					runId,
					asyncDir: location.asyncDir ?? undefined,
					state,
					...(mode ? { mode } : {}),
					agent: selectedStep.agent,
					index: requestedIndex,
					cwd: status?.cwd ?? result?.cwd,
					sessionFile: selectedStep.sessionFile ?? status?.sessionFile ?? result?.sessionFile,
					model: selectedStep.model,
					thinking: selectedStep.thinking,
					launchContractDigest: selectedStep.launchContractDigest ?? result?.results?.[requestedIndex]?.launchContractDigest ?? result?.launchContractDigest ?? recoveryDescriptor?.launchContractDigest,
					...(selectedStep.runner ? { runner: selectedStep.runner } : {}),
					...(selectedStep.externalJob ? { externalJob: selectedStep.externalJob } : {}),
					...(capabilityCeiling ? { capabilityCeiling } : {}),
					...(selectedStep.thinkingCeiling ? { thinkingCeiling: selectedStep.thinkingCeiling } : {}),
					...(recoveryDescriptor ? { recoveryDescriptor } : {}),
				};
			}
			if (selectedStep?.status === "pending") throw new Error(`Async run '${runId}' child ${requestedIndex} is pending and has not started yet. Wait for it to run or complete before resuming.`);
			if (selectedStep && !terminalStepStatuses.has(selectedStep.status)) throw new Error(`Async run '${runId}' child ${requestedIndex} is ${selectedStep.status} and cannot be revived yet.`);
		} else {
			const running = statusSteps
				.map((step, index) => ({ step, index }))
				.filter(({ step }) => step.status === "running");
			const selected = running.length === 1 ? running[0] : undefined;
			if (!selected) {
				throw new Error(`Async run '${runId}' has ${running.length} running children. Provide index to choose one.`);
			}
			const capabilityCeiling = intersectSubagentCapabilityCeilings(status?.capabilityCeiling, selected.step.capabilityCeiling);
			return {
				kind: "live",
				runId,
				asyncDir: location.asyncDir ?? undefined,
				state,
				...(mode ? { mode } : {}),
				agent: selected.step.agent,
				index: selected.index,
				cwd: status?.cwd ?? result?.cwd,
				sessionFile: selected.step.sessionFile ?? status?.sessionFile ?? result?.sessionFile,
				model: selected.step.model,
				thinking: selected.step.thinking,
				launchContractDigest: selected.step.launchContractDigest ?? result?.results?.[selected.index]?.launchContractDigest ?? result?.launchContractDigest ?? recoveryDescriptor?.launchContractDigest,
				...(selected.step.runner ? { runner: selected.step.runner } : {}),
				...(selected.step.externalJob ? { externalJob: selected.step.externalJob } : {}),
				...(capabilityCeiling ? { capabilityCeiling } : {}),
				...(selected.step.thinkingCeiling ? { thinkingCeiling: selected.step.thinkingCeiling } : {}),
				...(recoveryDescriptor ? { recoveryDescriptor } : {}),
			};
		}
	}

	if (stepCount > 1 && requestedIndex === undefined) {
		throw new Error(`Async run '${runId}' has ${stepCount} children. Provide index to choose one.`);
	}
	const index = requestedIndex ?? 0;
	if (!Number.isInteger(index)) throw new Error(`Async run '${runId}' index must be an integer.`);
	if (index < 0 || index >= stepCount) throw new Error(`Async run '${runId}' has ${stepCount} children. Index ${index} is out of range.`);
	const agent = statusSteps[index]?.agent ?? resultSteps[index]?.agent ?? result?.agent;
	if (!agent) throw new Error(`Could not determine child agent for async run '${runId}'.`);
	if (recoveryDescriptor && recoveryDescriptor.agent !== agent) throw new Error(`Async run '${runId}' has a recovery descriptor for '${recoveryDescriptor.agent}', not '${agent}'.`);
	const sessionFile = statusSteps[index]?.sessionFile
		?? resultSteps[index]?.sessionFile
		?? (stepCount === 1 ? status?.sessionFile ?? result?.sessionFile : undefined);
	if (!sessionFile && requireSessionFile) throw new Error(`Async run '${runId}' child ${index} does not have a persisted session file to resume from.`);
	const resolvedSessionFile = sessionFile ? validateResumeSessionFile(runId, sessionFile) : undefined;
	const stepModel = statusSteps[index]?.model ?? resultSteps[index]?.model ?? (stepCount === 1 ? result?.model : undefined);
	const stepThinking = statusSteps[index]?.thinking ?? resultSteps[index]?.thinking ?? (stepCount === 1 ? result?.thinking : undefined);
	const thinkingCeiling = statusSteps[index]?.thinkingCeiling ?? (stepCount === 1 ? recoveryDescriptor?.thinkingCeiling : undefined);
	const capabilityCeiling = intersectSubagentCapabilityCeilings(status?.capabilityCeiling, statusSteps[index]?.capabilityCeiling, result?.capabilityCeiling, resultSteps[index]?.capabilityCeiling);
	const managedWorktreeCwd = location.asyncDir
		? resolveRetainedWorktreeCwd(parallelHandoffPath(location.asyncDir), runId, index)
		: undefined;
	const resumeCwd = validateResumeCwd(runId, managedWorktreeCwd ?? status?.cwd ?? result?.cwd ?? recoveryDescriptor?.cwd);

	return {
		kind: "revive",
		runId,
		asyncDir: location.asyncDir ?? undefined,
		state,
		...(mode ? { mode } : {}),
		agent,
		index,
		...(resumeCwd ? { cwd: resumeCwd } : {}),
		...(resolvedSessionFile ? { sessionFile: resolvedSessionFile } : {}),
		...(stepModel ? { model: stepModel } : {}),
		...(stepThinking ? { thinking: stepThinking } : {}),
		launchContractDigest: statusSteps[index]?.launchContractDigest ?? resultSteps[index]?.launchContractDigest ?? result?.launchContractDigest ?? recoveryDescriptor?.launchContractDigest,
		...(statusSteps[index]?.runner ? { runner: statusSteps[index]!.runner } : {}),
		...(statusSteps[index]?.externalJob ? { externalJob: statusSteps[index]!.externalJob } : {}),
		...(capabilityCeiling ? { capabilityCeiling } : {}),
		...(thinkingCeiling ? { thinkingCeiling } : {}),
		...(recoveryDescriptor ? { recoveryDescriptor } : {}),
	};
}

export function applySteeringRecoveryAgentConfig(agentConfig: AgentConfig, descriptor: SteeringRecoveryDescriptor): AgentConfig {
	return {
		...agentConfig,
		model: descriptor.model,
		modelProvider: descriptor.modelProvider,
		fallbackModels: descriptor.fallbackModels ? [...descriptor.fallbackModels] : undefined,
		thinking: descriptor.thinking,
		maxThinking: intersectThinkingCeilings(descriptor.thinkingCeiling, agentConfig.maxThinking),
		tools: descriptor.tools ? [...descriptor.tools] : undefined,
		extensions: descriptor.extensions ? [...descriptor.extensions] : undefined,
		subagentOnlyExtensions: descriptor.subagentOnlyExtensions ? [...descriptor.subagentOnlyExtensions] : undefined,
		mcpDirectTools: descriptor.mcpDirectTools ? [...descriptor.mcpDirectTools] : undefined,
		systemPrompt: descriptor.systemPrompt ?? agentConfig.systemPrompt,
		systemPromptMode: descriptor.systemPromptMode,
		inheritProjectContext: descriptor.inheritProjectContext,
		inheritSkills: descriptor.inheritSkills,
		skills: descriptor.skills ? [...descriptor.skills] : undefined,
		skillPath: descriptor.skillPath ? [...descriptor.skillPath] : undefined,
		filePath: descriptor.agentFilePath as string,
		completionGuard: descriptor.completionGuard,
		memory: descriptor.memory ? { ...descriptor.memory } : undefined,
		output: descriptor.outputPath,
		toolBudget: descriptor.initialToolBudget,
		maxSubagentDepth: descriptor.maxSubagentDepth,
	};
}

export function buildRevivedAsyncTask(target: AsyncResumeTarget, message: string): string {
	return [
		"You are reviving a previous subagent conversation.",
		"",
		`Original run: ${target.runId}`,
		`Original agent: ${target.agent}`,
		target.sessionFile ? `Original session file: ${target.sessionFile}` : undefined,
		"",
		"Use the stored session context as background. Answer the orchestrator's follow-up below. Do not assume the original child process is still alive.",
		"",
		"Follow-up:",
		message,
	].filter((line): line is string => line !== undefined).join("\n");
}

import { spawnSync } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { randomUUID } from "node:crypto";
import { Worker } from "node:worker_threads";
import { writeAtomicJson } from "../../shared/atomic-json.ts";
import type { AsyncStatus } from "../../shared/types.ts";
import { MISSION_BINDING_FILE } from "../../missions/lifecycle.ts";
import { ACTIVE_RUN_INDEX_DIR } from "./active-run-index.ts";
import { encodeIndexSegment } from "./index-segment.ts";

export const ASYNC_RETENTION_DAYS = 30;
export const ASYNC_RETENTION_BATCH_SIZE = 100;
export const ASYNC_RETENTION_DELAY_MS = 60_000;
export const ASYNC_RETENTION_TOMBSTONE_GRACE_MS = 24 * 60 * 60 * 1000;

const RETENTION_MS = ASYNC_RETENTION_DAYS * 24 * 60 * 60 * 1000;
const LOCK_NAME = ".async-retention.lock";
const CURSOR_NAME = ".async-retention-cursor.json";
const LOG_NAME = "async-retention-maintenance.jsonl";
const RUN_TOMBSTONE_PREFIX = ".deleting-run-";
const RESULT_TOMBSTONE_PREFIX = ".deleting-result-";
const RUN_TOMBSTONE_MARKERS_DIR = "async-retention-run-tombstones";
const LOCK_STALE_MS = 24 * 60 * 60 * 1000;
const RUN_MODES = new Set<AsyncStatus["mode"]>(["single", "parallel", "chain", "workflow"]);
const TERMINAL_STATES = new Set<AsyncStatus["state"]>(["complete", "failed", "stopped", "rejected"]);
const RESULT_TIMESTAMP_FIELDS = ["endedAt", "completedAt", "createdAt", "writtenAt", "expiresAt", "timestamp"] as const;

interface RetentionCursor {
	version: 1;
	runAfter?: string;
	resultAfter?: string;
	resultPublicAfter?: string;
	resultPendingAfterBySession?: Record<string, string>;
	resultReplayAfter?: string;
	resultArchiveAfter?: string;
	pendingSessionAfter?: string;
}

type ResultCursorKey = keyof Pick<RetentionCursor, "resultPublicAfter" | "resultReplayAfter" | "resultArchiveAfter">;
type ResultCursorTarget = { type: "result"; key: ResultCursorKey } | { type: "pending"; session: string };

interface ResultCandidate {
	path: string;
	relative: string;
	kind: "public" | "pending" | "replay" | "archive" | "tombstone";
	cursor: ResultCursorTarget;
}

interface DiscoveredRunCandidate {
	name: string;
	relative: string;
}

type CursorOperation =
	| { type: "set"; key: Exclude<keyof RetentionCursor, "version" | "resultPendingAfterBySession">; value: string }
	| { type: "delete"; key: Exclude<keyof RetentionCursor, "version" | "resultPendingAfterBySession"> }
	| { type: "set-pending"; session: string; value: string }
	| { type: "delete-pending"; session: string };

interface RetentionDiscovery {
	discoveryDurationMs: number;
	rawReads: number;
	sourceExhausted: Record<string, boolean>;
	runCandidates: DiscoveredRunCandidate[];
	resultCandidates: Array<Omit<ResultCandidate, "path">>;
	cursorOps: CursorOperation[];
}

interface RetentionLockOwner {
	version: 1;
	token: string;
	pid: number;
	hostname: string;
	startedAt: number;
	processStartIdentity?: string;
}

export interface AsyncRetentionOptions {
	asyncDirRoot: string;
	resultsDir: string;
	waitSubscriptionsDir?: string;
	protectedRunIds?: Iterable<string>;
	now?: () => number;
	retentionMs?: number;
	tombstoneGraceMs?: number;
	batchSize?: number;
	randomId?: () => string;
	maintenanceRoot?: string;
	pid?: number;
	hostname?: string;
	processStartIdentity?: string;
	isProcessAlive?: (pid: number) => boolean | undefined;
	getProcessStartIdentity?: (pid: number) => string | undefined;
	lstatSync?: typeof fs.lstatSync;
	signal?: AbortSignal;
	discoveryWorkerUrl?: URL;
}

export interface AsyncRetentionResult {
	acquired: boolean;
	scanned: number;
	deletedRuns: number;
	deletedResults: number;
	reapedTombstones: number;
	skipped: Record<string, number>;
	errors: string[];
	rawReads: number;
	sourceExhausted: Record<string, boolean>;
	discoveryDurationMs: number;
	commitDurationMs: number;
	cancelled: boolean;
	workerFailed: boolean;
	durationMs: number;
}

function isNotFound(error: unknown): boolean {
	return typeof error === "object" && error !== null && "code" in error && (error as NodeJS.ErrnoException).code === "ENOENT";
}

function compactError(error: unknown): string {
	const message = error instanceof Error ? error.message : String(error);
	return message.replace(/\s+/g, " ").slice(0, 240);
}

function listDir(dir: string): fs.Dirent[] {
	try {
		return fs.readdirSync(dir, { withFileTypes: true });
	} catch (error) {
		if (isNotFound(error)) return [];
		throw error;
	}
}

function readJson(filePath: string): Record<string, unknown> | undefined {
	try {
		const parsed = JSON.parse(fs.readFileSync(filePath, "utf-8")) as unknown;
		return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as Record<string, unknown> : undefined;
	} catch {
		return undefined;
	}
}

function readStatus(runDir: string): AsyncStatus | undefined {
	const value = readJson(path.join(runDir, "status.json"));
	if (!value
		|| typeof value.runId !== "string"
		|| typeof value.state !== "string"
		|| typeof value.mode !== "string"
		|| !RUN_MODES.has(value.mode as AsyncStatus["mode"])
		|| typeof value.startedAt !== "number"
		|| !Number.isFinite(value.startedAt)) return undefined;
	return value as unknown as AsyncStatus;
}

function existingRegularFile(filePath: string | undefined): boolean {
	if (!filePath) return false;
	try {
		const stat = fs.lstatSync(filePath);
		return stat.isFile() && !stat.isSymbolicLink();
	} catch (error) {
		return !isNotFound(error);
	}
}

function validRunId(runId: string): boolean {
	return runId.length > 0 && runId !== "." && runId !== ".." && path.basename(runId) === runId;
}

function statusTimestamp(status: AsyncStatus, runDir: string): number | undefined {
	if (status.endedAt !== undefined && (typeof status.endedAt !== "number" || !Number.isFinite(status.endedAt))) return undefined;
	if (status.lastUpdate !== undefined && (typeof status.lastUpdate !== "number" || !Number.isFinite(status.lastUpdate))) return undefined;
	const logical = status.endedAt ?? status.lastUpdate;
	try {
		const physical = Math.max(fs.statSync(runDir).mtimeMs, fs.statSync(path.join(runDir, "status.json")).mtimeMs);
		const timestamp = logical === undefined ? physical : Math.max(logical, physical);
		return Number.isFinite(timestamp) ? timestamp : undefined;
	} catch {
		return undefined;
	}
}

function hasNestedReferences(status: AsyncStatus): boolean {
	return status.isNested === true || (status.steps ?? []).some((step) => (step.children?.length ?? 0) > 0);
}

function hasResumableContract(runDir: string, status: AsyncStatus): boolean {
	const statusSessionFiles = [status.sessionFile, ...(status.steps ?? []).map((step) => step.sessionFile)];
	if (statusSessionFiles.some(existingRegularFile)) return true;
	const descriptorPath = path.join(runDir, "recovery-descriptor.json");
	if (!fs.existsSync(descriptorPath)) return false;
	const descriptor = readJson(descriptorPath);
	if (!descriptor) return true;
	const sessionFiles = [
		typeof descriptor.sessionFile === "string" ? descriptor.sessionFile : undefined,
	];
	if (descriptor.sourceRunId !== status.runId) return true;
	return sessionFiles.some(existingRegularFile);
}

function activeMarkerExists(asyncDirRoot: string, runId: string): boolean {
	return fs.existsSync(path.join(asyncDirRoot, ACTIVE_RUN_INDEX_DIR, runId));
}

function missionObserverIndexExists(resultsDir: string, runId: string): boolean {
	return fs.existsSync(path.join(resultsDir, "result-index", "observers", "mission", `${encodeIndexSegment(runId)}.json`));
}

function runTombstoneMarkerPath(maintenanceRoot: string, runId: string): string {
	return path.join(maintenanceRoot, RUN_TOMBSTONE_MARKERS_DIR, `${encodeIndexSegment(runId)}.json`);
}

function writeRunTombstoneMarker(maintenanceRoot: string, runId: string, tombstonePath: string, now: number): void {
	const markerPath = runTombstoneMarkerPath(maintenanceRoot, runId);
	fs.mkdirSync(path.dirname(markerPath), { recursive: true });
	writeAtomicJson(markerPath, { version: 1, runId, tombstonePath, createdAt: now });
}

function removeRunTombstoneMarker(maintenanceRoot: string, runId: string): void {
	fs.rmSync(runTombstoneMarkerPath(maintenanceRoot, runId), { force: true });
}

function readRunTombstoneMarker(maintenanceRoot: string, runId: string): { runId: string; tombstonePath: string } | undefined | "unreadable" {
	const markerPath = runTombstoneMarkerPath(maintenanceRoot, runId);
	try {
		const stat = fs.lstatSync(markerPath);
		if (!stat.isFile() || stat.isSymbolicLink()) return "unreadable";
	} catch (error) {
		return isNotFound(error) ? undefined : "unreadable";
	}
	const marker = readJson(markerPath);
	if (marker?.version !== 1 || marker.runId !== runId || typeof marker.tombstonePath !== "string" || !marker.tombstonePath) return "unreadable";
	return { runId, tombstonePath: marker.tombstonePath };
}

function runTombstoneMarkerMatches(maintenanceRoot: string, runId: string, tombstonePath: string): boolean {
	const marker = readRunTombstoneMarker(maintenanceRoot, runId);
	return marker !== undefined && marker !== "unreadable" && path.resolve(marker.tombstonePath) === path.resolve(tombstonePath);
}

function runTombstoneMarkerBlocks(maintenanceRoot: string, runId: string): boolean {
	const marker = readRunTombstoneMarker(maintenanceRoot, runId);
	if (marker === undefined) return false;
	if (marker === "unreadable") return true;
	try {
		if (fs.existsSync(marker.tombstonePath)) return true;
		removeRunTombstoneMarker(maintenanceRoot, runId);
		return false;
	} catch {
		return true;
	}
}

function unresolvedHandoff(manifestPath: string): boolean {
	const manifest = readJson(manifestPath);
	if (!manifest || manifest.version !== 1 || !Array.isArray(manifest.groups) || manifest.groups.length === 0) return true;
	return manifest.groups.some((value) => {
		if (!value || typeof value !== "object" || Array.isArray(value)) return true;
		const cleanup = (value as Record<string, unknown>).cleanup;
		return !cleanup || typeof cleanup !== "object" || Array.isArray(cleanup) || (cleanup as Record<string, unknown>).state !== "complete";
	});
}

function hasUnresolvedRunHandoff(runDir: string, status: AsyncStatus): boolean {
	const paths = new Set<string>();
	if (status.parallelHandoff) {
		if (typeof status.parallelHandoff.path !== "string" || !status.parallelHandoff.path) return true;
		paths.add(status.parallelHandoff.path);
	}
	const localPath = path.join(runDir, "handoff.json");
	if (fs.existsSync(localPath)) paths.add(localPath);
	return [...paths].some(unresolvedHandoff);
}

function runSkipReason(input: {
	runDir: string;
	status: AsyncStatus | undefined;
	asyncDirRoot: string;
	resultsDir: string;
	cutoff: number;
	protectedRunIds: ReadonlySet<string>;
	waitRunIds: ReadonlySet<string>;
}): string | undefined {
	const { runDir, status } = input;
	if (!status) return "invalid-status";
	if (!validRunId(status.runId)) return "identity-mismatch";
	if (path.basename(runDir) !== status.runId && !path.basename(runDir).startsWith(RUN_TOMBSTONE_PREFIX)) return "identity-mismatch";
	if (input.protectedRunIds.has(status.runId)) return "runtime-reference";
	if (input.waitRunIds.has(status.runId)) return "wait-reference";
	if (activeMarkerExists(input.asyncDirRoot, status.runId)) return "active-index";
	if (!TERMINAL_STATES.has(status.state)) return "non-terminal";
	if (status.mode === "workflow" || status.parentWorkflowRunId || status.workflowKey) return "workflow-reference";
	if (hasNestedReferences(status)) return "nested-reference";
	if (fs.existsSync(path.join(runDir, MISSION_BINDING_FILE)) || missionObserverIndexExists(input.resultsDir, status.runId)) return "mission-reference";
	if (hasUnresolvedRunHandoff(runDir, status)) return "handoff-reference";
	if (hasResumableContract(runDir, status)) return "resumable";
	const timestamp = statusTimestamp(status, runDir);
	if (timestamp === undefined) return "unknown-age";
	if (timestamp > input.cutoff) return "recent";
	return undefined;
}

function parseWaitRunIds(dir: string): { runIds: Set<string>; safe: boolean } {
	const runIds = new Set<string>();
	for (const entry of listDir(dir)) {
		if (!entry.isFile() || !entry.name.endsWith(".json")) continue;
		const record = readJson(path.join(dir, entry.name));
		if (!record || typeof record.runId !== "string" || typeof record.expiresAt !== "number") return { runIds, safe: false };
		runIds.add(record.runId);
	}
	return { runIds, safe: true };
}

function readCursor(root: string): RetentionCursor {
	const value = readJson(path.join(root, CURSOR_NAME));
	return value?.version === 1 ? value as unknown as RetentionCursor : { version: 1 };
}

function processStartIdentity(pid: number): string | undefined {
	if (process.platform === "linux") {
		try {
			const stat = fs.readFileSync(`/proc/${pid}/stat`, "utf-8");
			const commandEnd = stat.lastIndexOf(")");
			if (commandEnd === -1) return undefined;
			const fields = stat.slice(commandEnd + 1).trim().split(/\s+/);
			return fields[19] ? `linux:${fields[19]}` : undefined;
		} catch {
			return undefined;
		}
	}
	if (process.platform === "win32") {
		const result = spawnSync("powershell.exe", ["-NoProfile", "-Command", `(Get-CimInstance Win32_Process -Filter "ProcessId=${pid}").CreationDate`], { encoding: "utf-8", windowsHide: true });
		const started = result.status === 0 ? result.stdout.trim() : "";
		return started ? `win:${started}` : undefined;
	}
	return undefined;
}

function processIsAlive(pid: number): boolean | undefined {
	try {
		process.kill(pid, 0);
		return true;
	} catch (error) {
		const code = (error as NodeJS.ErrnoException).code;
		if (code === "ESRCH") return false;
		if (code === "EPERM") return true;
		return undefined;
	}
}

function parseLockOwner(lockDir: string): RetentionLockOwner | undefined {
	const owner = readJson(path.join(lockDir, "owner.json"));
	if (owner?.version !== 1
		|| typeof owner.token !== "string"
		|| typeof owner.pid !== "number"
		|| !Number.isInteger(owner.pid)
		|| owner.pid <= 0
		|| typeof owner.hostname !== "string"
		|| typeof owner.startedAt !== "number"
		|| !Number.isFinite(owner.startedAt)) return undefined;
	if (owner.processStartIdentity !== undefined && typeof owner.processStartIdentity !== "string") return undefined;
	return owner as unknown as RetentionLockOwner;
}

function staleLock(lockDir: string, now: number, options: Required<Pick<AsyncRetentionOptions, "hostname" | "isProcessAlive" | "getProcessStartIdentity">>): { stale: boolean; token?: string } {
	const owner = parseLockOwner(lockDir);
	if (!owner) {
		try {
			return { stale: now - fs.statSync(lockDir).mtimeMs >= LOCK_STALE_MS };
		} catch {
			return { stale: false };
		}
	}
	if (owner.hostname !== options.hostname) return { stale: false };
	const alive = options.isProcessAlive(owner.pid);
	if (alive === false) return { stale: true, token: owner.token };
	if (alive === true && owner.processStartIdentity) {
		const currentIdentity = options.getProcessStartIdentity(owner.pid);
		if (currentIdentity !== undefined && currentIdentity !== owner.processStartIdentity) return { stale: true, token: owner.token };
	}
	return { stale: now - owner.startedAt >= LOCK_STALE_MS, token: owner.token };
}

function createLockDirectory(lockDir: string, owner: RetentionLockOwner): boolean {
	try {
		fs.mkdirSync(lockDir, { mode: 0o700 });
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "EEXIST") return false;
		throw error;
	}
	try {
		fs.writeFileSync(path.join(lockDir, "owner.json"), JSON.stringify(owner), { encoding: "utf-8", mode: 0o600 });
		return true;
	} catch (error) {
		fs.rmSync(lockDir, { recursive: true, force: true });
		throw error;
	}
}

function acquireRetentionLock(lockDir: string, owner: RetentionLockOwner, options: Required<Pick<AsyncRetentionOptions, "hostname" | "isProcessAlive" | "getProcessStartIdentity">>): boolean {
	for (let attempt = 0; attempt < 4; attempt += 1) {
		if (createLockDirectory(lockDir, owner)) return true;
		const stale = staleLock(lockDir, owner.startedAt, options);
		if (!stale.stale) return false;
		const staleKey = (stale.token ?? owner.token).replace(/[^A-Za-z0-9._-]/g, "-");
		const tombstone = `${lockDir}.stale-${staleKey}`;
		try {
			fs.renameSync(lockDir, tombstone);
		} catch (error) {
			const code = (error as NodeJS.ErrnoException).code;
			if (code === "ENOENT" || fs.existsSync(tombstone)) continue;
			throw error;
		}
	}
	return false;
}

function releaseRetentionLock(lockDir: string, token: string): void {
	if (parseLockOwner(lockDir)?.token !== token) return;
	fs.rmSync(lockDir, { recursive: true, force: true });
}

function resultRunId(candidate: ResultCandidate, data: Record<string, unknown>): string | undefined {
	if (typeof data.runId === "string") return data.runId;
	if (typeof data.id === "string") return data.id;
	if ((candidate.kind === "public" || candidate.kind === "pending") && path.basename(candidate.path).endsWith(".json")) return path.basename(candidate.path, ".json");
	return undefined;
}

function resultTimestamp(data: Record<string, unknown>, filePath: string): number | undefined {
	for (const field of RESULT_TIMESTAMP_FIELDS) {
		const value = data[field];
		if (value !== undefined && (typeof value !== "number" || !Number.isFinite(value))) return undefined;
	}
	const logical = RESULT_TIMESTAMP_FIELDS.map((field) => data[field])
		.filter((value): value is number => typeof value === "number" && Number.isFinite(value));
	try {
		return Math.max(fs.statSync(filePath).mtimeMs, ...logical);
	} catch {
		return undefined;
	}
}

function terminalResult(data: Record<string, unknown>): boolean {
	return data.success === true || data.success === false || (typeof data.state === "string" && TERMINAL_STATES.has(data.state as AsyncStatus["state"]));
}

function resultHasResumableSession(data: Record<string, unknown>): boolean {
	if (existingRegularFile(typeof data.sessionFile === "string" ? data.sessionFile : undefined)) return true;
	return Array.isArray(data.results) && data.results.some((value) => {
		if (!value || typeof value !== "object" || Array.isArray(value)) return false;
		const sessionFile = (value as Record<string, unknown>).sessionFile;
		return existingRegularFile(typeof sessionFile === "string" ? sessionFile : undefined);
	});
}

function hasUnresolvedResultHandoff(data: Record<string, unknown>): boolean {
	if (data.parallelHandoff === undefined) return false;
	if (!data.parallelHandoff || typeof data.parallelHandoff !== "object" || Array.isArray(data.parallelHandoff)) return true;
	const manifestPath = (data.parallelHandoff as Record<string, unknown>).path;
	return typeof manifestPath !== "string" || !manifestPath || unresolvedHandoff(manifestPath);
}

function completionMode(data: Record<string, unknown>): unknown {
	return data.completion && typeof data.completion === "object" && !Array.isArray(data.completion)
		? (data.completion as Record<string, unknown>).mode
		: undefined;
}

function resultSkipReason(input: {
	candidate: ResultCandidate;
	data: Record<string, unknown> | undefined;
	asyncDirRoot: string;
	resultsDir: string;
	maintenanceRoot: string;
	cutoff: number;
	protectedRunIds: ReadonlySet<string>;
	waitRunIds: ReadonlySet<string>;
}): string | undefined {
	if (!input.data) return "invalid-result";
	const runId = resultRunId(input.candidate, input.data);
	if (!runId || !validRunId(runId)) return "invalid-result";
	if (runTombstoneMarkerBlocks(input.maintenanceRoot, runId)) return "run-tombstone-present";
	if (input.protectedRunIds.has(runId)) return "runtime-reference";
	if (input.waitRunIds.has(runId)) return "wait-reference";
	if (activeMarkerExists(input.asyncDirRoot, runId)) return "active-index";
	if (fs.existsSync(path.join(input.asyncDirRoot, runId))) return "run-present";
	if (missionObserverIndexExists(input.resultsDir, runId)) return "mission-reference";
	if (input.data.mode === "workflow" || completionMode(input.data) === "workflow" || typeof input.data.parentWorkflowRunId === "string" || typeof input.data.workflowKey === "string") return "workflow-reference";
	if (hasUnresolvedResultHandoff(input.data)) return "handoff-reference";
	if (resultHasResumableSession(input.data)) return "resumable";
	if (input.candidate.kind === "archive" && fs.existsSync(path.join(input.resultsDir, "completion-replay", `${encodeURIComponent(runId)}.json`))) return "replay-reference";
	if (!terminalResult(input.data) && input.candidate.kind !== "replay" && input.candidate.kind !== "archive" && input.candidate.kind !== "tombstone") return "non-terminal-result";
	const timestamp = resultTimestamp(input.data, input.candidate.path);
	if (timestamp === undefined) return "unknown-age";
	if (timestamp > input.cutoff) return "recent";
	return undefined;
}

function appendMaintenanceLog(root: string, result: AsyncRetentionResult, now: number, deletedIds: string[]): void {
	fs.mkdirSync(root, { recursive: true });
	fs.appendFileSync(path.join(root, LOG_NAME), `${JSON.stringify({
		at: new Date(now).toISOString(),
		acquired: result.acquired,
		scanned: result.scanned,
		deletedRuns: result.deletedRuns,
		deletedResults: result.deletedResults,
		reapedTombstones: result.reapedTombstones,
		skipped: result.skipped,
		deleted: deletedIds.slice(0, ASYNC_RETENTION_BATCH_SIZE),
		errors: result.errors.length,
		rawReads: result.rawReads,
		sourceExhausted: result.sourceExhausted,
		discoveryDurationMs: result.discoveryDurationMs,
		commitDurationMs: result.commitDurationMs,
		cancelled: result.cancelled,
		workerFailed: result.workerFailed,
		durationMs: result.durationMs,
	})}\n`, "utf-8");
}

function increment(record: Record<string, number>, key: string): void {
	record[key] = (record[key] ?? 0) + 1;
}


class RetentionCancelledError extends Error {}

function isRecord(value: unknown): value is Record<string, unknown> {
	return value !== null && typeof value === "object" && !Array.isArray(value);
}

function safeRelative(relative: string): boolean {
	return relative.length > 0 && !path.isAbsolute(relative) && !relative.split(path.sep).includes("..");
}

function parseDiscoveryResult(message: unknown, passId: string, runBudget: number, resultBudget: number): RetentionDiscovery {
	if (!isRecord(message) || message.type !== "result" || message.passId !== passId) throw new Error("Retention discovery worker returned a stale or malformed pass id.");
	if (!Number.isFinite(message.discoveryDurationMs) || (message.discoveryDurationMs as number) < 0) throw new Error("Retention discovery worker returned an invalid duration.");
	if (!Number.isInteger(message.rawReads) || (message.rawReads as number) < 0) throw new Error("Retention discovery worker returned an invalid raw-read count.");
	if (!isRecord(message.sourceExhausted) || Object.values(message.sourceExhausted).some((value) => typeof value !== "boolean")) throw new Error("Retention discovery worker returned invalid source telemetry.");
	if (!Array.isArray(message.runCandidates) || message.runCandidates.length > runBudget) throw new Error("Retention discovery worker exceeded the run budget.");
	if (!Array.isArray(message.resultCandidates) || message.resultCandidates.length > resultBudget) throw new Error("Retention discovery worker exceeded the result budget.");
	if (!Array.isArray(message.cursorOps) || message.cursorOps.length > runBudget + resultBudget + 8) throw new Error("Retention discovery worker returned invalid cursor operations.");
	for (const candidate of message.runCandidates) {
		if (!isRecord(candidate) || typeof candidate.name !== "string" || typeof candidate.relative !== "string" || !validRunId(candidate.name) || candidate.relative !== candidate.name) throw new Error("Retention discovery worker returned an unsafe run candidate.");
	}
	const resultKinds = new Set(["public", "pending", "replay", "archive", "tombstone"]);
	const resultKeys = new Set(["resultPublicAfter", "resultReplayAfter", "resultArchiveAfter"]);
	for (const candidate of message.resultCandidates) {
		if (!isRecord(candidate) || typeof candidate.name !== "string" || typeof candidate.relative !== "string" || path.basename(candidate.name) !== candidate.name || !safeRelative(candidate.relative) || path.basename(candidate.relative) !== candidate.name || !resultKinds.has(candidate.kind as string) || !isRecord(candidate.cursor)) throw new Error("Retention discovery worker returned an unsafe result candidate.");
		const cursor = candidate.cursor;
		if (cursor.type === "pending") {
			if (typeof cursor.session !== "string" || !validRunId(cursor.session) || path.dirname(candidate.relative) !== path.join("result-pending", cursor.session)) throw new Error("Retention discovery worker returned an invalid pending candidate.");
		} else if (cursor.type === "result") {
			if (typeof cursor.key !== "string" || !resultKeys.has(cursor.key)) throw new Error("Retention discovery worker returned an invalid result cursor.");
			const expectedDir = cursor.key === "resultPublicAfter" ? "." : cursor.key === "resultReplayAfter" ? "completion-replay" : "output-archives";
			if (path.dirname(candidate.relative) !== expectedDir) throw new Error("Retention discovery worker returned a result from the wrong source.");
		} else throw new Error("Retention discovery worker returned an invalid result cursor target.");
	}
	const scalarKeys = new Set(["runAfter", "resultPublicAfter", "resultReplayAfter", "resultArchiveAfter", "pendingSessionAfter"]);
	for (const operation of message.cursorOps) {
		if (!isRecord(operation) || typeof operation.type !== "string") throw new Error("Retention discovery worker returned a malformed cursor operation.");
		if (operation.type === "set" || operation.type === "delete") {
			if (typeof operation.key !== "string" || !scalarKeys.has(operation.key) || (operation.type === "set" && (typeof operation.value !== "string" || !safeRelative(operation.value)))) throw new Error("Retention discovery worker returned an invalid scalar cursor operation.");
		} else if (operation.type === "set-pending" || operation.type === "delete-pending") {
			if (typeof operation.session !== "string" || !validRunId(operation.session) || (operation.type === "set-pending" && (typeof operation.value !== "string" || !safeRelative(operation.value)))) throw new Error("Retention discovery worker returned an invalid pending cursor operation.");
		} else throw new Error("Retention discovery worker returned an unknown cursor operation.");
	}
	return message as unknown as RetentionDiscovery;
}

function runRetentionDiscovery(input: {
	passId: string;
	asyncDirRoot: string;
	resultsDir: string;
	cursor: RetentionCursor;
	runBudget: number;
	resultBudget: number;
	workerUrl: URL;
	signal?: AbortSignal;
}): Promise<RetentionDiscovery> {
	return new Promise((resolve, reject) => {
		if (input.signal?.aborted) {
			reject(new RetentionCancelledError("Retention discovery was cancelled."));
			return;
		}
		const worker = new Worker(input.workerUrl);
		let settled = false;
		const cleanup = (): void => {
			input.signal?.removeEventListener("abort", onAbort);
			void worker.terminate();
		};
		const fail = (error: Error): void => {
			if (settled) return;
			settled = true;
			cleanup();
			reject(error);
		};
		const onAbort = (): void => fail(new RetentionCancelledError("Retention discovery was cancelled."));
		input.signal?.addEventListener("abort", onAbort, { once: true });
		worker.once("error", (error) => fail(error instanceof Error ? error : new Error(String(error))));
		worker.once("exit", (code) => {
			if (!settled) fail(new Error(`Retention discovery worker exited before replying (${code}).`));
		});
		worker.once("message", (message: unknown) => {
			if (settled) return;
			try {
				if (isRecord(message) && message.type === "error" && message.passId === input.passId) throw new Error(`Retention discovery failed: ${String(message.error)}`);
				const discovery = parseDiscoveryResult(message, input.passId, input.runBudget, input.resultBudget);
				settled = true;
				cleanup();
				resolve(discovery);
			} catch (error) {
				fail(error instanceof Error ? error : new Error(String(error)));
			}
		});
		worker.postMessage({ type: "discover", passId: input.passId, asyncDirRoot: input.asyncDirRoot, resultsDir: input.resultsDir, cursor: input.cursor, runBudget: input.runBudget, resultBudget: input.resultBudget });
	});
}

function applyCursorOperations(cursor: RetentionCursor, operations: CursorOperation[]): void {
	for (const operation of operations) {
		if (operation.type === "set") cursor[operation.key] = operation.value;
		else if (operation.type === "delete") delete cursor[operation.key];
		else if (operation.type === "set-pending") {
			cursor.resultPendingAfterBySession ??= {};
			cursor.resultPendingAfterBySession[operation.session] = operation.value;
		} else {
			delete cursor.resultPendingAfterBySession?.[operation.session];
			if (cursor.resultPendingAfterBySession && Object.keys(cursor.resultPendingAfterBySession).length === 0) delete cursor.resultPendingAfterBySession;
		}
	}
}

export async function cleanupAsyncRetention(options: AsyncRetentionOptions): Promise<AsyncRetentionResult> {
	const startedWall = Date.now();
	const now = options.now ?? Date.now;
	const currentTime = now();
	const retentionMs = options.retentionMs ?? RETENTION_MS;
	const tombstoneGraceMs = options.tombstoneGraceMs ?? ASYNC_RETENTION_TOMBSTONE_GRACE_MS;
	const batchSize = Math.min(ASYNC_RETENTION_BATCH_SIZE, Math.max(1, Math.trunc(options.batchSize ?? ASYNC_RETENTION_BATCH_SIZE)));
	const randomId = options.randomId ?? randomUUID;
	const maintenanceRoot = options.maintenanceRoot ?? path.dirname(options.asyncDirRoot);
	const lockDir = path.join(maintenanceRoot, LOCK_NAME);
	const lockToken = randomId();
	const pid = options.pid ?? process.pid;
	const hostname = options.hostname ?? os.hostname();
	const getProcessStartIdentity = options.getProcessStartIdentity ?? processStartIdentity;
	const currentProcessStartIdentity = options.processStartIdentity ?? getProcessStartIdentity(pid) ?? (pid === process.pid ? `runtime:${Math.round(Date.now() - process.uptime() * 1000)}` : undefined);
	const lockOwner: RetentionLockOwner = { version: 1, token: lockToken, pid, hostname, startedAt: currentTime, ...(currentProcessStartIdentity ? { processStartIdentity: currentProcessStartIdentity } : {}) };
	const lockOptions = { hostname, isProcessAlive: options.isProcessAlive ?? processIsAlive, getProcessStartIdentity };
	const result: AsyncRetentionResult = {
		acquired: false,
		scanned: 0,
		deletedRuns: 0,
		deletedResults: 0,
		reapedTombstones: 0,
		skipped: {},
		errors: [],
		rawReads: 0,
		sourceExhausted: {},
		discoveryDurationMs: 0,
		commitDurationMs: 0,
		cancelled: false,
		workerFailed: false,
		durationMs: 0,
	};
	const deletedIds: string[] = [];
	const lstatSync = options.lstatSync ?? fs.lstatSync;
	let commitStartedAt: number | undefined;
	let cursorCommitUnsafe = false;
	const finish = (): AsyncRetentionResult => {
		if (commitStartedAt !== undefined) result.commitDurationMs = Math.max(0, Date.now() - commitStartedAt);
		result.durationMs = Math.max(0, Date.now() - startedWall);
		appendMaintenanceLog(maintenanceRoot, result, currentTime, deletedIds);
		return result;
	};
	const markCancelled = (): boolean => {
		if (!options.signal?.aborted) return false;
		result.cancelled = true;
		increment(result.skipped, "cancelled");
		return true;
	};
	fs.mkdirSync(maintenanceRoot, { recursive: true });
	if (!acquireRetentionLock(lockDir, lockOwner, lockOptions)) {
		increment(result.skipped, "lock-busy");
		return finish();
	}
	result.acquired = true;
	try {
		if (markCancelled()) return finish();
		const protectedRunIds = new Set(options.protectedRunIds ?? []);
		const cutoff = currentTime - retentionMs;
		const cursor = readCursor(maintenanceRoot);
		const runBudget = Math.ceil(batchSize / 2);
		const resultBudget = batchSize - runBudget;
		const discoveryStartedAt = Date.now();
		let discovery: RetentionDiscovery;
		try {
			discovery = await runRetentionDiscovery({
				passId: randomUUID(),
				asyncDirRoot: options.asyncDirRoot,
				resultsDir: options.resultsDir,
				cursor,
				runBudget,
				resultBudget,
				workerUrl: options.discoveryWorkerUrl ?? new URL("../../../async-retention-discovery-worker.mjs", import.meta.url),
				signal: options.signal,
			});
		} catch (error) {
			result.discoveryDurationMs = Math.max(0, Date.now() - discoveryStartedAt);
			if (error instanceof RetentionCancelledError) {
				result.cancelled = true;
				increment(result.skipped, "cancelled");
			} else {
				result.workerFailed = true;
				increment(result.skipped, "worker-failure");
				result.errors.push(compactError(error));
			}
			return finish();
		}
		result.discoveryDurationMs = Math.max(0, Date.now() - discoveryStartedAt);
		result.rawReads = discovery.rawReads;
		result.sourceExhausted = discovery.sourceExhausted;
		commitStartedAt = Date.now();
		if (markCancelled()) return finish();
		if (parseLockOwner(lockDir)?.token !== lockToken) {
			increment(result.skipped, "lock-owner-changed");
			return finish();
		}
		const waitSubscriptionsDir = options.waitSubscriptionsDir ?? path.join(maintenanceRoot, "wait-subscriptions");
		// This safety scan stays on the commit thread. Wait records are the active,
		// swept subscription set. Each destructive action re-reads it to close the
		// race with a newly armed wait.
		const waitReferences = parseWaitRunIds(waitSubscriptionsDir);
		if (!waitReferences.safe) {
			increment(result.skipped, "wait-references-unknown");
			return finish();
		}
		for (const entry of discovery.runCandidates) {
			if (markCancelled()) return finish();
			result.scanned += 1;
			const runDir = path.join(options.asyncDirRoot, entry.name);
			let mutationStateChanged = false;
			try {
				const stat = lstatSync(runDir);
				if (!stat.isDirectory() || stat.isSymbolicLink()) {
					increment(result.skipped, "unsafe-run-path");
					continue;
				}
				const status = readStatus(runDir);
				const initialReason = runSkipReason({ runDir, status, asyncDirRoot: options.asyncDirRoot, resultsDir: options.resultsDir, cutoff, protectedRunIds, waitRunIds: waitReferences.runIds });
				if (initialReason) {
					increment(result.skipped, initialReason);
					continue;
				}
				if (entry.name.startsWith(RUN_TOMBSTONE_PREFIX)) {
					if (!runTombstoneMarkerMatches(maintenanceRoot, status!.runId, runDir)) {
						increment(result.skipped, "run-tombstone-marker");
						continue;
					}
					if (currentTime - stat.mtimeMs < tombstoneGraceMs) {
						increment(result.skipped, "tombstone-grace");
						continue;
					}
					const freshWaitReferences = parseWaitRunIds(waitSubscriptionsDir);
					const finalReason = freshWaitReferences.safe ? runSkipReason({ runDir, status, asyncDirRoot: options.asyncDirRoot, resultsDir: options.resultsDir, cutoff, protectedRunIds, waitRunIds: freshWaitReferences.runIds }) : "wait-references-unknown";
					if (finalReason) {
						increment(result.skipped, `recheck-${finalReason}`);
						continue;
					}
					mutationStateChanged = true;
					fs.rmSync(runDir, { recursive: true });
					removeRunTombstoneMarker(maintenanceRoot, status!.runId);
					result.reapedTombstones += 1;
					deletedIds.push(`run-tombstone:${status!.runId}`);
					continue;
				}
				const tombstone = path.join(options.asyncDirRoot, `${RUN_TOMBSTONE_PREFIX}${randomId()}`);
				writeRunTombstoneMarker(maintenanceRoot, status!.runId, tombstone, currentTime);
				mutationStateChanged = true;
				try {
					fs.renameSync(runDir, tombstone);
				} catch (error) {
					removeRunTombstoneMarker(maintenanceRoot, status!.runId);
					mutationStateChanged = false;
					throw error;
				}
				const recheckStatus = readStatus(tombstone);
				const freshWaitReferences = parseWaitRunIds(waitSubscriptionsDir);
				const recheckReason = freshWaitReferences.safe ? runSkipReason({ runDir: tombstone, status: recheckStatus, asyncDirRoot: options.asyncDirRoot, resultsDir: options.resultsDir, cutoff, protectedRunIds, waitRunIds: freshWaitReferences.runIds }) : "wait-references-unknown";
				if (recheckReason) {
					if (!fs.existsSync(runDir)) {
						fs.renameSync(tombstone, runDir);
						mutationStateChanged = false;
					}
					removeRunTombstoneMarker(maintenanceRoot, status!.runId);
					if (mutationStateChanged) cursorCommitUnsafe = true;
					increment(result.skipped, `recheck-${recheckReason}`);
					continue;
				}
				fs.rmSync(tombstone, { recursive: true });
				removeRunTombstoneMarker(maintenanceRoot, status!.runId);
				result.deletedRuns += 1;
				deletedIds.push(`run:${status!.runId}`);
			} catch (error) {
				if (mutationStateChanged) cursorCommitUnsafe = true;
				if (!isNotFound(error)) result.errors.push(compactError(error));
			}
		}
		for (const discoveredCandidate of discovery.resultCandidates) {
			if (markCancelled()) return finish();
			result.scanned += 1;
			const candidate: ResultCandidate = { ...discoveredCandidate, path: path.join(options.resultsDir, discoveredCandidate.relative) };
			let mutationStateChanged = false;
			try {
				const stat = lstatSync(candidate.path);
				if (!stat.isFile() || stat.isSymbolicLink()) {
					increment(result.skipped, "unsafe-result-path");
					continue;
				}
				const data = readJson(candidate.path);
				const reason = resultSkipReason({ candidate, data, asyncDirRoot: options.asyncDirRoot, resultsDir: options.resultsDir, maintenanceRoot, cutoff, protectedRunIds, waitRunIds: waitReferences.runIds });
				if (reason) {
					increment(result.skipped, reason);
					continue;
				}
				if (candidate.kind === "tombstone") {
					if (currentTime - stat.mtimeMs < tombstoneGraceMs) {
						increment(result.skipped, "tombstone-grace");
						continue;
					}
					const freshWaitReferences = parseWaitRunIds(waitSubscriptionsDir);
					const finalReason = freshWaitReferences.safe ? resultSkipReason({ candidate, data, asyncDirRoot: options.asyncDirRoot, resultsDir: options.resultsDir, maintenanceRoot, cutoff, protectedRunIds, waitRunIds: freshWaitReferences.runIds }) : "wait-references-unknown";
					if (finalReason) {
						increment(result.skipped, `recheck-${finalReason}`);
						continue;
					}
					fs.rmSync(candidate.path);
					mutationStateChanged = true;
					result.reapedTombstones += 1;
					deletedIds.push(`result-tombstone:${resultRunId(candidate, data!)}`);
					continue;
				}
				const tombstone = path.join(path.dirname(candidate.path), `${RESULT_TOMBSTONE_PREFIX}${candidate.kind}-${randomId()}`);
				fs.renameSync(candidate.path, tombstone);
				mutationStateChanged = true;
				const tombstoneCandidate = { ...candidate, path: tombstone, kind: "tombstone" as const };
				const recheckData = readJson(tombstone);
				const freshWaitReferences = parseWaitRunIds(waitSubscriptionsDir);
				const recheckReason = freshWaitReferences.safe ? resultSkipReason({ candidate: tombstoneCandidate, data: recheckData, asyncDirRoot: options.asyncDirRoot, resultsDir: options.resultsDir, maintenanceRoot, cutoff, protectedRunIds, waitRunIds: freshWaitReferences.runIds }) : "wait-references-unknown";
				if (recheckReason) {
					if (!fs.existsSync(candidate.path)) {
						fs.renameSync(tombstone, candidate.path);
						mutationStateChanged = false;
					}
					if (mutationStateChanged) cursorCommitUnsafe = true;
					increment(result.skipped, `recheck-${recheckReason}`);
					continue;
				}
				fs.rmSync(tombstone);
				result.deletedResults += 1;
				deletedIds.push(`result:${resultRunId(candidate, data!)}`);
			} catch (error) {
				if (mutationStateChanged) cursorCommitUnsafe = true;
				if (!isNotFound(error)) result.errors.push(compactError(error));
			}
		}
		if (cursorCommitUnsafe) {
			increment(result.skipped, "commit-failure");
			return finish();
		}
		if (markCancelled()) return finish();
		if (parseLockOwner(lockDir)?.token !== lockToken) {
			increment(result.skipped, "lock-owner-changed");
			return finish();
		}
		applyCursorOperations(cursor, discovery.cursorOps);
		writeAtomicJson(path.join(maintenanceRoot, CURSOR_NAME), cursor);
		return finish();
	} finally {
		try { releaseRetentionLock(lockDir, lockToken); } catch { /* a stale lock blocks the next pass safely */ }
	}
}

import { sanitizeDisplayText, truncateDisplayText } from "../../shared/display-text.ts";
import type { AsyncJobState, AsyncJobStep, NestedRunSummary, NestedStepSummary, SubagentRunMode, SubagentState } from "../../shared/types.ts";

export const ASYNC_STATUS_SNAPSHOT_KIND = "pi-subagents.async-status-snapshot";
export const ASYNC_STATUS_SNAPSHOT_VERSION = 1;
export const ASYNC_STATUS_SNAPSHOT_WIDGET_PREFIX = "PI_SUBAGENT_ASYNC_JSON:";

const DEFAULT_MAX_RUNS = 20;
const DEFAULT_MAX_CHILDREN_PER_NODE = 8;
const DEFAULT_MAX_DEPTH = 3;
const DEFAULT_MAX_STRING_LENGTH = 160;
const DEFAULT_MAX_SERIALIZED_BYTES = 32 * 1024;

export type AsyncStatusSnapshotState = "queued" | "running" | "complete" | "failed" | "paused" | "stopped" | "rejected";
export type AsyncStatusSnapshotKind = "subagent" | "workflow" | "step";

export interface AsyncStatusSnapshotActivityV1 {
	state?: string;
	currentTool?: string;
	lastActivityAt?: number;
	currentToolStartedAt?: number;
	turnCount?: number;
	toolCount?: number;
}

