	truncated?: boolean;
}

export interface CompletionArchive {
	version: 1;
	runId: string;
	createdAt: number;
	entries: CompletionArchiveEntry[];
}

export interface CompletionReplayRecord {
	version: 1;
	runId: string;
	sessionId: string;
	completedAt: number;
	expiresAt: number;
	completion: WaitCompletion;
	archivePath: string;
}

function safeRunFile(runId: string): string {
	return `${encodeURIComponent(runId)}.json`;
}

export function completionReplayPath(resultsDir: string, runId: string): string {
	return path.join(resultsDir, REPLAY_DIR_NAME, safeRunFile(runId));
}

export function completionArchivePath(resultsDir: string, runId: string): string {
	return path.join(resultsDir, ARCHIVE_DIR_NAME, safeRunFile(runId));
}

function nonEmptyString(value: unknown): string | undefined {
	return typeof value === "string" && value.length > 0 ? value : undefined;
}

function existingFile(value: unknown): string | undefined {
	const filePath = nonEmptyString(value);
	if (!filePath) return undefined;
	try {
		return fs.statSync(filePath).isFile() ? filePath : undefined;
	} catch {
		return undefined;
	}
}

function outputArtifactPath(child: Record<string, unknown>): string | undefined {
	if (!child.artifactPaths || typeof child.artifactPaths !== "object" || Array.isArray(child.artifactPaths)) return undefined;
	return existingFile((child.artifactPaths as Record<string, unknown>).outputPath);
}

/** Create a small archive that references saved child artifacts and retains only bounded fallback output text. */
export function writeCompletionArchive(resultsDir: string, runId: string, data: Record<string, unknown>, createdAt: number): string {
	const entries: CompletionArchiveEntry[] = [];
	const results = Array.isArray(data.results) ? data.results : [];
	for (let resultIndex = 0; resultIndex < results.length; resultIndex++) {
		const value = results[resultIndex];
		if (!value || typeof value !== "object" || Array.isArray(value)) continue;
		const child = value as Record<string, unknown>;
		const agent = nonEmptyString(child.agent);
		const artifactPath = outputArtifactPath(child);
		if (artifactPath) {
			entries.push({ ...(agent ? { agent } : {}), resultIndex, source: "output-artifact", path: artifactPath });
			continue;
		}
		const sessionPath = existingFile(child.sessionFile);
		if (sessionPath) {
			entries.push({ ...(agent ? { agent } : {}), resultIndex, source: "session", path: sessionPath });
			continue;
		}
		const output = nonEmptyString(child.output);
		const error = nonEmptyString(child.error);
		if (output || error) {
			const bounded = utf8Tail([error ? `Error: ${error}` : undefined, output].filter(Boolean).join("\n"), ARCHIVE_TEXT_LIMIT_BYTES);
			entries.push({
				...(agent ? { agent } : {}),
				resultIndex,
				source: "result-tail",
				text: bounded.text,
				...(bounded.truncated ? { truncated: true } : {}),
			});
		}
	}
	if (results.length === 0) {
		const sessionPath = existingFile(data.sessionFile);
		if (sessionPath) entries.push({ source: "session", path: sessionPath });
	}
	if (entries.length === 0) {
		const summary = nonEmptyString(data.summary);
		if (summary) {
			const bounded = utf8Tail(summary, ARCHIVE_TEXT_LIMIT_BYTES);
			entries.push({ source: "result-tail", text: bounded.text, ...(bounded.truncated ? { truncated: true } : {}) });
		}
	}
	const archive: CompletionArchive = { version: ARCHIVE_VERSION, runId, createdAt, entries };
	const archivePath = completionArchivePath(resultsDir, runId);
	writePrivateAtomicJson(archivePath, archive);
	return archivePath;
}

function parseCompletion(value: unknown, runId: string): WaitCompletion | undefined {
	if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
	const completion = value as Partial<WaitCompletion>;
	if (completion.runId !== runId) return undefined;
	return completion as WaitCompletion;
}

function parseReplay(value: unknown): CompletionReplayRecord | undefined {
	if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
	const record = value as Partial<CompletionReplayRecord>;
	if (record.version !== REPLAY_VERSION
		|| typeof record.runId !== "string"
		|| typeof record.sessionId !== "string"
		|| typeof record.completedAt !== "number"
		|| typeof record.expiresAt !== "number"
		|| typeof record.archivePath !== "string") return undefined;
	const completion = parseCompletion(record.completion, record.runId);
	return completion ? { ...record, completion } as CompletionReplayRecord : undefined;
}

function validateReplayRecord(resultsDir: string, runId: string, record: CompletionReplayRecord): CompletionReplayRecord | undefined {
	if (record.runId !== runId) return undefined;
	const archivePath = completionArchivePath(resultsDir, runId);
	return path.resolve(record.archivePath) === path.resolve(archivePath)
		? { ...record, archivePath, completion: { ...record.completion, archivePath } }
		: undefined;
}

function runIdFromReplayFile(file: string): string | undefined {
	if (!file.endsWith(".json")) return undefined;
	try {
		const runId = decodeURIComponent(file.slice(0, -".json".length));
		return safeRunFile(runId) === file ? runId : undefined;
	} catch {
		return undefined;
	}
}

function removeBestEffort(filePath: string): void {
	try {
		fs.rmSync(filePath, { force: true });
	} catch { /* cleanup only */ }
}

function parseArchive(value: unknown): CompletionArchive | undefined {
	if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
	const archive = value as Partial<CompletionArchive>;
	if (archive.version !== ARCHIVE_VERSION || typeof archive.runId !== "string" || typeof archive.createdAt !== "number" || !Array.isArray(archive.entries)) return undefined;
	const entries = archive.entries.flatMap((value): CompletionArchiveEntry[] => {
		if (!value || typeof value !== "object" || Array.isArray(value)) return [];
		const entry = value as Partial<CompletionArchiveEntry>;
		if (entry.source !== "output-artifact" && entry.source !== "session" && entry.source !== "result-tail") return [];
		return [{
			...(typeof entry.agent === "string" ? { agent: entry.agent } : {}),
			...(typeof entry.resultIndex === "number" && Number.isSafeInteger(entry.resultIndex) && entry.resultIndex >= 0 ? { resultIndex: entry.resultIndex } : {}),
			source: entry.source,
			...(typeof entry.path === "string" ? { path: entry.path } : {}),
			...(typeof entry.text === "string" ? { text: entry.text } : {}),
			...(entry.truncated === true ? { truncated: true } : {}),
		}];
	});
	return { version: ARCHIVE_VERSION, runId: archive.runId, createdAt: archive.createdAt, entries };
}

/** Persist a terminal completion before its one-shot result file is removed. */
export function writeCompletionReplay(input: {
	resultsDir: string;
	runId: string;
	sessionId: string;
	completion: WaitCompletion;
	data: Record<string, unknown>;
	now: number;
	ttlMs: number;
}): CompletionReplayRecord {
	const archivePath = writeCompletionArchive(input.resultsDir, input.runId, input.data, input.now);
	const completion = { ...input.completion, archivePath };
	const record: CompletionReplayRecord = {
		version: REPLAY_VERSION,
		runId: input.runId,
		sessionId: input.sessionId,
		completedAt: input.now,
		expiresAt: input.now + input.ttlMs,
		completion,
		archivePath,
	};
	writePrivateAtomicJson(completionReplayPath(input.resultsDir, input.runId), record);
	cleanupCompletionReplayIfDue(input.resultsDir, input.now, input.ttlMs);
	return record;
}

/** Read a current replay record. Unknown fields are ignored and unknown versions are skipped. */
export function readCompletionReplay(resultsDir: string, runId: string, options: { sessionId?: string; now?: number } = {}): CompletionReplayRecord | undefined {
	const replayPath = completionReplayPath(resultsDir, runId);
	let parsed: CompletionReplayRecord | undefined;
	try {
		parsed = parseReplay(JSON.parse(fs.readFileSync(replayPath, "utf-8")));
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
		throw error;
	}
	if (!parsed) return undefined;
	const safeRecord = validateReplayRecord(resultsDir, runId, parsed);
	if (!safeRecord) {
		removeBestEffort(replayPath);
		return undefined;
	}
	parsed = safeRecord;
	if (options.sessionId !== undefined && parsed.sessionId !== options.sessionId) return undefined;
	if (parsed.expiresAt <= (options.now ?? Date.now())) {
		removeBestEffort(replayPath);
		removeBestEffort(parsed.archivePath);
		return undefined;
	}
	return parsed;
}

export function readCompletionArchive(archivePath: string): CompletionArchive | undefined {
	try {
		const archive = parseArchive(JSON.parse(fs.readFileSync(archivePath, "utf-8")));
		if (!archive) throw new Error("Completion archive is malformed.");
		return archive;
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
		throw error;
	}
}

export function cleanupCompletionReplayIfDue(resultsDir: string, now: number, maxAgeMs: number, intervalMs = CLEANUP_INTERVAL_MS): boolean {
	const last = lastCleanupByResultsDir.get(resultsDir);
	if (last !== undefined && now - last < intervalMs) return false;
	lastCleanupByResultsDir.set(resultsDir, now);
	cleanupCompletionReplay(resultsDir, now, maxAgeMs);
	return true;
}

/** Opportunistically remove expired replay and orphan archive files without affecting delivery. */
export function cleanupCompletionReplay(resultsDir: string, now: number, maxAgeMs: number): void {
	const replayDir = path.join(resultsDir, REPLAY_DIR_NAME);
	try {
		for (const file of fs.readdirSync(replayDir)) {
			const runId = runIdFromReplayFile(file);
			if (!runId) continue;
			const filePath = path.join(replayDir, file);
			try {
				const record = parseReplay(JSON.parse(fs.readFileSync(filePath, "utf-8")));
				const safeRecord = record ? validateReplayRecord(resultsDir, runId, record) : undefined;
				if (record && !safeRecord) {
					fs.rmSync(filePath, { force: true });
				} else if (safeRecord && safeRecord.expiresAt <= now) {
					fs.rmSync(filePath, { force: true });
					fs.rmSync(safeRecord.archivePath, { force: true });
				} else if (!record && now - fs.statSync(filePath).mtimeMs > maxAgeMs) {
					fs.rmSync(filePath, { force: true });
				}
			} catch { /* one bad entry must not block cleanup */ }
		}
	} catch { /* replay directory may not exist yet */ }
	const archiveDir = path.join(resultsDir, ARCHIVE_DIR_NAME);
	try {
		for (const file of fs.readdirSync(archiveDir)) {
			const filePath = path.join(archiveDir, file);
			try {
				if (now - fs.statSync(filePath).mtimeMs > maxAgeMs) fs.rmSync(filePath, { force: true });
			} catch { /* one bad entry must not block cleanup */ }
		}
	} catch { /* archive directory may not exist yet */ }
}

/**
 * Cross-OS control channel for async subagent runs.
 *
 * Background runs are detached OS processes. The original control path delivered
 * an interrupt with `process.kill(pid, SIGUSR2|SIGBREAK)`, but Windows cannot
 * deliver those signals cross-process via `process.kill` and throws `ENOSYS`,
 * which left async runs uninterruptible (no stop, no live steer) on Windows.
 *
 * This module adds a portable, file-based control inbox inside the run directory.
 * The parent drops an interrupt request file; the runner watches the inbox and
 * routes the request into its existing graceful `interruptRunner()` (pause +
 * resumable), identically on every platform. The file inbox is authoritative and
 * avoids signaling a PID that the extension cannot prove belongs to the runner.
 */

import { randomUUID } from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import { writeAtomicJson } from "../../shared/atomic-json.ts";
import { POLL_INTERVAL_MS } from "../../shared/types.ts";
import { shouldUseNativeFsWatch } from "../../shared/watch-strategy.ts";
import { resolveWatchPath } from "../../shared/utils.ts";

export type ControlChannelFs = Pick<typeof fs, "mkdirSync" | "existsSync" | "rmSync" | "watch" | "readdirSync" | "readFileSync" | "realpathSync">;

function writeJsonToExistingDir(filePath: string, payload: object): void {
	const tempPath = path.join(path.dirname(filePath), `.${path.basename(filePath)}.${process.pid}.${Date.now()}.${randomUUID()}.tmp`);
	try {
		fs.writeFileSync(tempPath, JSON.stringify(payload, null, 2), { encoding: "utf-8", flag: "wx" });
		fs.renameSync(tempPath, filePath);
	} finally {
		fs.rmSync(tempPath, { force: true });
	}
}
export type ControlChannelTimers = { setInterval: typeof setInterval; clearInterval: typeof clearInterval };
const CONTROL_SAFETY_POLL_INTERVAL_MS = 5000;
type KillFn = (pid: number, signal?: NodeJS.Signals | 0) => unknown;

export interface InterruptRequest {
	type: "interrupt";
	ts?: number;
	source?: string;
	reason?: string;
}

export interface TimeoutRequest {
	type: "timeout";
	ts?: number;
	source?: string;
	reason?: string;
}

export interface StopRequest {
	type: "stop";
	ts?: number;
	source?: string;
	reason?: string;
	targetIndex?: number;
	childId?: string;
}

export type SteerDeliveryMode = "steer" | "follow_up" | "auto";
export type SteerDeliveryStatus = "delivered" | "queued";

export interface SteerRequest {
	type: "steer";
	id: string;
	ts: number;
	message: string;
	mode?: SteerDeliveryMode;
	targetIndex?: number;
	targetIndexes?: number[];
	source?: string;
}

export interface SteerCapability {
	type: "steer-capability";
	protocolVersion: 1;
	index: number;
	pid: number;
	readyAt: number;
	supported: boolean;
}

export interface SteerAck {
	type: "steer-ack";
	protocolVersion: 1;
	requestId: string;
	index: number;
	ts: number;
	state: "delivered" | "queued" | "failed";
	deliveryStatus?: SteerDeliveryStatus;
	message: string;
}

const STEER_REQUESTS_DIR = "steer-requests";
const STOP_REQUESTS_DIR = "stop-requests";
const REVIVAL_BRIEFS_DIR = "revival-briefs";
export const MAX_STEER_QUEUE_SIZE = 20;
const STEER_TARGETS_DIR = "steer-targets";
const STEER_CAPABILITIES_DIR = "steer-capabilities";
const STEER_ACKS_DIR = "steer-acks";
const STEER_INBOX_CLOSED_FILE = "steer-inbox-closed.json";
const MAX_STEER_MESSAGE_BYTES = 128 * 1024;
const MAX_STEER_REQUEST_ID_LENGTH = 256;

/** Control inbox directory inside an async run dir. */
export function controlInboxDir(asyncDir: string): string {
	return path.join(asyncDir, "control");
}

/** Path of the portable interrupt request file. */
export function interruptRequestPath(asyncDir: string): string {
	return path.join(controlInboxDir(asyncDir), "interrupt.json");
}

/** Path of the portable timeout request file. */
export function timeoutRequestPath(asyncDir: string): string {
	return path.join(controlInboxDir(asyncDir), "timeout.json");
}

/** Path of the portable manual stop request file. */
export function stopRequestPath(asyncDir: string): string {
	return path.join(controlInboxDir(asyncDir), "stop.json");
}

/** Directory of parent-to-runner stop requests. */
export function stopRequestsDir(asyncDir: string): string {
	return path.join(controlInboxDir(asyncDir), STOP_REQUESTS_DIR);
}

/** Directory of parent-to-runner steering requests. */
export function steerRequestsDir(asyncDir: string): string {
	return path.join(controlInboxDir(asyncDir), STEER_REQUESTS_DIR);
}

export function steerInboxClosedPath(asyncDir: string): string {
	return path.join(controlInboxDir(asyncDir), STEER_INBOX_CLOSED_FILE);
}

export function closeSteerInbox(asyncDir: string, state: string, write: (filePath: string, payload: object) => void = writeAtomicJson): void {
	write(steerInboxClosedPath(asyncDir), { version: 1, closedAt: Date.now(), state });
}

/** Per-child inbox consumed by the child prompt runtime inside the Pi process. */
export function stepSteerInboxDir(asyncDir: string, index: number): string {
	assertChildIndex(index);
	return path.join(controlInboxDir(asyncDir), STEER_TARGETS_DIR, String(index));
}

export function steerCapabilitiesDir(asyncDir: string): string {
	return path.join(controlInboxDir(asyncDir), STEER_CAPABILITIES_DIR);
}

export function steerCapabilityPath(asyncDir: string, index: number): string {
	assertChildIndex(index);
	return path.join(steerCapabilitiesDir(asyncDir), `${index}.json`);
}

export function steerAcksDir(asyncDir: string, index: number): string {
	assertChildIndex(index);
	return path.join(controlInboxDir(asyncDir), STEER_ACKS_DIR, String(index));
}

function steerAckFileName(requestId: string): string {
	return `${Buffer.from(requestId).toString("base64url")}.json`;
}

export function steerAckPathFromDir(dir: string, requestId: string): string {
	if (!/^[^\s]+$/.test(requestId) || requestId.length > 256) throw new Error("steer acknowledgment requestId is invalid.");
	return path.join(dir, steerAckFileName(requestId));
}

function assertChildIndex(index: number): void {
	if (!Number.isInteger(index) || index < 0 || index > 1_000_000) throw new Error("child index must be a non-negative integer.");
}

function validStopChildId(childId: unknown): childId is string {
	return typeof childId === "string"
		&& Boolean(childId.trim())
		&& childId.length <= 256
		&& !/[\r\n]/.test(childId);
}

function steerRequestFileName(request: SteerRequest): string {
	return `${String(request.ts).padStart(13, "0")}-${Buffer.from(request.id).toString("base64url")}.json`;
}

function stopRequestFileName(request: StopRequest): string {
	return `${String(request.ts ?? 0).padStart(13, "0")}-${randomUUID()}.json`;
}

function validSteerRequest(request: Partial<SteerRequest>): request is SteerRequest {
	return request.type === "steer"
		&& typeof request.id === "string"
		&& /^[^\s]+$/.test(request.id)
		&& request.id.length <= MAX_STEER_REQUEST_ID_LENGTH
		&& typeof request.ts === "number"
		&& Number.isFinite(request.ts)
		&& request.ts > 0
		&& typeof request.message === "string"
		&& Boolean(request.message.trim())
		&& Buffer.byteLength(request.message, "utf8") <= MAX_STEER_MESSAGE_BYTES
		&& (request.mode === undefined || request.mode === "steer" || request.mode === "follow_up" || request.mode === "auto")
		&& (request.targetIndex === undefined || (Number.isInteger(request.targetIndex) && request.targetIndex >= 0 && request.targetIndex <= 1_000_000))
		&& (request.targetIndexes === undefined || (
			request.targetIndex === undefined
			&& Array.isArray(request.targetIndexes)
			&& request.targetIndexes.length > 0
			&& request.targetIndexes.length <= 1_000
			&& request.targetIndexes.every((index) => Number.isInteger(index) && index >= 0 && index <= 1_000_000)
			&& new Set(request.targetIndexes).size === request.targetIndexes.length
		))
		&& (request.source === undefined || (typeof request.source === "string" && Boolean(request.source.trim()) && request.source.length <= 256));
}

export function writeSteerRequestToDir(dir: string, request: SteerRequest): string {
	if (!validSteerRequest(request)) throw new Error("steer request is malformed or exceeds transport limits.");
	const requestPath = path.join(dir, steerRequestFileName(request));
	writeAtomicJson(requestPath, request);
	return requestPath;
}

export function writeSteerRequestToExistingDir(dir: string, request: SteerRequest): string {
	if (!validSteerRequest(request)) throw new Error("steer request is malformed or exceeds transport limits.");
	const requestPath = path.join(dir, steerRequestFileName(request));
	writeJsonToExistingDir(requestPath, request);
	return requestPath;
}

export function writeSteerCapabilityAt(filePath: string, capability: Omit<SteerCapability, "type" | "protocolVersion">): string {
	assertChildIndex(capability.index);
	if (!Number.isInteger(capability.pid) || capability.pid <= 0) throw new Error("steer capability pid must be a positive integer.");
	if (!Number.isFinite(capability.readyAt) || capability.readyAt <= 0) throw new Error("steer capability readyAt must be a finite timestamp.");
	const record: SteerCapability = { type: "steer-capability", protocolVersion: 1, ...capability };
	writeAtomicJson(filePath, record);
	return filePath;
}

export function writeSteerCapability(asyncDir: string, capability: Omit<SteerCapability, "type" | "protocolVersion">): string {
	return writeSteerCapabilityAt(steerCapabilityPath(asyncDir, capability.index), capability);
}

function steerAckWritePath(filePath: string, ack: Omit<SteerAck, "type" | "protocolVersion">): string {
	const parsed = path.parse(filePath);
	const stateOrder = ack.state === "queued" ? "0" : ack.state === "delivered" ? "1" : "2";
	const timestamp = String(Math.trunc(ack.ts)).padStart(13, "0");
	for (let suffix = 0; suffix < 1_000; suffix += 1) {
		const candidate = path.join(parsed.dir, `${parsed.name}-${timestamp}-${stateOrder}-${ack.state}${suffix === 0 ? "" : `-${suffix}`}${parsed.ext}`);
		if (!fs.existsSync(candidate)) return candidate;
	}
	throw new Error("steer acknowledgment queue is full.");
}

export function writeSteerAckAt(filePath: string, ack: Omit<SteerAck, "type" | "protocolVersion">): string {
	assertChildIndex(ack.index);
	if (!/^[^\s]+$/.test(ack.requestId) || ack.requestId.length > 256) throw new Error("steer acknowledgment requestId is invalid.");
	if (!Number.isFinite(ack.ts) || ack.ts <= 0) throw new Error("steer acknowledgment ts must be a finite timestamp.");
	if (!ack.message.trim() || ack.message.length > 1000) throw new Error("steer acknowledgment message is invalid.");
	const record: SteerAck = { type: "steer-ack", protocolVersion: 1, ...ack, message: ack.message.trim() };
	const ackPath = steerAckWritePath(filePath, ack);
	writeAtomicJson(ackPath, record);
	return ackPath;
}

export function writeSteerAck(asyncDir: string, ack: Omit<SteerAck, "type" | "protocolVersion">): string {
	return writeSteerAckAt(path.join(steerAcksDir(asyncDir, ack.index), steerAckFileName(ack.requestId)), ack);
}

/**
 * Parent side: drop a portable interrupt request the runner's inbox watcher will
 * pick up regardless of OS. Written atomically (temp + rename), dir auto-created.
 */
export function requestAsyncInterrupt(
	asyncDir: string,
	payload: Omit<InterruptRequest, "type"> = {},
	deps: { now?: () => number } = {},
): string {
	const requestPath = interruptRequestPath(asyncDir);
	const request: InterruptRequest = { ...payload, ts: payload.ts ?? deps.now?.() ?? Date.now(), type: "interrupt" };
	writeAtomicJson(requestPath, request);
	return requestPath;
}

export function requestAsyncTimeout(
	asyncDir: string,
	payload: Omit<TimeoutRequest, "type"> = {},
	deps: { now?: () => number } = {},
): string {
	const requestPath = timeoutRequestPath(asyncDir);
	const request: TimeoutRequest = { ...payload, ts: payload.ts ?? deps.now?.() ?? Date.now(), type: "timeout" };
	writeAtomicJson(requestPath, request);
	return requestPath;
}

export function requestAsyncStop(
	asyncDir: string,
	payload: Omit<StopRequest, "type"> = {},
	deps: { now?: () => number } = {},
): string {
	if (payload.targetIndex !== undefined) assertChildIndex(payload.targetIndex);
	if (payload.childId !== undefined && !validStopChildId(payload.childId)) {
		throw new Error("stop childId must be a non-empty string without newlines and at most 256 characters.");
	}
	const request: StopRequest = { ...payload, ts: payload.ts ?? deps.now?.() ?? Date.now(), type: "stop" };
	const requestPath = path.join(stopRequestsDir(asyncDir), stopRequestFileName(request));
	writeAtomicJson(requestPath, request);
	return requestPath;
}

export function requestAsyncSteer(
	asyncDir: string,
	payload: { message: string; mode?: SteerDeliveryMode; targetIndex?: number; targetIndexes?: number[]; source?: string; id?: string; ts?: number },
	deps: { now?: () => number; randomId?: () => string } = {},
): string {
	const message = payload.message.trim();
	if (!message) throw new Error("steer message must not be empty.");
	if (Buffer.byteLength(message, "utf8") > MAX_STEER_MESSAGE_BYTES) throw new Error(`steer message exceeds ${MAX_STEER_MESSAGE_BYTES} UTF-8 bytes.`);
	if (payload.targetIndex !== undefined && (!Number.isInteger(payload.targetIndex) || payload.targetIndex < 0 || payload.targetIndex > 1_000_000)) {
		throw new Error("steer targetIndex must be an integer between 0 and 1000000.");
	}
	if (payload.targetIndexes !== undefined && (
		!Array.isArray(payload.targetIndexes)
		|| payload.targetIndex !== undefined
		|| payload.targetIndexes.length === 0
		|| payload.targetIndexes.length > 1_000
		|| payload.targetIndexes.some((index) => !Number.isInteger(index) || index < 0 || index > 1_000_000)
		|| new Set(payload.targetIndexes).size !== payload.targetIndexes.length
	)) {
		throw new Error("steer targetIndexes must contain 1-1000 unique non-negative integers and cannot be combined with targetIndex.");
	}
	const closedPath = steerInboxClosedPath(asyncDir);
	if (fs.existsSync(closedPath)) throw new Error("Async run no longer accepts steering requests.");
	const request: SteerRequest = {
		type: "steer",
		id: payload.id ?? deps.randomId?.() ?? randomUUID(),
		ts: payload.ts ?? deps.now?.() ?? Date.now(),
		message,
		...(payload.mode && payload.mode !== "steer" ? { mode: payload.mode } : {}),
		...(payload.targetIndex !== undefined ? { targetIndex: payload.targetIndex } : {}),
		...(payload.targetIndexes !== undefined ? { targetIndexes: [...payload.targetIndexes] } : {}),
		...(payload.source ? { source: payload.source } : {}),
	};
	const requestPath = writeSteerRequestToDir(steerRequestsDir(asyncDir), request);
	if (fs.existsSync(closedPath)) {
		fs.rmSync(requestPath, { force: true });
		throw new Error("Async run stopped accepting steering before the request was committed.");
	}
	return requestPath;
}

export function enqueueStepSteer(asyncDir: string, index: number, request: SteerRequest): string {
	assertChildIndex(index);
	const { targetIndexes: _targetIndexes, ...singleTargetRequest } = request;
	return writeSteerRequestToDir(stepSteerInboxDir(asyncDir, index), { ...singleTargetRequest, targetIndex: index, type: "steer" });
}

function parseSteerCapability(raw: unknown): SteerCapability | undefined {
	if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
	const input = raw as Partial<SteerCapability>;
	if (input.type !== "steer-capability" || input.protocolVersion !== 1) return undefined;
	const { index, pid, readyAt, supported } = input;
	if (typeof index !== "number" || !Number.isInteger(index) || index < 0 || index > 1_000_000) return undefined;
	if (typeof pid !== "number" || typeof readyAt !== "number" || !Number.isInteger(pid) || pid <= 0 || !Number.isFinite(readyAt) || readyAt <= 0 || typeof supported !== "boolean") return undefined;
	return { type: "steer-capability", protocolVersion: 1, index, pid, readyAt, supported };
}

function parseSteerAck(raw: unknown): SteerAck | undefined {
	if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
	const input = raw as Partial<SteerAck>;
	if (input.type !== "steer-ack" || input.protocolVersion !== 1 || typeof input.requestId !== "string" || !/^[^\s]+$/.test(input.requestId) || input.requestId.length > 256) return undefined;
	const { index, ts, state, message } = input;
	if (typeof index !== "number" || typeof ts !== "number" || !Number.isInteger(index) || index < 0 || index > 1_000_000 || !Number.isFinite(ts) || ts <= 0) return undefined;
	if (state !== "delivered" && state !== "queued" && state !== "failed") return undefined;
	if (input.deliveryStatus !== undefined && input.deliveryStatus !== "delivered" && input.deliveryStatus !== "queued") return undefined;
	if (typeof message !== "string" || !message.trim() || message.length > 1000) return undefined;
	return { type: "steer-ack", protocolVersion: 1, requestId: input.requestId, index, ts, state, ...(input.deliveryStatus ? { deliveryStatus: input.deliveryStatus } : {}), message: message.trim() };
}

export function readSteerCapability(asyncDir: string, index: number): SteerCapability | undefined {
	try {
		return parseSteerCapability(JSON.parse(fs.readFileSync(steerCapabilityPath(asyncDir, index), "utf-8")));
	} catch {
		return undefined;
	}
}

export function consumeSteerCapabilities(asyncDir: string, fsImpl: Pick<typeof fs, "existsSync" | "readdirSync" | "readFileSync"> = fs): SteerCapability[] {
	const dir = steerCapabilitiesDir(asyncDir);
	if (!fsImpl.existsSync(dir)) return [];
	const capabilities: SteerCapability[] = [];
	for (const entry of fsImpl.readdirSync(dir).filter((name) => /^\d+\.json$/.test(name)).sort()) {
		try {
			const capability = parseSteerCapability(JSON.parse(fsImpl.readFileSync(path.join(dir, entry), "utf-8")));
			if (capability) capabilities.push(capability);
		} catch {
			// A partially written or malformed capability is ignored until a valid one arrives.
		}
	}
	return capabilities;
}

export function consumeSteerAckFromDir(
	dir: string,
	requestId: string,
	fsImpl: Pick<typeof fs, "existsSync" | "readdirSync" | "readFileSync" | "rmSync"> = fs,
): SteerAck | undefined {
	if (!fsImpl.existsSync(dir)) return undefined;
	let entries: string[];
	try { entries = fsImpl.readdirSync(dir).filter((name) => name.endsWith(".json")).sort(); } catch { return undefined; }
	for (const entry of entries) {
		const target = path.join(dir, entry);
		let ack: SteerAck | undefined;
		try { ack = parseSteerAck(JSON.parse(fsImpl.readFileSync(target, "utf-8"))); } catch { ack = undefined; }
		if (ack?.requestId !== requestId) continue;
		try { fsImpl.rmSync(target, { force: true }); } catch { return undefined; }
		return ack;
	}
	return undefined;
}

export function consumeSteerAcks(asyncDir: string, fsImpl: Pick<typeof fs, "existsSync" | "readdirSync" | "readFileSync" | "rmSync"> = fs): SteerAck[] {
	const root = path.join(controlInboxDir(asyncDir), STEER_ACKS_DIR);
	if (!fsImpl.existsSync(root)) return [];
	const acks: SteerAck[] = [];
	let indexNames: string[];
	try { indexNames = fsImpl.readdirSync(root).filter((name) => /^\d+$/.test(name)); } catch { return []; }
	for (const indexName of indexNames) {
		const dir = path.join(root, indexName);
		let entries: string[];
		try { entries = fsImpl.readdirSync(dir).filter((name) => name.endsWith(".json")).sort(); } catch { continue; }
		for (const entry of entries) {
			const target = path.join(dir, entry);
			let ack: SteerAck | undefined;
			try { ack = parseSteerAck(JSON.parse(fsImpl.readFileSync(target, "utf-8"))); } catch { ack = undefined; }
			try { fsImpl.rmSync(target, { force: true }); } catch { continue; }
			if (ack) acks.push(ack);
		}
	}
	return acks;
}

function parseSteerRequest(raw: unknown): SteerRequest | undefined {
	if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
	const input = raw as Partial<SteerRequest>;
	if (!validSteerRequest(input)) return undefined;
	return {
		type: "steer",
		id: input.id.trim(),
		ts: input.ts,
		message: input.message.trim(),
		...(input.mode ? { mode: input.mode } : {}),
		...(input.targetIndex !== undefined ? { targetIndex: input.targetIndex } : {}),
		...(input.targetIndexes !== undefined ? { targetIndexes: [...input.targetIndexes] } : {}),
		...(typeof input.source === "string" && input.source.trim() ? { source: input.source } : {}),
	};
}

export function consumeSteerRequestsFromDir(dir: string, fsImpl: Pick<typeof fs, "existsSync" | "rmSync" | "readdirSync" | "readFileSync"> = fs): SteerRequest[] {
	if (!fsImpl.existsSync(dir)) return [];
	let entries: string[];
	try {
		entries = fsImpl.readdirSync(dir).filter((name) => name.endsWith(".json")).sort();
	} catch {
		// Leave requests in place so the periodic poll can retry the scan.
		return [];
	}
	const requests: SteerRequest[] = [];
	for (const entry of entries) {
		const requestPath = path.join(dir, entry);
		let parsed: SteerRequest | undefined;
		try {
			parsed = parseSteerRequest(JSON.parse(fsImpl.readFileSync(requestPath, "utf-8")));
		} catch {
			parsed = undefined;
		}
		try {
			fsImpl.rmSync(requestPath, { recursive: true });
		} catch {
			// Already removed by a concurrent check — do not execute it twice.
			continue;
		}
		if (parsed) requests.push(parsed);
	}
	return requests.sort((left, right) => left.ts - right.ts || left.id.localeCompare(right.id));
}

export function consumeSteerRequests(asyncDir: string, fsImpl: Pick<typeof fs, "existsSync" | "rmSync" | "readdirSync" | "readFileSync"> = fs): SteerRequest[] {
	return consumeSteerRequestsFromDir(steerRequestsDir(asyncDir), fsImpl);
}

export function queueRevivalBrief(asyncDir: string, request: SteerRequest): string {
	const dir = path.join(controlInboxDir(asyncDir), REVIVAL_BRIEFS_DIR);
	const queued = fs.existsSync(dir) ? fs.readdirSync(dir).filter((entry) => entry.endsWith(".json")).length : 0;
	if (queued >= MAX_STEER_QUEUE_SIZE) throw new Error(`Follow-up queue is full (${MAX_STEER_QUEUE_SIZE} messages).`);
	return writeSteerRequestToDir(dir, { ...request, mode: "follow_up" });
}

export function readRevivalBriefs(asyncDir: string): Array<{ request: SteerRequest; path: string }> {
	const dir = path.join(controlInboxDir(asyncDir), REVIVAL_BRIEFS_DIR);
	if (!fs.existsSync(dir)) return [];
	return fs.readdirSync(dir).filter((entry) => entry.endsWith(".json")).sort().flatMap((entry) => {
		const filePath = path.join(dir, entry);
		try {
			const request = parseSteerRequest(JSON.parse(fs.readFileSync(filePath, "utf-8")));
			return request ? [{ request, path: filePath }] : [];
		} catch {
			return [];
		}
	});
}

/**
 * Runner side: consume a pending interrupt request. Idempotent — removes the file
 * so each distinct request fires exactly once. Returns whether one was pending.
 */
export function consumeInterruptRequest(
	asyncDir: string,
	fsImpl: Pick<typeof fs, "existsSync" | "rmSync"> = fs,
): boolean {
	const requestPath = interruptRequestPath(asyncDir);
	if (!fsImpl.existsSync(requestPath)) return false;
	try {
		fsImpl.rmSync(requestPath, { force: true, recursive: true });
	} catch {
		// Already removed by a concurrent check — still counts as consumed.
	}
	return true;
}

export function consumeTimeoutRequest(
	asyncDir: string,
	fsImpl: Pick<typeof fs, "existsSync" | "rmSync"> = fs,
): boolean {
	const requestPath = timeoutRequestPath(asyncDir);
	if (!fsImpl.existsSync(requestPath)) return false;
	try {
		fsImpl.rmSync(requestPath, { force: true, recursive: true });
	} catch {
		// Already removed by a concurrent check — still counts as consumed.
	}
	return true;
}

export function consumeStopRequest(
	asyncDir: string,
	fsImpl: Pick<typeof fs, "existsSync" | "rmSync" | "readdirSync" | "readFileSync"> = fs,
): boolean {
	return consumeStopRequestPayload(asyncDir, fsImpl) !== undefined;
}

function parseStopRequest(raw: unknown): StopRequest | undefined {
	if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
	const parsed = raw as Partial<StopRequest>;
	if (parsed.type !== "stop") return undefined;
	if (Object.hasOwn(parsed, "targetIndex") && !(Number.isInteger(parsed.targetIndex) && parsed.targetIndex! >= 0 && parsed.targetIndex! <= 1_000_000)) return undefined;
	if (Object.hasOwn(parsed, "childId") && !validStopChildId(parsed.childId)) return undefined;
	return {
		type: "stop",
		...(typeof parsed.ts === "number" ? { ts: parsed.ts } : {}),
		...(typeof parsed.source === "string" ? { source: parsed.source } : {}),
		...(typeof parsed.reason === "string" ? { reason: parsed.reason } : {}),
		...(parsed.targetIndex !== undefined ? { targetIndex: parsed.targetIndex } : {}),
		...(validStopChildId(parsed.childId) ? { childId: parsed.childId } : {}),
	};
}

function consumeStopRequestFile(
	requestPath: string,
	fsImpl: Pick<typeof fs, "rmSync" | "readFileSync">,
): StopRequest | undefined {
	let request: StopRequest | undefined;
	try {
		request = parseStopRequest(JSON.parse(fsImpl.readFileSync(requestPath, "utf-8")));
	} catch {
		request = undefined;
	}
	try {
		fsImpl.rmSync(requestPath, { force: true, recursive: true });
	} catch {
		// Already removed by a concurrent check — do not execute it twice.
		return undefined;
	}
	return request;
}

export function consumeStopRequestPayloads(
	asyncDir: string,
	fsImpl: Pick<typeof fs, "existsSync" | "rmSync" | "readdirSync" | "readFileSync"> = fs,
): StopRequest[] {
	const dir = stopRequestsDir(asyncDir);
	const requests: StopRequest[] = [];
	if (fsImpl.existsSync(dir)) {
		let entries: string[];
		try {
			entries = fsImpl.readdirSync(dir).filter((name) => name.endsWith(".json")).sort();
		} catch {
			entries = [];
		}
		for (const entry of entries) {
			const request = consumeStopRequestFile(path.join(dir, entry), fsImpl);
			if (request) requests.push(request);
		}
	}

	const legacyPath = stopRequestPath(asyncDir);
	if (fsImpl.existsSync(legacyPath)) {
		const request = consumeStopRequestFile(legacyPath, fsImpl);
		if (request) requests.push(request);
	}
	return requests.sort((left, right) => (left.ts ?? 0) - (right.ts ?? 0));
}

export function consumeStopRequestPayload(
	asyncDir: string,
	fsImpl: Pick<typeof fs, "existsSync" | "rmSync" | "readdirSync" | "readFileSync"> = fs,
): StopRequest | undefined {
	return consumeStopRequestPayloads(asyncDir, fsImpl)[0];
}

/** Parent side: write the authoritative portable interrupt request. */
export function deliverInterruptRequest(input: {
	asyncDir: string;
	now?: () => number;
	source?: string;
}): void {
	requestAsyncInterrupt(input.asyncDir, input.source ? { source: input.source } : {}, { now: input.now });
}

export function deliverTimeoutRequest(input: {
	asyncDir: string;
	pid?: number;
	kill?: KillFn;
	signal?: NodeJS.Signals;
	now?: () => number;
	source?: string;
}): void {
	requestAsyncTimeout(input.asyncDir, input.source ? { source: input.source } : {}, { now: input.now });
}

export function deliverStopRequest(input: {
	asyncDir: string;
	pid?: number;
	kill?: KillFn;
	signal?: NodeJS.Signals;
	now?: () => number;
	source?: string;
	targetIndex?: number;
	childId?: string;
}): void {
	requestAsyncStop(input.asyncDir, { ...(input.source ? { source: input.source } : {}), ...(input.targetIndex !== undefined ? { targetIndex: input.targetIndex } : {}), ...(input.childId ? { childId: input.childId } : {}) }, { now: input.now });
}

/**
 * Runner side: watch the control inbox and route interrupt requests into
 * `onInterrupt`. Uses `fs.watch` when available and starts interval polling
 * only when native watching is unavailable or fails. Fires once per distinct
 * request. Returns a disposer.
 */
export function watchAsyncControlInbox(
	asyncDir: string,
	opts: {
		onInterrupt: () => void;
		onTimeout?: () => void;
		onStop?: (request: StopRequest) => void;
		onSteer?: (request: SteerRequest) => void;
		onSteerCapability?: (capability: SteerCapability) => void;
		onSteerAck?: (ack: SteerAck) => void;
		pollIntervalMs?: number;
		safetyPollIntervalMs?: number;
		platform?: NodeJS.Platform;
		fs?: ControlChannelFs;
		timers?: ControlChannelTimers;
	},
): () => void {
	const fsImpl = opts.fs ?? fs;
	const timers = opts.timers ?? { setInterval, clearInterval };
	const dir = controlInboxDir(asyncDir);
	try {
		fsImpl.mkdirSync(dir, { recursive: true });
	} catch {
		// Best effort — the poll/watch below tolerates a missing dir.
	}

	let disposed = false;
	const check = (): void => {
		if (disposed) return;
		try {
			for (const stopRequest of consumeStopRequestPayloads(asyncDir, fsImpl)) opts.onStop?.(stopRequest);
			if (consumeTimeoutRequest(asyncDir, fsImpl)) opts.onTimeout?.();
			if (consumeInterruptRequest(asyncDir, fsImpl)) opts.onInterrupt();
			for (const request of consumeSteerRequests(asyncDir, fsImpl)) opts.onSteer?.(request);
			for (const capability of consumeSteerCapabilities(asyncDir, fsImpl)) opts.onSteerCapability?.(capability);
			for (const ack of consumeSteerAcks(asyncDir, fsImpl)) opts.onSteerAck?.(ack);
		} catch {
			// Never let inbox errors crash the runner.
		}
	};

	// Handle a request that may have arrived before the watcher started.
	check();

	const watchers: fs.FSWatcher[] = [];
	const watchedDirs = new Set<string>();
	let interval: ReturnType<typeof setInterval> | undefined;
	let safetyInterval: ReturnType<typeof setInterval> | undefined;
	const startPolling = (): void => {
		if (interval || disposed) return;
		interval = timers.setInterval(check, opts.pollIntervalMs ?? POLL_INTERVAL_MS);
		interval.unref?.();
	};
	const startSafetyPolling = (): void => {
		if (safetyInterval || disposed) return;
		safetyInterval = timers.setInterval(check, opts.safetyPollIntervalMs ?? CONTROL_SAFETY_POLL_INTERVAL_MS);
		safetyInterval.unref?.();
	};
	const watchDir = (target: string, create = false): void => {
		if (disposed || watchedDirs.has(target)) return;
		if (create) fsImpl.mkdirSync(target, { recursive: true });
		const watcher = fsImpl.watch(resolveWatchPath(target, fsImpl.realpathSync.native), () => {
			watchExistingSteerAckDirs();
			check();
		});
		watcher.on?.("error", startPolling);
		watchers.push(watcher);
		watchedDirs.add(target);
	};
	const watchExistingSteerAckDirs = (): void => {
		const ackRoot = path.join(dir, STEER_ACKS_DIR);
		let entries: string[];
		try {
			entries = fsImpl.readdirSync(ackRoot).filter((name) => /^\d+$/.test(name));
		} catch {
			return;
		}
		for (const entry of entries) watchDir(path.join(ackRoot, entry));
	};
	try {
		if (shouldUseNativeFsWatch("runner-control-inbox", opts.platform)) {
			watchDir(dir);
			watchDir(stopRequestsDir(asyncDir), true);
			watchDir(steerRequestsDir(asyncDir), true);
			watchDir(steerCapabilitiesDir(asyncDir), true);
			watchDir(path.join(dir, STEER_ACKS_DIR), true);
			watchExistingSteerAckDirs();
			startSafetyPolling();
		} else {
			startPolling();
		}
	} catch {
		startPolling();
	}

	return () => {
		if (disposed) return;
		disposed = true;
		for (const watcher of watchers) {
			try {
				watcher.close();
			} catch {
				// ignore
			}
		}
		if (interval) timers.clearInterval(interval);
		if (safetyInterval) timers.clearInterval(safetyInterval);
	};
}

import * as fs from "node:fs";
import * as path from "node:path";
import type { AgentToolResult } from "@earendil-works/pi-agent-core";
import { safeTerminalText } from "../../shared/display-text.ts";
import { formatDuration, formatModelThinking, formatTokens, shortenPath } from "../../shared/formatters.ts";
import { formatActivityLabel } from "../../shared/status-format.ts";
import {
	DIRS,
	type ActivityState,
	type AsyncJobStep,
	type AsyncStatus,
	type Details,
	type NestedRunSummary,
	type SubagentRunMode,
	type SubagentState,
} from "../../shared/types.ts";
import { readStatus } from "../../shared/utils.ts";
import { formatNestedRunStatusLines } from "../shared/nested-render.ts";
import { contextModeLabel, summarizeContextModes } from "../shared/context-mode.ts";
import { formatAsyncRunOutputPath, formatAsyncRunProgressLabel, listAsyncRuns, type AsyncRunSummary } from "./async-status.ts";

const DEFAULT_TRANSCRIPT_LINES = 80;
const MAX_TRANSCRIPT_LINES = 500;
const TRANSCRIPT_TAIL_BYTES = 256 * 1024;

type ForegroundControl = SubagentState["foregroundControls"] extends Map<string, infer T> ? T : never;
type ForegroundRun = NonNullable<SubagentState["foregroundRuns"]> extends Map<string, infer T> ? T : never;

interface FleetViewParams {
	lines?: number;
}

interface FleetViewDeps {
	asyncDirRoot?: string;
	resultsDir?: string;
	kill?: (pid: number, signal?: NodeJS.Signals | 0) => boolean;
	now?: () => number;
	state?: SubagentState;
	childSafe?: boolean;
}

interface TranscriptOptions {
	index?: number;
	lines?: number;
	sessionRoots?: string[];
}

interface TextTailResult {
	path: string;
	lines: string[];
	truncated: boolean;
	error?: string;
}

function transcriptLineLimit(value: number | undefined): number {
	if (value === undefined) return DEFAULT_TRANSCRIPT_LINES;
	if (!Number.isFinite(value)) return DEFAULT_TRANSCRIPT_LINES;
	return Math.max(1, Math.min(MAX_TRANSCRIPT_LINES, Math.trunc(value)));
}

function uniqueStrings(values: Array<string | undefined>): string[] {
	const seen = new Set<string>();
	const result: string[] = [];
	for (const value of values) {
		if (!value || seen.has(value)) continue;
		seen.add(value);
		result.push(value);
	}
	return result;
}

function resolveMaybeRelative(asyncDir: string, filePath: string | undefined): string | undefined {
	if (!filePath) return undefined;
	return path.resolve(asyncDir, filePath);
}

function pathWithin(base: string, candidate: string): boolean {
	const resolvedBase = path.resolve(base);
	const resolvedCandidate = path.resolve(candidate);
	return resolvedCandidate === resolvedBase || resolvedCandidate.startsWith(`${resolvedBase}${path.sep}`);
}

function getErrorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function isNotFoundError(error: unknown): boolean {
	return typeof error === "object"
		&& error !== null
		&& "code" in error
		&& (error as NodeJS.ErrnoException).code === "ENOENT";
}

function readTextTail(filePath: string, maxLines: number): TextTailResult {
	let stat: fs.Stats;
	try {
		stat = fs.statSync(filePath);
	} catch (error) {
		if (isNotFoundError(error)) return { path: filePath, lines: [], truncated: false };
		return { path: filePath, lines: [], truncated: false, error: getErrorMessage(error) };
	}
	if (stat.size === 0) return { path: filePath, lines: [], truncated: false };

	let fd: number | undefined;
	try {
		const bytesToRead = Math.min(stat.size, TRANSCRIPT_TAIL_BYTES);
		const start = stat.size - bytesToRead;
		const buffer = Buffer.alloc(bytesToRead);
		fd = fs.openSync(filePath, "r");
		const bytesRead = fs.readSync(fd, buffer, 0, bytesToRead, start);
		const content = buffer.subarray(0, bytesRead).toString("utf-8");
		let lines = content.split(/\r?\n/);
		if (start > 0 && lines.length > 0) lines = lines.slice(1);
		if (lines.at(-1) === "") lines = lines.slice(0, -1);
		return { path: filePath, lines: lines.slice(-maxLines), truncated: start > 0 || lines.length > maxLines };
	} catch (error) {
		return { path: filePath, lines: [], truncated: false, error: getErrorMessage(error) };
	} finally {
		if (fd !== undefined) fs.closeSync(fd);
	}
}

function readContainedTextTail(filePath: string, maxLines: number, trustedRoots: string[], label: string): TextTailResult {
	if (trustedRoots.length === 0) return { path: filePath, lines: [], truncated: false, error: `Refusing to read ${label} transcript path without a trusted root: ${filePath}` };
	const resolvedPath = path.resolve(filePath);
	if (!trustedRoots.some((root) => pathWithin(root, resolvedPath))) {
		return { path: filePath, lines: [], truncated: false, error: `Refusing to read ${label} transcript path outside trusted roots: ${filePath}` };
	}
	let lstat: fs.Stats;
	try {
		lstat = fs.lstatSync(resolvedPath);
	} catch (error) {
		if (isNotFoundError(error)) return { path: filePath, lines: [], truncated: false };
		return { path: filePath, lines: [], truncated: false, error: getErrorMessage(error) };
	}
	if (lstat.isSymbolicLink()) return { path: filePath, lines: [], truncated: false, error: `Refusing to read symlink ${label} transcript path: ${filePath}` };
	if (!lstat.isFile()) return { path: filePath, lines: [], truncated: false, error: `Refusing to read non-file ${label} transcript path: ${filePath}` };
	let realPath: string;
	let realRoots: string[];
	try {
		realPath = fs.realpathSync(resolvedPath);
		realRoots = trustedRoots.filter((root) => fs.existsSync(root)).map((root) => fs.realpathSync(root));
	} catch (error) {
		return { path: filePath, lines: [], truncated: false, error: getErrorMessage(error) };
	}
	if (!realRoots.some((root) => pathWithin(root, realPath))) {
		return { path: filePath, lines: [], truncated: false, error: `Refusing to read ${label} transcript path outside trusted roots: ${filePath}` };
	}
	return readTextTail(resolvedPath, maxLines);
}

function stringifyJsonPreview(value: unknown, maxLength = 240): string {
	let raw: string;
	if (typeof value === "string") raw = value;
	else raw = JSON.stringify(value);
	return raw.length > maxLength ? `${raw.slice(0, maxLength)}…` : raw;
}

/** One structured content part of a session JSONL record. Shared by the prose transcript formatter and inspect RPC. */
export interface SessionTranscriptMessage {
	role: string;
	kind: "text" | "toolCall" | "toolResult";
	text: string;
	name?: string;
	isError?: boolean;
	/** Ordinal of the session record this part came from, so consumers can
	 *  regroup multi-part messages (one session record can yield several parts). */
	recordIndex?: number;
}

function sessionMessageParts(record: unknown): SessionTranscriptMessage[] {
	if (!record || typeof record !== "object") return [];
	const outer = record as { message?: unknown; role?: unknown; content?: unknown; type?: unknown };
	const message = outer.message && typeof outer.message === "object" ? outer.message as { role?: unknown; content?: unknown } : outer;
	const role = typeof message.role === "string" ? message.role : undefined;
	if (!role) return [];
	const content = message.content;
	if (typeof content === "string") return content.trim() ? [{ role, kind: "text", text: content }] : [];
	if (!Array.isArray(content)) return [];
	const parts: SessionTranscriptMessage[] = [];
	for (const part of content) {
		if (!part || typeof part !== "object") continue;
		const entry = part as { type?: unknown; text?: unknown; name?: unknown; toolName?: unknown; args?: unknown; result?: unknown; content?: unknown; isError?: unknown };
		if (typeof entry.text === "string") {
			if (entry.text.trim()) parts.push({ role, kind: "text", text: entry.text });
			continue;
		}
		if (entry.type === "toolCall" || entry.type === "tool_call") {
			const name = typeof entry.name === "string" ? entry.name : typeof entry.toolName === "string" ? entry.toolName : "tool";
			parts.push({ role, kind: "toolCall", name, text: `[tool: ${name}${entry.args === undefined ? "" : ` ${stringifyJsonPreview(entry.args)}`}]` });
			continue;
		}
		if (entry.type === "toolResult" || entry.type === "tool_result") {
			const name = typeof entry.name === "string" ? entry.name : typeof entry.toolName === "string" ? entry.toolName : undefined;
			parts.push({ role, kind: "toolResult", ...(name ? { name } : {}), ...(entry.isError === true ? { isError: true } : {}), text: `[tool result${entry.result === undefined ? "" : `: ${stringifyJsonPreview(entry.result)}`}]` });
			continue;
		}
		if (entry.content !== undefined) {
			const preview = stringifyJsonPreview(entry.content);
			if (preview.trim()) parts.push({ role, kind: "text", text: preview });
		}
	}
	return parts;
}

function sessionMessageLine(record: unknown): string | undefined {
	const parts = sessionMessageParts(record);
	if (parts.length === 0) return undefined;
	const text = parts.map((part) => part.text).join("\n").trim();
	if (!text) return undefined;
	return `${parts[0]!.role}: ${text}`;
}

/** Structured session tail: parsed content parts, newest last, bounded by
 *  maxMessages. Same trusted-root containment as the prose transcript tail. */
export function readSessionMessagesTail(sessionFile: string, maxMessages: number, trustedRoots: string[]): { messages: SessionTranscriptMessage[]; warnings: string[]; truncated: boolean } {
	const tail = readContainedTextTail(sessionFile, Math.max(maxMessages * 4, maxMessages), trustedRoots, "session");
	const warnings: string[] = [];
	if (tail.error) warnings.push(`Session read failed for ${sessionFile}: ${tail.error}`);
	const parsedMessages: SessionTranscriptMessage[] = [];
	let malformed = 0;
	let recordIndex = 0;
	for (const line of tail.lines) {
		if (!line.trim()) continue;
		try {
			const parsed = JSON.parse(line) as unknown;
			for (const part of sessionMessageParts(parsed)) parsedMessages.push({ ...part, recordIndex });
		} catch {
			malformed++;
		}
		recordIndex++;
	}
	if (malformed > 0) warnings.push(`Skipped ${malformed} malformed session tail line${malformed === 1 ? "" : "s"}.`);
	const messages = parsedMessages.slice(-maxMessages);
	return { messages, warnings, truncated: tail.truncated || parsedMessages.length > messages.length };
}

function readSessionTranscriptTail(sessionFile: string, maxLines: number, trustedRoots: string[]): { lines: string[]; warnings: string[] } {
	const tail = readContainedTextTail(sessionFile, Math.max(maxLines * 4, maxLines), trustedRoots, "session");
	const warnings: string[] = [];
	if (tail.error) warnings.push(`Session read failed for ${sessionFile}: ${tail.error}`);
	const lines: string[] = [];
	let malformed = 0;
	for (const line of tail.lines) {
		if (!line.trim()) continue;
		try {
			const parsed = JSON.parse(line) as unknown;
			const messageLine = sessionMessageLine(parsed);
			if (messageLine) lines.push(...messageLine.split(/\r?\n/));
		} catch {
			malformed++;
		}
	}
	if (malformed > 0) warnings.push(`Skipped ${malformed} malformed session tail line${malformed === 1 ? "" : "s"}.`);
	return { lines: lines.slice(-maxLines), warnings };
}

function formatActivityFacts(input: {
	activityState?: ActivityState;
	lastActivityAt?: number;
	currentTool?: string;
	currentToolStartedAt?: number;
	currentPath?: string;
	turnCount?: number;
	toolCount?: number;
	tokens?: { total: number };
}): string | undefined {
	const facts: string[] = [];
	if (input.currentTool && input.currentToolStartedAt !== undefined) facts.push(`tool ${input.currentTool} ${formatDuration(Math.max(0, Date.now() - input.currentToolStartedAt))}`);
	else if (input.currentTool) facts.push(`tool ${input.currentTool}`);
	if (input.currentPath) facts.push(shortenPath(input.currentPath));
	if (input.turnCount !== undefined) facts.push(`${input.turnCount} turns`);
	if (input.toolCount !== undefined) facts.push(`${input.toolCount} tools`);
	if (input.tokens?.total) facts.push(`${formatTokens(input.tokens.total)} tok`);
	const activity = formatActivityLabel(input.lastActivityAt, input.activityState);
	return activity || facts.length ? [activity, ...facts].filter(Boolean).join(" | ") : undefined;
}

function foregroundModeName(control: ForegroundControl): string {
	if (control.mode === "single" && control.currentAgent) return control.currentAgent;
	return control.mode;
}

function formatForegroundFleetLines(controls: ForegroundControl[]): string[] {
	if (controls.length === 0) return [];
	const lines = ["Foreground runs:"];
	const ordered = [...controls].sort((left, right) => right.updatedAt - left.updatedAt);
	for (const control of ordered) {
		const activity = formatActivityFacts({
			activityState: control.currentActivityState,
			lastActivityAt: control.lastActivityAt,
			currentTool: control.currentTool,
			currentToolStartedAt: control.currentToolStartedAt,
			currentPath: control.currentPath,
			turnCount: control.turnCount,
			toolCount: control.toolCount,
			...(control.tokens !== undefined ? { tokens: { total: control.tokens } } : {}),
		});
		const current = control.currentAgent ? ` | ${control.currentAgent}${control.currentIndex !== undefined ? ` #${control.currentIndex}` : ""}` : "";
		lines.push(`- ${control.runId} | running | ${foregroundModeName(control)}${current}${activity ? ` | ${activity}` : ""}`);
		lines.push(`  status: subagent({ action: "status", id: "${control.runId}" })`);
		lines.push("  transcript: live in the expanded foreground result; persisted session transcript appears after completion when sessions are enabled.");
		lines.push(...formatNestedRunStatusLines(control.nestedChildren, { indent: "  ", commandHints: true, maxLines: 12 }));
	}
	return lines;
}

function formatDetachedForegroundFleetLines(runs: ForegroundRun[]): string[] {
	if (runs.length === 0) return [];
	const lines = ["Detached foreground runs:"];
	const ordered = [...runs].sort((left, right) => right.updatedAt - left.updatedAt);
	for (const run of ordered) {
		const detachedChildren = run.children.filter((child) => child.status === "detached");
		const childSummary = detachedChildren.map((child) => `${child.agent} #${child.index}`).join(", ");
		lines.push(`- ${run.runId} | detached | ${run.mode}${childSummary ? ` | ${childSummary}` : ""}`);
		lines.push(`  status: subagent({ action: "status", id: "${run.runId}" })`);
		lines.push(`  recovery: reply to the supervisor request first, then wait with subagent_wait({ id: "${run.runId}" }); do not resume or launch a replacement while any child remains detached.`);
	}
	return lines;
}

function formatAsyncFleetLines(runs: AsyncRunSummary[]): string[] {
	if (runs.length === 0) return [];
	const lines = ["Async runs:"];
	for (const run of runs) {
		const progress = formatAsyncRunProgressLabel(run);
		const activity = formatActivityFacts(run);
		const cwd = run.cwd ? shortenPath(run.cwd) : shortenPath(run.asyncDir);
		const pending = run.pendingAppends ? ` | ${run.pendingAppends} pending append${run.pendingAppends === 1 ? "" : "s"}` : "";
		const runContext = contextModeLabel(run.context);
		lines.push(`- ${run.id} | ${run.state}${activity ? ` | ${activity}` : ""} | ${run.mode}${runContext ? ` ${runContext}` : ""} | ${progress}${pending} | ${cwd}`);
		lines.push(`  status: subagent({ action: "status", id: "${run.id}" })`);
		lines.push(`  transcript: subagent({ action: "status", id: "${run.id}", view: "transcript" })`);
		for (const step of run.steps) {
			const display = step.label ? `${step.label} (${step.agent})` : step.agent;
			const stepContext = contextModeLabel(step.context);
			const phase = step.phase ? `[${step.phase}] ` : "";
			const stepActivity = formatActivityFacts(step);
			const modelThinking = formatModelThinking(step.model, step.thinking);
			const parts = [`${step.index}. ${phase}${display}${stepContext ? ` ${stepContext}` : ""}`, step.status, stepActivity, modelThinking].filter(Boolean);
			lines.push(`  ${parts.join(" | ")}`);
			const output = path.join(run.asyncDir, `output-${step.index}.log`);
			if (fs.existsSync(output)) lines.push(`    output: ${shortenPath(output)}`);
			if (step.sessionFile) lines.push(`    session: ${shortenPath(step.sessionFile)}`);
			if (step.status === "running" || step.recentOutput?.length || fs.existsSync(output)) {
				lines.push(`    transcript: subagent({ action: "status", id: "${run.id}", index: ${step.index}, view: "transcript" })`);
			}
			lines.push(...formatNestedRunStatusLines(step.children, { indent: "    ", commandHints: true, maxLines: 12 }));
		}
		const attached = new Set(run.steps.flatMap((step) => step.children?.map((child) => child.id) ?? []));
		const unattached = run.nestedChildren?.filter((child) => !attached.has(child.id)) ?? [];
		lines.push(...formatNestedRunStatusLines(unattached, { indent: "  ", commandHints: true, maxLines: 12 }));
		if (run.error) lines.push(`  error: ${run.error}`);
		for (const warning of run.nestedWarnings ?? []) lines.push(`  warning: ${warning}`);
		const outputPath = formatAsyncRunOutputPath(run);
		if (outputPath) lines.push(`  output: ${shortenPath(outputPath)}`);
		if (run.sessionFile) lines.push(`  session: ${shortenPath(run.sessionFile)}`);
	}
	return lines;
}

export function inspectSubagentFleet(_params: FleetViewParams, deps: FleetViewDeps = {}): AgentToolResult<Details> {
	if (deps.childSafe) {
		return {
			content: [{ type: "text", text: "Child-safe subagent fleet view is unavailable without an explicit run id. Use subagent({ action: \"status\", id: \"...\" }) for the delegated run you can see." }],
			isError: true,
			details: { mode: "management", results: [] },
		};
	}

	let asyncRuns: AsyncRunSummary[];
	try {
		asyncRuns = listAsyncRuns(deps.asyncDirRoot ?? DIRS.async, {
			states: ["queued", "running"],
			sessionId: deps.state?.currentSessionId ?? undefined,
			resultsDir: deps.resultsDir ?? DIRS.results,
			kill: deps.kill,
			now: deps.now,
		});
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		return { content: [{ type: "text", text: message }], isError: true, details: { mode: "management", results: [] } };
	}

	const foregroundControls = deps.state ? [...deps.state.foregroundControls.values()] : [];
	const activeForegroundIds = new Set(foregroundControls.map((control) => control.runId));
	const detachedForegroundRuns = deps.state?.foregroundRuns
		? [...deps.state.foregroundRuns.values()].filter((run) => run.sessionId === deps.state?.currentSessionId && !activeForegroundIds.has(run.runId) && run.children.some((child) => child.status === "detached"))
		: [];
	const total = foregroundControls.length + detachedForegroundRuns.length + asyncRuns.length;
	if (total === 0) {
		return {
			content: [{ type: "text", text: "No active subagent fleet. Background runs that already finished are available through completion notifications or subagent({ action: \"status\", id: \"...\" })." }],
			details: { mode: "management", results: [] },
		};
	}

	const lines = [`Subagent fleet: ${total} tracked`, ""];
	const foregroundLines = formatForegroundFleetLines(foregroundControls);
	if (foregroundLines.length) lines.push(...foregroundLines, "");
	const detachedForegroundLines = formatDetachedForegroundFleetLines(detachedForegroundRuns);
	if (detachedForegroundLines.length) lines.push(...detachedForegroundLines, "");
	const asyncLines = formatAsyncFleetLines(asyncRuns);
	if (asyncLines.length) lines.push(...asyncLines, "");
	lines.push("Commands:");
	lines.push("  Refresh fleet: subagent({ action: \"status\", view: \"fleet\" })");
	lines.push("  Tail run transcript: subagent({ action: \"status\", id: \"<run-id>\", view: \"transcript\" })");
	lines.push("  Tail child transcript: subagent({ action: \"status\", id: \"<run-id>\", index: 0, view: \"transcript\" })");

	return { content: [{ type: "text", text: lines.join("\n").trimEnd() }], details: { mode: "management", results: [] } };
}

function validateTranscriptIndex(index: number | undefined, steps: AsyncJobStep[]): number | undefined {
	if (index === undefined) return undefined;
	if (!Number.isInteger(index)) throw new Error("Transcript index must be an integer.");
	if (index < 0 || index >= steps.length) throw new Error(`Transcript index ${index} is out of range for ${steps.length} child step${steps.length === 1 ? "" : "s"}.`);
	return index;
}

function selectTranscriptStep(status: AsyncStatus, options: TranscriptOptions): { index?: number; step?: AsyncJobStep; hint?: string } {
	const steps = status.steps ?? [];
	let selectedIndex = validateTranscriptIndex(options.index, steps);
	if (selectedIndex === undefined) {
		if (status.state === "running" && typeof status.currentStep === "number" && status.currentStep >= 0 && status.currentStep < steps.length) {
			selectedIndex = status.currentStep;
		} else if (steps.length === 1) {
			selectedIndex = 0;
		}
	}
	const step = selectedIndex !== undefined ? steps[selectedIndex] : undefined;
	const hint = options.index === undefined && steps.length > 1
		? `Tip: pass index to inspect a specific child transcript (${steps.map((candidate, index) => `${index}=${candidate.agent}`).join(", ")}).`
		: undefined;
	return { index: selectedIndex, step, hint };
}

function stepStateLine(mode: SubagentRunMode, index: number | undefined, step: AsyncJobStep | undefined): string | undefined {
	if (index === undefined || !step) return undefined;
	const modelThinking = formatModelThinking(step.model, step.thinking);
	const context = contextModeLabel(step.context);
	const parts = [
		`${mode === "parallel" ? "Agent" : "Step"}: ${index} (${step.agent})${context ? ` ${context}` : ""}`,
		step.status,
		formatActivityFacts(step),
		modelThinking,
		step.error ? `error: ${step.error}` : undefined,
	].filter(Boolean);
	return parts.join(" | ");
}

function appendKnownArtifacts(lines: string[], input: { outputPaths: string[]; sessionFile?: string; eventsPath?: string; logPath?: string; resultPath?: string }): void {
	const artifacts: string[] = [];
	for (const outputPath of input.outputPaths) artifacts.push(`Output: ${outputPath}`);
	if (input.sessionFile) artifacts.push(`Session: ${input.sessionFile}`);
	if (input.eventsPath) artifacts.push(`Events: ${input.eventsPath}`);
	if (input.logPath) artifacts.push(`Log: ${input.logPath}`);
	if (input.resultPath) artifacts.push(`Result: ${input.resultPath}`);
	if (!artifacts.length) return;
	lines.push("Artifacts:");
	for (const artifact of artifacts) lines.push(`  ${artifact}`);
}

/**
 * Sanitizes each assembled line independently.
 *
 * Sanitizing the joined response would let a single binary fragment in child
 * output collapse the whole transcript, including run state, artifact paths, and
 * warnings, into the binary placeholder. Per-line sanitization keeps that damage
 * to the offending line.
 */
function safeTranscriptLines(lines: string[]): string {
	return lines.map((line) => safeTerminalText(line)).join("\n");
}

function appendTranscriptBody(lines: string[], sourceLabel: string, sourceLines: string[], truncated: boolean): void {
	lines.push(`${sourceLabel}${truncated ? " (tail truncated)" : ""}:`);
	if (sourceLines.length === 0) {
		lines.push("  (no transcript lines available yet)");
		return;
	}
	for (const line of sourceLines) lines.push(`  ${line}`);
}

export function formatAsyncRunTranscript(status: AsyncStatus, asyncDir: string, options: TranscriptOptions = {}): string {
	const lineLimit = transcriptLineLimit(options.lines);
	const selected = selectTranscriptStep(status, options);
	const stepOutputPath = selected.index !== undefined ? path.join(asyncDir, `output-${selected.index}.log`) : undefined;
	const runOutputPath = resolveMaybeRelative(asyncDir, status.outputFile);
	const logPath = path.join(asyncDir, `subagent-log-${status.runId}.md`);
	const outputPaths = selected.index !== undefined
		? uniqueStrings([stepOutputPath, runOutputPath && stepOutputPath && path.resolve(runOutputPath) === path.resolve(stepOutputPath) ? runOutputPath : undefined])
		: uniqueStrings([runOutputPath]);
	const sessionFile = selected.index !== undefined ? selected.step?.sessionFile : status.sessionFile;
	const eventsPath = path.join(asyncDir, "events.jsonl");
	// Synthesized output paths can name files that were never written. Keep the unfiltered paths
	// below so a present-but-unreadable file still reports its read error.

	const context = contextModeLabel(status.context ?? summarizeContextModes((status.steps ?? []).map((step) => step.context)));
	const lines = [
		`Run: ${status.runId}`,
		`State: ${status.state}`,
		`Mode: ${status.mode}${context ? ` ${context}` : ""}`,
		stepStateLine(status.mode, selected.index, selected.step),
		selected.hint,
	].filter((line): line is string => Boolean(line));
	appendKnownArtifacts(lines, { outputPaths: outputPaths.filter((outputPath) => fs.existsSync(outputPath)), sessionFile, eventsPath: fs.existsSync(eventsPath) ? eventsPath : undefined, logPath: fs.existsSync(logPath) ? logPath : undefined });

	const warnings: string[] = [];
	let transcriptLines: string[] = [];
	let transcriptSource = "Transcript tail";
	let truncated = false;
	for (const outputPath of outputPaths) {
		const tail = readContainedTextTail(outputPath, lineLimit, [asyncDir], "output");
		if (tail.error) warnings.push(`Output read failed for ${tail.path}: ${tail.error}`);
		if (tail.lines.length === 0) continue;
		transcriptLines = tail.lines;
		transcriptSource = `Transcript tail from ${tail.path}`;
		truncated = tail.truncated;
		break;
	}
	if (transcriptLines.length === 0 && selected.step?.recentOutput?.length) {
		transcriptLines = selected.step.recentOutput.slice(-lineLimit);
		transcriptSource = "Recent output from status.json";
	}
	if (transcriptLines.length === 0 && sessionFile) {
		const sessionTail = readSessionTranscriptTail(sessionFile, lineLimit, options.sessionRoots ?? []);
		transcriptLines = sessionTail.lines;
		warnings.push(...sessionTail.warnings);
		if (transcriptLines.length > 0) transcriptSource = `Session transcript tail from ${sessionFile}`;
	}

	if (warnings.length) {
		lines.push("Warnings:");
		for (const warning of warnings) lines.push(`  ${warning}`);
	}
	appendTranscriptBody(lines, transcriptSource, transcriptLines, truncated);
	return safeTranscriptLines(lines);
}

export function formatNestedRunTranscript(run: NestedRunSummary, options: TranscriptOptions = {}): string {
	if (run.asyncDir) {
		const status = readStatus(run.asyncDir);
		if (status) return formatAsyncRunTranscript(status, run.asyncDir, options);
	}
	const lineLimit = transcriptLineLimit(options.lines);
	const lines = [
		`Nested run: ${run.id}`,
		`State: ${run.state}`,
		run.mode ? `Mode: ${run.mode}` : undefined,
		run.agent ? `Agent: ${run.agent}` : run.agents?.length ? `Agents: ${run.agents.join(", ")}` : undefined,
	].filter((line): line is string => Boolean(line));
	appendKnownArtifacts(lines, { outputPaths: [], sessionFile: run.sessionFile });
	if (!run.sessionFile) {
		appendTranscriptBody(lines, "Transcript tail", [], false);
		return safeTranscriptLines(lines);
	}
	const sessionTail = readSessionTranscriptTail(run.sessionFile, lineLimit, options.sessionRoots ?? []);
	if (sessionTail.warnings.length) {
		lines.push("Warnings:");
		for (const warning of sessionTail.warnings) lines.push(`  ${warning}`);
	}
	appendTranscriptBody(lines, `Session transcript tail from ${run.sessionFile}`, sessionTail.lines, false);
	return safeTranscriptLines(lines);
}

export function formatAsyncResultTranscript(data: {
	id?: string;
	runId?: string;
	state?: string;
	success?: boolean;
	summary?: string;
	output?: string;
	sessionFile?: string;
	agent?: string;
	exitCode?: number | null;
	results?: Array<{ agent?: string; output?: string; summary?: string; sessionFile?: string; state?: string; success?: boolean; exitCode?: number | null }>;
}, resultPath: string, options: TranscriptOptions = {}): string {
	const lineLimit = transcriptLineLimit(options.lines);
	const runId = data.runId ?? data.id ?? path.basename(resultPath, ".json");
	const children = Array.isArray(data.results)
		? data.results
		: data.agent
			? [{ agent: data.agent, output: data.output, summary: data.summary, sessionFile: data.sessionFile, state: data.state, success: data.success, exitCode: data.exitCode }]
			: [];
	let index = options.index;
	if (index !== undefined && !Number.isInteger(index)) throw new Error("Transcript index must be an integer.");
	if (index === undefined && children.length === 1) index = 0;
	if (index !== undefined && (index < 0 || index >= children.length)) throw new Error(`Transcript index ${index} is out of range for ${children.length} result child${children.length === 1 ? "" : "ren"}.`);
	const child = index !== undefined ? children[index] : undefined;
	const output = index !== undefined
		? child?.output ?? child?.summary ?? (children.length === 1 ? data.output ?? data.summary : undefined) ?? ""
		: data.output ?? data.summary ?? "";
	const transcriptLines = output.split(/\r?\n/).slice(-lineLimit);
	const sessionFile = child?.sessionFile ?? data.sessionFile;
	const lines = [
		`Run: ${runId}`,
		`State: ${data.state ?? (data.success ? "complete" : "failed")}`,
		index !== undefined && child ? `Child: ${index} (${child.agent ?? "subagent"})` : undefined,
		index === undefined && children.length > 1 ? `Tip: pass index to inspect a specific child transcript (${children.map((candidate, childIndex) => `${childIndex}=${candidate.agent ?? "subagent"}`).join(", ")}).` : undefined,
	].filter((line): line is string => Boolean(line));
	appendKnownArtifacts(lines, { outputPaths: [], sessionFile, resultPath });
	appendTranscriptBody(lines, "Result transcript tail", transcriptLines.filter((line) => line.trim()), output.split(/\r?\n/).length > lineLimit);
	return safeTranscriptLines(lines);
}

import { createHash } from "node:crypto";

/**
 * Keep opaque index keys below common filesystem component limits.
 *
 * Portable short values retain the historical URI-encoded representation.
 * Oversized or non-portable values use a deterministic digest so callers can
 * resolve the same index without persisting a separate lookup table.
 *
 * Encoded backslashes and trailing file extensions are not portable. Pi session
 * ids are often the full session `.jsonl` path. On Windows, `readdir` of a
 * directory whose name ends in `.jsonl` or contains `%5C` can fail with EPERM.
 */
export const MAX_INDEX_SEGMENT_BYTES = 255;
const HASHED_INDEX_SEGMENT_PREFIX = "~sha256-";
const WINDOWS_RESERVED_NAME = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i;

function hashedSegment(value: string): string {
	return `${HASHED_INDEX_SEGMENT_PREFIX}${createHash("sha256").update(value).digest("hex")}`;
}

function isPortableSegment(value: string): boolean {
	return value.length > 0
		&& value !== "."
		&& value !== ".."
		&& !value.endsWith(".")
		&& !WINDOWS_RESERVED_NAME.test(value)
		&& !/%5C/i.test(value)
		&& !/\.[A-Za-z][A-Za-z0-9]{0,7}$/.test(value);
}

export function encodeIndexSegment(value: string, maxBytes = MAX_INDEX_SEGMENT_BYTES): string {
	let encoded: string;
	try {
		encoded = encodeURIComponent(value);
	} catch {
		return hashedSegment(value);
	}
	if (Buffer.byteLength(encoded, "utf-8") <= maxBytes && isPortableSegment(encoded)) return encoded;
	return hashedSegment(value);
}

function historicallyReadableSegment(value: string, maxBytes: number): string | undefined {
	try {
		const encoded = encodeURIComponent(value);
		if (encoded.length === 0 || encoded === "." || encoded === ".." || encoded.endsWith(".") || WINDOWS_RESERVED_NAME.test(encoded)) return undefined;
		if (Buffer.byteLength(encoded, "utf-8") > maxBytes) return undefined;
		return encoded;
	} catch {
		return undefined;
	}
}

/** Current write key first, then the pre-hash URI-encoded key when it still fits. */
export function indexSegmentAliases(value: string, maxBytes = MAX_INDEX_SEGMENT_BYTES): string[] {
	const current = encodeIndexSegment(value, maxBytes);
	const historical = historicallyReadableSegment(value, maxBytes);
	return historical && historical !== current ? [current, historical] : [current];
}

import * as fs from "node:fs";
import { sanitizeDisplayText, truncateDisplayText } from "../../shared/display-text.ts";
import { decodeUtf8Tail } from "../../shared/utf8.ts";
import { DIRS, type AsyncStatus, type NestedRunSummary, type SubagentState } from "../../shared/types.ts";
import { readStatus } from "../../shared/utils.ts";
import { readSessionMessagesTail, type SessionTranscriptMessage } from "./fleet-view.ts";
import { completionReplayPath, readCompletionArchive, readCompletionReplay } from "./completion-replay.ts";
import { resultPayloadPathForSessionRun } from "./result-files.ts";
import { resolveSubagentRunId } from "./run-id-resolver.ts";
import { reconcileAsyncRun, reconcileNestedAsyncDescendants } from "./stale-run-reconciler.ts";

/** On-demand inspection of current-session async children. Re-reads canonical artifacts after the same reconciliation as status; nothing is persisted or broadcast. */

export const INSPECT_REPLY_KIND = "pi-subagents.inspect-reply";
export const INSPECT_REPLY_VERSION = 1;
export const INSPECT_WIDGET_KEY = "subagent-inspect";
export const INSPECT_WIDGET_PREFIX = "PI_SUBAGENT_INSPECT_JSON:";

export type InspectErrorCode =
	| "invalid_request"
	| "not_found"
	| "foreign_session"
	| "stale"
	| "no_active_session"
	| "internal";

export interface InspectRequest {
	requestId: string;
	asyncId: string;
	childId?: string;
	lines?: number;
}

export interface InspectReplyMessage {
	role: string;
	kind: "text" | "toolCall" | "toolResult";
	text: string;
	name?: string;
	isError?: boolean;
}

export interface InspectReply {
	kind: typeof INSPECT_REPLY_KIND;
	version: typeof INSPECT_REPLY_VERSION;
	requestId: string;
	/** Canonical run id of the inspected node. Absent on error replies that
	 *  could not resolve a run. */
	asyncId?: string;
	childId?: string;
	status?: AsyncStatus["state"];
	label?: string;
	task?: string;
	messages?: InspectReplyMessage[];
	finalOutput?: string;
	truncated?: { task: boolean; messages: number; finalOutput: boolean };
	error?: { code: InspectErrorCode; message: string };
}

const REQUEST_ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;
const MAX_ID_LENGTH = 256;
const MAX_LABEL_LENGTH = 160;
const MAX_TASK_LENGTH = 2_000;
const MAX_FINAL_OUTPUT_LENGTH = 8_000;
const MAX_MESSAGE_TEXT_LENGTH = 1_000;
const DEFAULT_MESSAGE_LINES = 100;
const MAX_MESSAGE_LINES = 200;
const FAILED_OUTPUT_ARTIFACT_PREFIX = "Subagent run failed before producing output.\n\nError:\n";
export const MAX_SERIALIZED_BYTES = 64 * 1024;

export interface InspectDeps {
	state?: SubagentState;
	asyncDirRoot?: string;
	resultsDir?: string;
	kill?: (pid: number, signal?: NodeJS.Signals | 0) => boolean;
	now?: () => number;
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function publicText(value: unknown, maxLength: number): string | undefined {
	if (typeof value !== "string") return undefined;
	const normalized = sanitizeDisplayText(value.slice(0, maxLength * 4));
	return normalized ? truncateDisplayText(normalized, maxLength) : undefined;
}

/** Bound long-form content without flattening it: task/finalOutput/message text
 *  must keep newlines readable. Only the two unicode line separators are
 *  normalized, since JSON.stringify does not escape them and hosts split the
 *  widget payload on line boundaries. */
function boundContent(value: string, maxLength: number): string {
	const normalized = value.replace(/[\u2028\u2029]/g, "\n");
	return truncateDisplayText(normalized, maxLength);
}

function errorReply(request: Partial<InspectRequest>, code: InspectErrorCode, message: string): InspectReply {
	return {
		kind: INSPECT_REPLY_KIND,
		version: INSPECT_REPLY_VERSION,
		requestId: typeof request.requestId === "string" && REQUEST_ID_PATTERN.test(request.requestId) ? request.requestId : "invalid",
		...(typeof request.asyncId === "string" ? { asyncId: truncateDisplayText(request.asyncId, MAX_ID_LENGTH) } : {}),
		...(typeof request.childId === "string" ? { childId: truncateDisplayText(request.childId, MAX_ID_LENGTH) } : {}),
		error: { code, message },
	};
}

export function parseInspectRequest(args: string): { request?: InspectRequest; error?: string } {
	const tokens = args.trim().split(/\s+/).filter(Boolean);
	const positional: string[] = [];
	let lines: number | undefined;
	for (let index = 0; index < tokens.length; index++) {
		const token = tokens[index]!;
		if (token === "--lines") {
			const value = tokens[++index];
			const parsed = value === undefined ? NaN : Number.parseInt(value, 10);
			if (!Number.isFinite(parsed)) return { error: "--lines requires an integer value." };
			lines = parsed;
			continue;
		}
		if (token.startsWith("--")) return { error: `Unknown flag: ${token}. Supported: --lines N.` };
		positional.push(token);
	}
	const [requestId, asyncId, childId, ...extra] = positional;
	if (!requestId || !REQUEST_ID_PATTERN.test(requestId)) {
		return { error: "requestId must match [A-Za-z0-9_-]{1,64}." };
	}
	if (!asyncId) return { error: "Usage: /subagents-inspect-rpc <requestId> <asyncId> [childId] [--lines N]." };
	if (asyncId.length > MAX_ID_LENGTH || (childId !== undefined && childId.length > MAX_ID_LENGTH)) {
		return { error: "asyncId/childId exceed the maximum length." };
	}
	if (extra.length > 0) return { error: "Too many positional arguments. Usage: /subagents-inspect-rpc <requestId> <asyncId> [childId] [--lines N]." };
	if (lines !== undefined && (lines < 1 || !Number.isSafeInteger(lines))) return { error: "--lines must be a positive integer." };
	return { request: { requestId, asyncId, childId, lines } };
}

interface ResolvedNode {
	asyncDir: string;
	status: AsyncStatus;
	stepIndex?: number;
	label?: string;
}

function findChildNode(status: AsyncStatus, asyncDir: string, childId: string): ResolvedNode | { error: string } {
	const steps = status.steps ?? [];
	for (let index = 0; index < steps.length; index++) {
		const step = steps[index]!;
		const ids = [step.workflowKey, step.runId, `step:${index}`];
		if (ids.includes(childId)) {
			return { asyncDir, status, stepIndex: index, label: step.label ?? step.agent };
		}
	}
	const findNested = (children: readonly NestedRunSummary[] | undefined): NestedRunSummary | undefined => {
		for (const child of children ?? []) {
			if (child.id === childId) return child;
			const deeper = findNested(child.children);
			if (deeper) return deeper;
		}
		return undefined;
	};
	for (const step of steps) {
		const nested = findNested(step.children);
		if (nested) {
			if (!nested.asyncDir) return { error: `Child '${childId}' has no async directory to inspect.` };
			const childStatus = readStatus(nested.asyncDir);
			if (!childStatus) return { error: `Child '${childId}' status is unavailable.` };
			return { asyncDir: nested.asyncDir, status: childStatus, label: nested.agent ?? nested.agents?.join(", ") };
		}
	}
	return { error: `Child '${childId}' was not found under async run '${status.runId}'.` };
}

function resultOutput(data: unknown, stepIndex: number | undefined): { output?: string; errorText?: string } {
	if (!isRecord(data)) throw new Error("Async result payload must be an object.");
	if (data.results !== undefined && !Array.isArray(data.results)) throw new Error("Async result payload results must be an array.");
	if (data.summary !== undefined && typeof data.summary !== "string") throw new Error("Async result payload summary must be a string.");
	const results = data.results;
	if (stepIndex !== undefined && results) {
		const stepResult = results[stepIndex];
		if (stepResult === undefined) return {};
		if (!isRecord(stepResult)) throw new Error("Async result payload step result must be an object.");
		if (stepResult.output !== undefined && typeof stepResult.output !== "string") throw new Error("Async result payload step output must be a string.");
		if (stepResult.error !== undefined && typeof stepResult.error !== "string") throw new Error("Async result payload step error must be a string.");
		return {
			...(typeof stepResult.output === "string" ? { output: stepResult.output } : {}),
			...(typeof stepResult.error === "string" ? { errorText: stepResult.error } : {}),
		};
	}
	if (typeof data.summary === "string") return { output: data.summary };
	if (results?.length === 1) {
		const result = results[0];
		if (!isRecord(result)) throw new Error("Async result payload result must be an object.");
		if (result.output !== undefined && typeof result.output !== "string") throw new Error("Async result payload output must be a string.");
		if (typeof result.output === "string") return { output: result.output };
	}
	return {};
}

function readOutputArtifact(outputPath: string): { output?: string; errorText?: string } {
	const file = fs.openSync(outputPath, "r");
	try {
		const prefix = Buffer.allocUnsafe(Buffer.byteLength(FAILED_OUTPUT_ARTIFACT_PREFIX, "utf-8"));
		const prefixBytes = fs.readSync(file, prefix, 0, prefix.length, 0);
		const failedOutput = prefix.subarray(0, prefixBytes).toString("utf-8") === FAILED_OUTPUT_ARTIFACT_PREFIX;
		const size = fs.fstatSync(file).size;
		const length = Math.min(size, MAX_FINAL_OUTPUT_LENGTH * 4);
		const buffer = Buffer.allocUnsafe(length);
		const bytesRead = fs.readSync(file, buffer, 0, length, size - length);
		let text = decodeUtf8Tail(buffer.subarray(0, bytesRead));
		if (!failedOutput) return { output: text };
		const metadata = text.lastIndexOf("\nMetadata: ");
		if (metadata >= 0 && !text.slice(metadata + 1).includes("\n")) text = text.slice(0, metadata);
		const transcript = text.lastIndexOf("\n\nTranscript: ");
		if (transcript >= 0 && !text.slice(transcript + 2).includes("\n")) text = text.slice(0, transcript);
		return { errorText: text.startsWith(FAILED_OUTPUT_ARTIFACT_PREFIX) ? text.slice(FAILED_OUTPUT_ARTIFACT_PREFIX.length) : text };
	} finally {
		fs.closeSync(file);
	}
}

function readSessionBackedOutput(sessionPath: string, trustedRoots: string[]): { output?: string } {
	if (trustedRoots.length === 0) return {};
	// The archive retains the child's session file as its output record. The
	// final answer is the terminal assistant message's text — all text parts
	// of that one session record, not just the last part.
	const tail = readSessionMessagesTail(sessionPath, MAX_MESSAGE_LINES, trustedRoots);
	const last = tail.messages.findLast((message) => message.role === "assistant" && message.kind === "text");
	if (!last) return {};
	const parts = tail.messages.filter((message) => message.recordIndex === last.recordIndex && message.kind === "text");
	return { output: parts.map((part) => part.text).join("\n") };
}

function readResultOutput(resultsDir: string, sessionId: string, runId: string, stepIndex: number | undefined, trustedRoots: string[], stepAgent: string | undefined, now: () => number): { output?: string; errorText?: string } {
	const resultPath = resultPayloadPathForSessionRun(resultsDir, sessionId, runId);
	if (resultPath) return resultOutput(JSON.parse(fs.readFileSync(resultPath, "utf-8")) as unknown, stepIndex);
	// Read the raw record first: readCompletionReplay best-effort deletes
	// invalid or expired records, so reading after it cannot distinguish
	// "never existed" from "failed validation".
	const replayPath = completionReplayPath(resultsDir, runId);
	let rawReplay: unknown;
	try {
		rawReplay = JSON.parse(fs.readFileSync(replayPath, "utf-8")) as unknown;
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
	}
	const nowMs = now();
	const replay = readCompletionReplay(resultsDir, runId, { sessionId, now: nowMs });
	if (!replay) {
		// readCompletionReplay also returns undefined for absent, expired, foreign,
		// and unknown-version records. A current-version, unexpired record for this
		// run and session that still failed validation is an inspection failure,
		// not a child without output — surface it instead of replying success with
		// no finalOutput.
		if (isRecord(rawReplay) && rawReplay.version === 1 && rawReplay.runId === runId
			&& rawReplay.sessionId === sessionId
			&& typeof rawReplay.expiresAt === "number" && rawReplay.expiresAt > nowMs) {
			throw new Error("Completion replay record failed validation.");
		}
		return {};
	}
	const archive = readCompletionArchive(replay.archivePath);
	// Run-level inspection must not attribute a child's output to the run in a
	// multi-child archive. Current child entries carry resultIndex and agent;
	// run-level entries carry neither. Legacy archives (written before
	// resultIndex existed) have child entries with agent but no resultIndex,
	// so child reads fall back to a unique agent name. Duplicate legacy agent
	// names fail closed. A single-child archive is the one exception: the run's
	// output IS that child's output, including a legacy agent-tagged entry.
	const childEntries = archive?.entries.filter((entry) => entry.resultIndex !== undefined || entry.agent !== undefined) ?? [];
	const singleChild = childEntries.length === 1;
	const uniqueLegacyAgent = (agent: string | undefined): boolean =>
		agent !== undefined
		&& archive?.entries.filter((entry) => entry.resultIndex === undefined && entry.agent === agent).length === 1;
	const matches = (entry: { resultIndex?: number; agent?: string }): boolean => {
		if (stepIndex !== undefined) {
			if (entry.resultIndex !== undefined) return entry.resultIndex === stepIndex;
			return uniqueLegacyAgent(stepAgent) && entry.agent === stepAgent;
		}
		if (singleChild) return entry.resultIndex !== undefined || entry.agent !== undefined;
		return entry.resultIndex === undefined && entry.agent === undefined;
	};
	const artifact = archive?.entries.find((entry) => entry.source === "output-artifact" && matches(entry));
	const artifactPath = artifact?.source === "output-artifact" ? artifact.path : undefined;
	if (artifactPath) return readOutputArtifact(artifactPath);
	const sessionEntry = archive?.entries.find((entry) => entry.source === "session" && matches(entry));
	const sessionPath = sessionEntry?.source === "session" ? sessionEntry.path : undefined;
	if (sessionPath) return readSessionBackedOutput(sessionPath, trustedRoots);
	const output = archive?.entries.find((entry) => entry.source === "result-tail" && matches(entry))?.text;
	return output ? { output } : {};
}

function toReplyMessage(message: SessionTranscriptMessage): InspectReplyMessage {
	return {
		role: truncateDisplayText(sanitizeDisplayText(message.role), 32),
		kind: message.kind,
		text: boundContent(message.text, MAX_MESSAGE_TEXT_LENGTH),
		...(message.name ? { name: truncateDisplayText(sanitizeDisplayText(message.name), 96) } : {}),
		...(message.isError === true ? { isError: true } : {}),
	};
}

/** Fit the reply under MAX_SERIALIZED_BYTES: drop oldest messages first, then
 *  shrink finalOutput, then task. The envelope always survives. */
function enforceByteBudget(reply: InspectReply): InspectReply {
	const truncated = reply.truncated ?? { task: false, messages: 0, finalOutput: false };
	const sized = (): number => Buffer.byteLength(JSON.stringify(reply), "utf-8");
	while (reply.messages && reply.messages.length > 0 && sized() > MAX_SERIALIZED_BYTES) {
		reply.messages.shift();
		truncated.messages += 1;
	}
	if (sized() > MAX_SERIALIZED_BYTES && reply.finalOutput) {
		reply.finalOutput = truncateDisplayText(reply.finalOutput, Math.max(0, reply.finalOutput.length - (sized() - MAX_SERIALIZED_BYTES) - 256));
		truncated.finalOutput = true;
	}
	if (sized() > MAX_SERIALIZED_BYTES && reply.task) {
		reply.task = truncateDisplayText(reply.task, Math.max(0, reply.task.length - (sized() - MAX_SERIALIZED_BYTES) - 256));
		truncated.task = true;
	}
	if (truncated.task || truncated.messages > 0 || truncated.finalOutput) reply.truncated = truncated;
	return reply;
}

export function buildInspectReply(request: InspectRequest, deps: InspectDeps = {}): InspectReply {
	const asyncDirRoot = deps.asyncDirRoot ?? DIRS.async;
	const resultsDir = deps.resultsDir ?? DIRS.results;
	const currentSessionId = deps.state?.currentSessionId ?? undefined;
	if (!currentSessionId) {
		return errorReply(request, "no_active_session", "Inspection requires an active session; the request could not be attributed to a session.");
	}

	let resolved: ReturnType<typeof resolveSubagentRunId>;
	try {
		resolved = resolveSubagentRunId(request.asyncId, { asyncDirRoot, resultsDir, state: deps.state });
	} catch {
		return errorReply(request, "invalid_request", "The requested async run could not be resolved.");
	}
	if (!resolved || resolved.kind === "foreground") {
		return errorReply(request, "not_found", `Async run '${request.asyncId}' was not found.`);
	}

	try {
		let asyncDir: string;
		let status: AsyncStatus | null;
		if (resolved.kind === "nested") {
			reconcileNestedAsyncDescendants(resolved.match.route, { resultsDir, kill: deps.kill, now: deps.now });
			asyncDir = resolved.match.run.asyncDir ?? "";
			status = asyncDir ? readStatus(asyncDir) : null;
		} else {
			if (!resolved.location.asyncDir) return errorReply(request, "stale", `Async run '${request.asyncId}' has no remaining artifacts.`);
			asyncDir = resolved.location.asyncDir;
			status = reconcileAsyncRun(asyncDir, { resultsDir, kill: deps.kill, now: deps.now }).status ?? readStatus(asyncDir);
		}
		if (!status) return errorReply(request, "stale", `Async run '${request.asyncId}' artifacts are no longer available.`);
		if (status.sessionId !== currentSessionId) {
			return errorReply(request, "foreign_session", "Inspection is only available for async runs owned by the current session.");
		}

		const node: ResolvedNode | { error: string } = request.childId === undefined
			? { asyncDir, status }
			: findChildNode(status, asyncDir, request.childId);
		if ("error" in node) return errorReply(request, "not_found", node.error);
		if (node.asyncDir !== asyncDir) {
			if (node.status.sessionId !== currentSessionId) {
				return errorReply(request, "foreign_session", "Inspection is only available for async runs owned by the current session.");
			}
			reconcileAsyncRun(node.asyncDir, { resultsDir, kill: deps.kill, now: deps.now });
			node.status = readStatus(node.asyncDir) ?? node.status;
		}

		const step = node.stepIndex !== undefined ? node.status.steps?.[node.stepIndex] : undefined;
		const lineLimit = Math.max(1, Math.min(MAX_MESSAGE_LINES, Math.trunc(request.lines ?? DEFAULT_MESSAGE_LINES)));
		const sessionFile = step?.sessionFile ?? node.status.sessionFile;
		const trustedRoots = [...new Set([
			...(deps.state?.trustedSessionRoots ?? []),
			...(node.status.sessionRoot ? [node.status.sessionRoot] : []),
		])];

		let messages: InspectReplyMessage[] | undefined;
		let task: string | undefined;
		if (sessionFile && trustedRoots.length > 0) {
			const tail = readSessionMessagesTail(sessionFile, lineLimit, trustedRoots);
			if (tail.messages.length > 0) {
				messages = tail.messages.map(toReplyMessage);
				// The delegated task is the child session's first user message, but
				// only when it is genuinely attributable: fresh-context children
				// (forked sessions begin with inherited parent history) whose
				// session file is fully inside the read window (a truncated tail
				// means the first visible user message may be a steering message).
				if (!tail.truncated && node.status.context !== "fork" && step?.context !== "fork") {
					const firstUser = tail.messages.find((message) => message.role === "user" && message.kind === "text");
					if (firstUser) task = firstUser.text;
				}
			}
		}

		const result = readResultOutput(resultsDir, currentSessionId, node.status.runId, node.stepIndex, trustedRoots, step?.agent, deps.now ?? Date.now);
		const failedText = step?.error ?? node.status.error;
		if (result.output === undefined && result.errorText === undefined && failedText !== undefined) {
			return errorReply(request, "internal", "Inspection could not read the async run artifacts.");
		}
		const finalOutputRaw = result.output ?? result.errorText;

		const truncated = { task: false, messages: 0, finalOutput: false };
		const boundedTask = task !== undefined ? boundContent(task, MAX_TASK_LENGTH) : undefined;
		if (task !== undefined && boundedTask !== task) truncated.task = true;
		const boundedFinal = finalOutputRaw !== undefined ? boundContent(finalOutputRaw, MAX_FINAL_OUTPUT_LENGTH) : undefined;
		if (finalOutputRaw !== undefined && boundedFinal !== finalOutputRaw) truncated.finalOutput = true;
		const label = publicText(node.label ?? step?.label ?? step?.agent ?? node.status.runId, MAX_LABEL_LENGTH);

		const reply: InspectReply = {
			kind: INSPECT_REPLY_KIND,
			version: INSPECT_REPLY_VERSION,
			requestId: request.requestId,
			asyncId: node.status.runId,
			...(request.childId !== undefined ? { childId: request.childId } : {}),
			status: node.status.state,
			...(label ? { label } : {}),
			...(boundedTask !== undefined ? { task: boundedTask } : {}),
			...(messages && messages.length > 0 ? { messages } : {}),
			...(boundedFinal !== undefined ? { finalOutput: boundedFinal } : {}),
			...(truncated.task || truncated.finalOutput || truncated.messages > 0 ? { truncated } : {}),
		};
		return enforceByteBudget(reply);
	} catch {
		return errorReply(request, "internal", "Inspection could not read the async run artifacts.");
	}
}

export function encodeInspectReply(reply: InspectReply): string[] {
	return [`${INSPECT_WIDGET_PREFIX}${JSON.stringify(reply)}`];
}

/** Parse the slash-command args and always return a correlated inspect reply. */
export function handleInspectRpcArgs(args: string, deps: InspectDeps = {}): InspectReply {
	const parsed = parseInspectRequest(args);
	if (parsed.error || !parsed.request) {
		// Echo a well-formed requestId so the host can correlate the failure.
		const firstToken = args.trim().split(/\s+/)[0];
		const echo = firstToken !== undefined && REQUEST_ID_PATTERN.test(firstToken) ? { requestId: firstToken } : {};
		return errorReply(echo, "invalid_request", parsed.error ?? "Invalid inspect request.");
	}
	return buildInspectReply(parsed.request, deps);
}

