import { missionObserverResultCandidateFiles, promotePendingResultFile, removeMissionObserverIndex, removeResultIndex, resultCandidateFilesForSession, resultPayloadPathForIndexedRun, resultPayloadPathForMissionObserverRun, resultPayloadPathForSessionRun, writeAsyncResultFile, writeResultIndexForData } from "./result-files.ts";
import type { CompletionNotifier, CompletionNotification } from "./notify.ts";

const WATCHER_RESTART_DELAY_MS = 3000;
const POLL_INTERVAL_MS = 3000;
const HEALTHY_SCAN_INTERVAL_MS = 60_000;
const RETRY_DELAY_MS = 100;
const SLOW_RESULT_SCAN_MS = 500;

type ResultWatcherFs = Pick<typeof fs, "existsSync" | "readFileSync" | "unlinkSync" | "readdirSync" | "mkdirSync" | "realpathSync" | "statSync" | "watch">;

type ResultWatcherTimers = {
	setTimeout: typeof setTimeout;
	clearTimeout: typeof clearTimeout;
	setInterval: typeof setInterval;
	clearInterval: typeof clearInterval;
};

type ResultWatcherDeps = {
	fs?: ResultWatcherFs;
	timers?: ResultWatcherTimers;
	notifier?: Pick<CompletionNotifier, "deliver">;
	/** Receives persisted completions before active-session delivery filtering. */
	observeCompletion?: (result: CompletionNotification & { runId: string }) => void;
	/** Returns cross-session run ids that the completion observer currently owns. */
	observedCompletionRunIds?: () => Iterable<string>;
	/** Parses a relevant result payload after its lightweight identity check. */
	parseResult?: (raw: string) => ResultFileData;
	/** External grouped-result transport. Disable when native completion notifications own delivery. */
	deliverIntercomResults?: boolean;
	/** Coalesces result-file events. Tests can lower this without changing retry timing. */
	coalesceDelayMs?: number;
	/** Returns true while a durable completion source needs periodic delivery checks. */
	hasDeliveryDemand?: () => boolean;
	/** Control how slow result-index scans are logged. Defaults to \"activity\". */
	resultScanLogging?: "all" | "activity" | "off";
	platform?: NodeJS.Platform;
};

type ResultFileChild = {
	agent?: string;
	output?: string;
	structuredOutput?: unknown;
	outputState?: SubagentOutputState;
	error?: string;
	success?: boolean;
	state?: string;
	interrupted?: boolean;
	timedOut?: boolean;
	stopped?: boolean;
	turnBudgetExceeded?: boolean;
	processSignal?: string | null;
	sessionFile?: string;
	artifactPaths?: { outputPath?: string };
	intercomTarget?: string;
	children?: unknown;
};

type ResultFileData = CompletionNotification & {
	runId?: string;
	mode?: string;
	results?: ResultFileChild[];
	nestedChildren?: unknown;
	asyncDir?: string;
	intercomTarget?: string;
	parallelHandoff?: ParallelHandoffReference;
	notificationDeliveredAt?: unknown;
};

type ResultFileIdentity = {
	sessionId?: string;
	completionOwnerId?: string;
	runId?: string;
	asyncDir?: string;
};

interface ResultScanStats {
	files: number;
	scheduled: number;
	startedAt: number;
}

function jsonStringProperty(raw: string, property: string): string | undefined {
	const matches = raw.matchAll(new RegExp(`"${property}"\\s*:\\s*("(?:\\\\.|[^"\\\\])*")`, "g"));
	let encoded: string | undefined;
	for (const match of matches) encoded = match[1];
	if (!encoded) return undefined;
	try {
		const value = JSON.parse(encoded) as unknown;
		return typeof value === "string" && value ? value : undefined;
	} catch {
		return undefined;
	}
}

function resultFileIdentity(raw: string, file: string): ResultFileIdentity {
	return {
		sessionId: jsonStringProperty(raw, "sessionId"),
		completionOwnerId: jsonStringProperty(raw, "completionOwnerId"),
		runId: file.replace(/\.json$/i, ""),
		asyncDir: jsonStringProperty(raw, "asyncDir"),
	};
}

function sanitizeNestedResultChildren(value: unknown, resultPath: string, label: string): NestedRunSummary[] | undefined {
	if (value === undefined) return undefined;
	if (!Array.isArray(value)) {
		console.error(`Ignoring invalid nested children in subagent result file '${resultPath}' at ${label}: expected an array.`);
		return undefined;
	}
	const children = value.map((child) => sanitizeSummary(child)).filter((child): child is NestedRunSummary => Boolean(child));
	if (children.length !== value.length) {
		console.error(`Ignoring ${value.length - children.length} invalid nested child record(s) in subagent result file '${resultPath}' at ${label}.`);
	}
	return children.length ? children : undefined;
}

function errorCode(error: unknown): string | undefined {
	return typeof error === "object" && error !== null && "code" in error ? (error as NodeJS.ErrnoException).code : undefined;
}

function isNotFound(error: unknown): boolean {
	return errorCode(error) === "ENOENT";
}

function isAccessDenied(error: unknown): boolean {
	const code = errorCode(error);
	return code === "EPERM" || code === "EACCES";
}

function shouldPoll(error: unknown): boolean {
	const code = errorCode(error);
	return code === "EMFILE" || code === "ENOSPC";
}

function hasDeliveredNotification(data: ResultFileData): boolean {
	return typeof data.notificationDeliveredAt === "number" && Number.isFinite(data.notificationDeliveredAt);
}

type PublicResultIdentity = {
	state?: string;
	timestamp?: number;
};

function resultPayloadWasReplaced(delivered: ResultFileData, disk: PublicResultIdentity | undefined): boolean {
	if (!disk) return false;
	const deliveredState = typeof delivered.state === "string" ? delivered.state : undefined;
	if (disk.state && deliveredState && disk.state !== deliveredState) return true;
	const deliveredTimestamp = typeof delivered.timestamp === "number" && Number.isFinite(delivered.timestamp)
		? delivered.timestamp
		: undefined;
	return disk.timestamp !== undefined && deliveredTimestamp !== undefined && disk.timestamp !== deliveredTimestamp;
}

function markDeliveredNotification(resultPath: string, data: ResultFileData, runId: string, now: number): ResultFileData {
	const marked = { ...data, runId, notificationDeliveredAt: now };
	writeAsyncResultFile(resultPath, marked);
	return marked;
}

/**
 * Watches persisted async results for the session currently owned by this
 * runtime. `stopResultWatcher()` revokes ownership before closing resources,
 * so old callbacks can never emit or delete after reload/session replacement.
 */
export function createResultWatcher(
	pi: { events: IntercomEventBus },
	state: SubagentState,
	resultsDir: string,
	completionTtlMs: number,
	deps: ResultWatcherDeps = {},
): {
	startResultWatcher: () => void;
	primeExistingResults: (options?: { triggerTurn?: boolean }) => void;
	refreshResultDelivery: () => void;
	stopResultWatcher: () => void;
} {
	const fsApi = deps.fs ?? fs;
	const timers = deps.timers ?? { setTimeout, clearTimeout, setInterval, clearInterval };
	const notifier = deps.notifier ?? { deliver: async () => true };
	const parseResult = deps.parseResult ?? ((raw: string) => JSON.parse(raw) as ResultFileData);
	const deliverIntercomResults = deps.deliverIntercomResults !== false;
	const pendingTriggerTurn = new Map<string, boolean>();
	const processing = new Set<string>();
	const identityCache = new Map<string, { signature: string; identity: ResultFileIdentity }>();
	let deliveryActive = true;
	let deliveryEpoch = 0;
	let resultScanTimer: ReturnType<typeof setInterval> | null = null;
	// The sole in-memory ownership lease. It is acquired for one active session
	// and revoked before the watcher, queues, or callbacks are torn down.
	let activeSessionId: string | null = null;

	const ownsCompletion = (sessionId: string, completionOwnerId: unknown, epoch: number) => {
		if (!deliveryActive || epoch !== deliveryEpoch) return false;
		if (!activeSessionId && state.currentSessionId) activeSessionId = state.currentSessionId;
		return activeSessionId === sessionId
			&& state.currentSessionId === sessionId
			&& typeof completionOwnerId === "string"
			&& completionOwnerId === state.completionOwnerId;
	};

	const scheduleResult = (file: string, triggerTurn: boolean, delayMs = 0) => {
		const pendingMode = pendingTriggerTurn.get(file);
		pendingTriggerTurn.set(file, pendingMode === false || !triggerTurn ? false : true);
		state.resultFileCoalescer.schedule(file, delayMs);
	};

	const publicResultPath = (file: string): string => path.join(resultsDir, file);
	const publicResultFileExists = (file: string): boolean => {
		try {
			return fsApi.statSync(publicResultPath(file)).isFile();
		} catch (error) {
			if (!isNotFound(error)) console.error(`Failed to inspect subagent result file '${publicResultPath(file)}':`, error);
			return false;
		}
	};
	const resultPayloadPath = (file: string, observed?: ReadonlySet<string>): string | undefined => {
		if (file !== path.basename(file) || !file.endsWith(".json")) return undefined;
		const runId = file.replace(/\.json$/i, "");
		const sessionResult = state.currentSessionId ? resultPayloadPathForSessionRun(resultsDir, state.currentSessionId, runId) : undefined;
		if (sessionResult) return sessionResult;
		const observerResult = resultPayloadPathForMissionObserverRun(resultsDir, runId);
		if (observerResult) return observerResult;
		if (observed?.has(runId)) {
			const indexedResult = resultPayloadPathForIndexedRun(resultsDir, runId);
			if (indexedResult) return indexedResult;
		}
		return publicResultFileExists(file) ? publicResultPath(file) : undefined;
	};
	const resultSignature = (file: string, observed?: ReadonlySet<string>): string | undefined => {
		const resultPath = resultPayloadPath(file, observed);
		if (!resultPath) {
			identityCache.delete(file);
			return undefined;
		}
		try {
			const stat = fsApi.statSync(resultPath);
			if (!stat.isFile()) return undefined;
			return `${resultPath}:${stat.size}:${stat.mtimeMs}`;
		} catch (error) {
			identityCache.delete(file);
			if (isAccessDenied(error)) throw error;
			if (!isNotFound(error)) console.error(`Failed to inspect subagent result file '${resultPath}':`, error);
			return undefined;
		}
	};
	const inspectResult = (file: string, knownSignature?: string, observed?: ReadonlySet<string>): { identity: ResultFileIdentity; signature: string } | undefined => {
		const resultPath = resultPayloadPath(file, observed);
		if (!resultPath) return undefined;
		try {
			const signature = knownSignature ?? resultSignature(file, observed);
			if (!signature) return undefined;
			const cached = identityCache.get(file);
			if (cached?.signature === signature) return { identity: cached.identity, signature };
			const identity = resultFileIdentity(fsApi.readFileSync(resultPath, "utf-8"), file);
			identityCache.set(file, { signature, identity });
			return { identity, signature };
		} catch (error) {
			identityCache.delete(file);
			if (isAccessDenied(error)) throw error;
			if (!isNotFound(error)) console.error(`Failed to inspect subagent result file '${resultPath}':`, error);
			return undefined;
		}
	};

	const observedRunIds = (): ReadonlySet<string> => {
		try {
			return new Set(deps.observedCompletionRunIds?.() ?? []);
		} catch (error) {
			console.error("Failed to inspect observed subagent completion ids:", error);
			return new Set();
		}
	};

	const shouldProcessResult = (file: string, observed?: ReadonlySet<string>, knownSignature?: string): boolean => {
		const inspected = inspectResult(file, knownSignature, observed);
		if (!inspected) return false;
		const { identity } = inspected;
		// Missing identity stays on the normal parser path so malformed or legacy
		// files keep their existing diagnostics and compatibility behavior.
		if (!identity.sessionId) return true;
		if (identity.sessionId === state.currentSessionId && identity.completionOwnerId === state.completionOwnerId) return true;
		if (identity.asyncDir && fsApi.existsSync(path.join(identity.asyncDir, MISSION_BINDING_FILE))) return true;
		if (identity.runId && (observed ?? observedRunIds()).has(identity.runId)) return true;
		return Boolean(deps.observeCompletion && !deps.observedCompletionRunIds);
	};

	const removeDeliveredResult = (file: string, sessionId: string, runId: string, toolCallId: string | undefined): boolean => {
		try {
			if (publicResultFileExists(file)) fsApi.unlinkSync(publicResultPath(file));
			identityCache.delete(file);
			removeResultIndex(resultsDir, sessionId, runId, toolCallId);
			return true;
		} catch (error) {
			if (!isNotFound(error)) {
				console.error(`Failed to remove delivered subagent result '${publicResultPath(file)}'; will retry:`, error);
				return false;
			}
			return true;
		}
	};
	const handleResult = async (file: string, triggerTurn: boolean) => {
		if (processing.has(file)) return;
		let observed: ReadonlySet<string> | undefined;
		try {
			if (!shouldProcessResult(file)) {
				const runId = file === path.basename(file) && file.endsWith(".json") ? file.replace(/\.json$/i, "") : undefined;
				observed = observedRunIds();
				if (!runId || !observed.has(runId) || !shouldProcessResult(file, observed)) return;
			}
		} catch (error) {
			if (!isAccessDenied(error)) throw error;
			console.error(`Failed to inspect subagent result file '${publicResultPath(file)}'; will retry:`, error);
			scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
			return;
		}
		processing.add(file);
		let rereadReplacedPayload = false;
		let resultPath = publicResultPath(file);
		const readPublicResultIdentity = (): PublicResultIdentity | undefined => {
			if (!publicResultFileExists(file)) return undefined;
			const parsed: unknown = JSON.parse(fsApi.readFileSync(publicResultPath(file), "utf-8"));
			if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) return undefined;
			const record = parsed as Record<string, unknown>;
			const state = typeof record.state === "string" && record.state ? record.state : undefined;
			const timestamp = typeof record.timestamp === "number" && Number.isFinite(record.timestamp)
				? record.timestamp
				: undefined;
			if (!state && timestamp === undefined) return undefined;
			return { state, timestamp };
		};
		try {
			const payloadPath = resultPayloadPath(file, observed);
			if (!payloadPath) return;
			resultPath = payloadPath;
			let raw = fsApi.readFileSync(resultPath, "utf-8");
			let identity = resultFileIdentity(raw, file);
			if (identity.sessionId && identity.runId) {
				const pendingState = promotePendingResultFile(resultsDir, identity.sessionId, identity.runId, file);
				if (pendingState === "promoted") {
					identityCache.delete(file);
					resultPath = publicResultPath(file);
					raw = fsApi.readFileSync(resultPath, "utf-8");
					identity = resultFileIdentity(raw, file);
				} else if (pendingState === "pending") {
					const pendingPath = resultPayloadPathForSessionRun(resultsDir, identity.sessionId, identity.runId);
					if (!pendingPath) {
						scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
						return;
					}
					resultPath = pendingPath;
					raw = fsApi.readFileSync(resultPath, "utf-8");
					identity = resultFileIdentity(raw, file);
				}
			}
			let data = parseResult(raw);
			const markReplacedPayload = (): boolean => {
				try {
					if (!resultPayloadWasReplaced(data, readPublicResultIdentity())) return false;
				} catch (error) {
					if (isAccessDenied(error)) throw error;
					if (isNotFound(error)) return false;
					console.error(`Failed to re-read subagent result file '${publicResultPath(file)}':`, error);
				}
				identityCache.delete(file);
				rereadReplacedPayload = true;
				return true;
			};
			if (typeof data.sessionId !== "string" || !data.sessionId) return;
			const sessionId = data.sessionId;
			const completionOwnerId = data.completionOwnerId;
			const runId = data.runId ?? data.id ?? file.replace(/\.json$/i, "");
			const toolCallId = typeof data.toolCallId === "string" ? data.toolCallId : undefined;
			let observerSucceeded = true;
			try {
				syncMissionFromAsyncCompletion({ ...data, runId });
			} catch (error) {
				observerSucceeded = false;
				console.error(`Mission completion sync failed for '${resultPath}':`, error);
			}
			try {
				deps.observeCompletion?.({ ...data, runId });
			} catch (error) {
				observerSucceeded = false;
				console.error(`Completion observer failed for '${resultPath}':`, error);
			}
			if (observerSucceeded) removeMissionObserverIndex(resultsDir, runId);
			const epoch = deliveryEpoch;
			if (!ownsCompletion(sessionId, completionOwnerId, epoch)) return;
			// Recorded before dedupe and before the unlink below so subagent_wait can
			// use the in-memory record or its bounded durable replay after cleanup.
			recordWaitCompletion(state, runId, data, Date.now(), completionTtlMs, {
				resultsDir,
				sessionId,
			});
			const hasExplicitNestedChildren = data.nestedChildren !== undefined;
			let nestedChildren = compactNestedResultChildren(sanitizeNestedResultChildren(data.nestedChildren, resultPath, "nestedChildren"));
			if (!nestedChildren?.length && !hasExplicitNestedChildren) {
				try {
					nestedChildren = compactNestedResultChildren(projectNestedRegistryForRoot(runId)?.children);
				} catch (error) {
					console.error(`Failed to enrich subagent result file '${resultPath}' with nested registry children; will retry later:`, error);
					scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
					return;
				}
			}

			const completionKey = buildCompletionKey(data, `result:${file}`);
			const alreadyDelivered = hasDeliveredNotification(data);
			const lastSeenAt = state.completionSeen.get(completionKey);
			if (lastSeenAt !== undefined && Date.now() - lastSeenAt > completionTtlMs) {
				state.completionSeen.delete(completionKey);
			} else if (lastSeenAt !== undefined) {
				if (!observerSucceeded) {
					scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
					return;
				}
				if (!ownsCompletion(sessionId, completionOwnerId, epoch)) return;
				if (markReplacedPayload()) return;
				if (!removeDeliveredResult(file, sessionId, runId, toolCallId)) scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
				return;
			}

			const hasResultChildren = Array.isArray(data.results) && data.results.length > 0;
			const resultChildren: ResultFileChild[] = hasResultChildren
				? data.results!
				: [{ agent: data.agent ?? undefined, output: data.summary, outputState: "unknown", success: data.success }];
			const normalizedChildren = attachNestedChildrenToResultChildren(runId, resultChildren.map((result = {}, index): SubagentResultIntercomChild => {
				const baseOutput = hasResultChildren ? result.output : result.output ?? data.summary;
				const hasRealOutput = typeof baseOutput === "string" && baseOutput.trim().length > 0;
				const structuredPreview = result.structuredOutput === undefined ? undefined : JSON.stringify(result.structuredOutput, null, 2).slice(0, 4_000);
				const output = hasRealOutput ? baseOutput : structuredPreview ? `Structured output:\n${structuredPreview}` : "(no output)";
				const summary = result.success === false && result.error
					? `${result.error}${hasRealOutput ? `\n\nOutput:\n${baseOutput}` : ""}`
					: output;
				const sessionPath = result.sessionFile ?? (resultChildren.length === 1 ? data.sessionFile : undefined);
				const childNestedChildren = sanitizeNestedResultChildren(result.children, resultPath, `results[${index}].children`);
				const childState = result.state === "paused" || result.state === "stopped"
					? result.state
					: result.stopped === true
						? "stopped"
						: data.state === "paused" || (!hasResultChildren && (data.state === "stopped" || typeof result.success !== "boolean"))
							? data.state
							: undefined;
				return {
					agent: result.agent ?? data.agent ?? `step-${index + 1}`,
					status: resolveSubagentResultStatus({
						success: result.success,
						state: childState,
						interrupted: result.interrupted,
						timedOut: result.timedOut,
						stopped: result.stopped,
						turnBudgetExceeded: result.turnBudgetExceeded,
						processSignal: result.processSignal,
					}),
					outputState: result.outputState === "present" || result.outputState === "absent" || result.outputState === "unknown"
						? result.outputState
						: "unknown",
					summary,
					index,
					artifactPath: result.artifactPaths?.outputPath,
					...(typeof sessionPath === "string" && fsApi.existsSync(sessionPath) ? { sessionPath } : {}),
					...(result.intercomTarget ? { intercomTarget: result.intercomTarget } : {}),
					...(childNestedChildren ? { children: childNestedChildren } : {}),
				};
			}), nestedChildren);

			if (alreadyDelivered) {
				markSeenWithTtl(state.completionSeen, completionKey, Date.now(), completionTtlMs);
				if (!observerSucceeded) {
					scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
					return;
				}
				if (!ownsCompletion(sessionId, completionOwnerId, epoch)) return;
				if (markReplacedPayload()) return;
				if (!removeDeliveredResult(file, sessionId, runId, toolCallId)) scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
				return;
			}

			const intercomTarget = data.intercomTarget?.trim();
			let intercomDelivered = false;
			if (deliverIntercomResults && intercomTarget && triggerTurn) {
				const mode = data.mode === "single" || data.mode === "parallel" || data.mode === "chain" || data.mode === "workflow"
					? data.mode
					: resultChildren.length > 1 ? "chain" : "single";
				intercomDelivered = await deliverSubagentResultIntercomEvent(pi.events, buildSubagentResultIntercomPayload({
					to: intercomTarget,
					runId,
					mode,
					source: "async",
					children: normalizedChildren,
					asyncId: data.id ?? undefined,
					asyncDir: data.asyncDir,
					...(data.parallelHandoff ? { parallelHandoff: data.parallelHandoff } : {}),
				}));
				if (!ownsCompletion(sessionId, completionOwnerId, epoch)) return;
				if (!intercomDelivered) console.error(`Subagent async grouped result intercom delivery was not acknowledged for '${resultPath}'.`);
			}

			const accepted = await notifier.deliver({
				...data,
				id: data.id ?? runId,
				runId,
				triggerTurn,
				intercomDelivered,
				...(nestedChildren?.length ? { nestedChildren } : {}),
				...(Array.isArray(data.results) ? {
					results: hasResultChildren ? normalizedChildren.map((child, index) => ({
						...data.results![index],
						agent: child.agent,
						status: child.status,
						summary: child.summary,
						index: child.index,
						artifactPath: child.artifactPath,
						sessionPath: child.sessionPath,
						children: child.children,
					})) : [],
				} : {}),
			});
			if (!ownsCompletion(sessionId, completionOwnerId, epoch)) return;
			if (!accepted) {
				scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
				return;
			}
			if (markReplacedPayload()) return;
			try {
				data = markDeliveredNotification(publicResultPath(file), data, runId, Date.now());
				identityCache.delete(file);
			} catch (error) {
				console.error(`Failed to mark subagent result notification delivered for '${resultPath}'; will retry:`, error);
				scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
				return;
			}
			markSeenWithTtl(state.completionSeen, completionKey, Date.now(), completionTtlMs);
			try {
				pi.events.emit(SUBAGENT_ASYNC_COMPLETE_EVENT, {
					...data,
					runId,
					triggerTurn,
					intercomDelivered,
					...(nestedChildren?.length ? { nestedChildren } : {}),
					...(Array.isArray(data.results) ? {
						results: hasResultChildren ? normalizedChildren.map((child, index) => ({
							...data.results![index],
							agent: child.agent,
							status: child.status,
							summary: child.summary,
							index: child.index,
							artifactPath: child.artifactPath,
							sessionPath: child.sessionPath,
							children: child.children,
						})) : [],
					} : {}),
				});
			} catch (error) {
				console.error(`Completion observer failed for '${resultPath}':`, error);
			}
			if (!observerSucceeded) {
				scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
				return;
			}
			if (!ownsCompletion(sessionId, completionOwnerId, epoch)) return;
			if (!removeDeliveredResult(file, sessionId, runId, toolCallId)) scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
		} catch (error) {
			if (isAccessDenied(error)) {
				console.error(`Failed to process subagent result file '${resultPath}'; will retry:`, error);
				scheduleResult(file, triggerTurn, RETRY_DELAY_MS);
			} else if (!isNotFound(error)) console.error(`Failed to process subagent result file '${resultPath}':`, error);
		} finally {
			processing.delete(file);
			if (rereadReplacedPayload) scheduleResult(file, triggerTurn);
		}
	};

	state.resultFileCoalescer = createFileCoalescer((file) => {
		const triggerTurn = pendingTriggerTurn.get(file) !== false;
		pendingTriggerTurn.delete(file);
		void handleResult(file, triggerTurn);
	}, deps.coalesceDelayMs ?? 50);

	const logScanStats = (stats: ResultScanStats) => {
		const elapsed = Date.now() - stats.startedAt;
		if (elapsed < SLOW_RESULT_SCAN_MS) return;
		const resultScanLogging = deps.resultScanLogging ?? "activity";
		if (resultScanLogging === "off") return;
		// A scan that inspected and scheduled nothing is a quiet no-op (e.g. the
		// healthy periodic rescan while no async runs are pending). Under
		// "activity", skip it so empty scans do not burn context tokens in the
		// session transcript.
		if (resultScanLogging === "activity" && stats.files === 0 && stats.scheduled === 0) return;
		console.error(`Subagent result scan inspected ${stats.files} indexed result file(s), scheduled ${stats.scheduled} in ${elapsed}ms (${resultsDir}).`);
	};
	const indexedResultCandidates = (observed: ReadonlySet<string>): string[] => {
		const files = new Set<string>();
		if (state.currentSessionId) {
			for (const file of resultCandidateFilesForSession(resultsDir, state.currentSessionId)) files.add(file);
		}
		for (const runId of state.asyncJobs.keys()) files.add(`${runId}.json`);
		for (const file of missionObserverResultCandidateFiles(resultsDir)) files.add(file);
		for (const runId of observed) files.add(`${runId}.json`);
		return [...files];
	};
	const primeExistingResults = (options: { triggerTurn?: boolean } = {}) => {
		try {
			const triggerTurn = options.triggerTurn !== false;
			const stats: ResultScanStats = { files: 0, scheduled: 0, startedAt: Date.now() };
			const observed = observedRunIds();
			for (const file of indexedResultCandidates(observed)) {
				stats.files += 1;
				const signature = resultSignature(file, observed);
				if (!signature) continue;
				if (!shouldProcessResult(file, observed, signature)) continue;
				stats.scheduled += 1;
				scheduleResult(file, triggerTurn);
			}
			logScanStats(stats);
		} catch (error) {
			if (!isNotFound(error)) console.error(`Failed to scan subagent result index in '${resultsDir}':`, error);
		}
	};

	const clearResultScan = () => {
		if (resultScanTimer) timers.clearInterval(resultScanTimer);
		resultScanTimer = null;
	};
	const useNativeWatcher = () => shouldUseNativeFsWatch("result-delivery", deps.platform);
	const hasDeliveryDemand = () => {
		try {
			return deps.hasDeliveryDemand?.() === true;
		} catch (error) {
			console.error("Failed to inspect subagent result delivery demand:", error);
			return false;
		}
	};
	const clearResultPoller = () => {
		if (!state.watcherRestartTimer) return;
		timers.clearTimeout(state.watcherRestartTimer);
		timers.clearInterval(state.watcherRestartTimer);
		state.watcherRestartTimer = null;
	};
	const startDemandPolling = () => {
		if (!deliveryActive || useNativeWatcher() || state.watcherRestartTimer) return;
		if (!hasDeliveryDemand()) return;
		state.watcherRestartTimer = timers.setInterval(() => {
			primeExistingResults();
			if (!hasDeliveryDemand()) clearResultPoller();
		}, POLL_INTERVAL_MS);
		state.watcherRestartTimer.unref?.();
	};

	const startPolling = (reason: unknown) => {
		state.watcher?.close();
		state.watcher = null;
		clearResultScan();
		if (state.watcherRestartTimer) return;
		console.error(`Subagent result watcher for '${resultsDir}' fell back to polling because native fs.watch is unavailable (${errorCode(reason) ?? "unknown error"}).`);
		primeExistingResults();
		state.watcherRestartTimer = timers.setInterval(primeExistingResults, POLL_INTERVAL_MS);
		state.watcherRestartTimer.unref?.();
	};

	const scheduleRestart = () => {
		clearResultScan();
		if (state.watcherRestartTimer) return;
		state.watcherRestartTimer = timers.setTimeout(() => {
			state.watcherRestartTimer = null;
			try {
				fsApi.mkdirSync(resultsDir, { recursive: true });
				startResultWatcher();
			} catch (error) {
				if (shouldPoll(error)) return startPolling(error);
				console.error(`Failed to restart subagent result watcher for '${resultsDir}':`, error);
				scheduleRestart();
			}
		}, WATCHER_RESTART_DELAY_MS);
		state.watcherRestartTimer.unref?.();
	};

	const startResultWatcher = () => {
		if (state.watcher) return;
		activeSessionId = state.currentSessionId;
		deliveryActive = true;
		deliveryEpoch += 1;
		if (state.watcherRestartTimer) {
			timers.clearTimeout(state.watcherRestartTimer);
			timers.clearInterval(state.watcherRestartTimer);
			state.watcherRestartTimer = null;
		}
		if (!useNativeWatcher()) {
			startDemandPolling();
			return;
		}
		try {
			const watchDir = resolveWatchPath(resultsDir, fsApi.realpathSync.native);
			state.watcher = fsApi.watch(watchDir, (_event, file) => {
				if (!file) {
					primeExistingResults();
					return;
				}
				const fileName = file.toString();
				if (fileName.endsWith(".json")) {
					identityCache.delete(fileName);
					try {
						writeResultIndexForData(path.join(resultsDir, fileName), JSON.parse(fsApi.readFileSync(path.join(resultsDir, fileName), "utf-8")) as Record<string, unknown>);
					} catch {
						// The writer may still be renaming the file; handleResult will retry from the normal result path.
					}
					scheduleResult(fileName, true);
				}
			});
			state.watcher.on("error", (error) => {
				if (shouldPoll(error)) return startPolling(error);
				console.error(`Subagent result watcher failed for '${resultsDir}':`, error);
				state.watcher?.close();
				state.watcher = null;
				scheduleRestart();
			});
			state.watcher.unref?.();
			resultScanTimer = timers.setInterval(primeExistingResults, HEALTHY_SCAN_INTERVAL_MS);
			resultScanTimer.unref?.();
		} catch (error) {
			if (shouldPoll(error)) return startPolling(error);
			console.error(`Failed to start subagent result watcher for '${resultsDir}':`, error);
			state.watcher = null;
			scheduleRestart();
		}
	};

	const stopResultWatcher = () => {
		deliveryActive = false;
		activeSessionId = null;
		deliveryEpoch += 1;
		state.watcher?.close();
		state.watcher = null;
		clearResultPoller();
		clearResultScan();
		state.resultFileCoalescer.clear();
		pendingTriggerTurn.clear();
		processing.clear();
		identityCache.clear();
	};

	return { startResultWatcher, primeExistingResults, stopResultWatcher, refreshResultDelivery: () => { primeExistingResults(); startDemandPolling(); } };
}

import * as fs from "node:fs";
import type { AsyncRunSummary } from "./async-status.ts";
import { readAsyncRecoveryDescriptor } from "./async-resume.ts";

const INTERCOM_DETACH_ERROR = "detached for intercom coordination";

function isIntercomDetached(run: AsyncRunSummary): boolean {
	return run.steps.some((step) => step.execution?.status === "detached"
		|| step.error?.toLowerCase().includes(INTERCOM_DETACH_ERROR) === true)
		|| run.error?.toLowerCase().includes(INTERCOM_DETACH_ERROR) === true;
}

function formatIntercomDetachGuidance(run: AsyncRunSummary): string | undefined {
	if (!isIntercomDetached(run)) return undefined;
	return `Run "${run.id}" detached for intercom coordination. Reply to the supervisor request first, then wait with subagent_wait({ id: "${run.id}" }). Use subagent({ action: "status", id: "${run.id}" }) to recover the result; do not resume or launch a replacement while it remains detached.`;
}

export function formatAsyncReviveCommand(run: AsyncRunSummary): string | undefined {
	const step = run.steps.find((candidate) => candidate.status === "failed");
	const sessionFile = step?.sessionFile ?? (run.steps.length === 1 ? run.sessionFile : undefined);
	if (!step || !sessionFile || !fs.existsSync(sessionFile)) return undefined;
	try {
		const descriptor = readAsyncRecoveryDescriptor(run.asyncDir);
		if (!descriptor || descriptor.sourceRunId !== run.id || descriptor.agent !== step.agent) return undefined;
	} catch {
		return undefined;
	}
	const index = run.steps.length === 1 ? "" : `, index: ${step.index}`;
	return `subagent({ action: "resume", id: "${run.id}"${index}, message: "Continue from the persisted child session and report the result." })`;
}

export function formatResumeFirstFailedRunDetail(run: AsyncRunSummary): string | undefined {
	if (run.state !== "failed") return undefined;
	const detachGuidance = formatIntercomDetachGuidance(run);
	if (detachGuidance) return detachGuidance;
	const command = formatAsyncReviveCommand(run);
	if (!command) return undefined;
	return `Resume-first: failed run "${run.id}" has a persisted child session. Revive the original run with ${command} before reporting failure or launching a replacement. Launch a replacement only if revive fails or the user explicitly asks for one.`;
}

export function formatResumeFirstFailedRunsNote(runs: AsyncRunSummary[]): string {
	const failedRuns = runs.filter((run) => run.state === "failed");
	const detachGuidance = failedRuns
		.map(formatIntercomDetachGuidance)
		.filter((guidance): guidance is string => Boolean(guidance));
	const resumable = failedRuns
		.filter((run) => !isIntercomDetached(run))
		.map((run) => ({ run, command: formatAsyncReviveCommand(run) }))
		.filter((entry): entry is { run: AsyncRunSummary; command: string } => Boolean(entry.command));
	const resumeGuidance = resumable.length === 0
		? ""
		: resumable.length === 1
			? ` Resume-first: failed run "${resumable[0]!.run.id}" has a persisted child session. Revive the original run with ${resumable[0]!.command} before reporting failure or launching a replacement. Launch a replacement only if revive fails or the user explicitly asks for one.`
			: ` Resume-first: ${resumable.length} failed runs have persisted child sessions. Inspect status and revive each original run before reporting failure or launching a replacement. Launch a replacement only if revive fails or the user explicitly asks for one.`;
	return `${detachGuidance.length > 0 ? ` ${detachGuidance.join(" ")}` : ""}${resumeGuidance}`;
}

import * as fs from "node:fs";
import { listAsyncRuns, type AsyncRunSummary } from "./async-status.ts";
import { readAsyncRecoveryDescriptor } from "./async-resume.ts";
import type { TokenUsage } from "../../shared/types.ts";
import { parallelHandoffPath, resolveRetainedWorktreeCwd } from "../shared/parallel-handoff.ts";

const MAX_RETAINED_CHILDREN = 10;
const MAX_RETAINED_CHILD_CANDIDATES = 100;
const MAX_TASK_SUMMARY_LENGTH = 120;

type RetainedChildState = "complete" | "failed" | "paused" | "stopped";
type RetainedChildResumability =
	| { state: "resumable"; sessionPath: string }
	| { state: "not-resumable"; reason: string };

export interface RetainedChild {
	runId: string;
	parentRunId?: string;
	workflowKey?: string;
	state: RetainedChildState;
	agent: string;
	taskSummary: string;
	completedAt: number;
	resumability: RetainedChildResumability;
	sessionPath?: string;
	tokenTotals?: TokenUsage;
}

function isRetainedChildState(state: AsyncRunSummary["state"]): state is RetainedChildState {
	return state === "complete" || state === "failed" || state === "paused" || state === "stopped";
}

function isTerminalStepStatus(status: AsyncRunSummary["steps"][number]["status"]): boolean {
	return status === "complete" || status === "completed" || status === "failed" || status === "paused" || status === "stopped";
}

function retainedSessionFile(sessionFile: string | undefined): RetainedChildResumability {
	if (!sessionFile) return { state: "not-resumable", reason: "no persisted session file" };
	if (!sessionFile.endsWith(".jsonl")) return { state: "not-resumable", reason: "persisted session file is not a .jsonl file" };
	try {
		const stat = fs.lstatSync(sessionFile);
		if (!stat.isFile() || stat.isSymbolicLink()) return { state: "not-resumable", reason: "persisted session file is not a regular file" };
		return { state: "resumable", sessionPath: sessionFile };
	} catch (error) {
		if (typeof error === "object" && error !== null && "code" in error && (error as NodeJS.ErrnoException).code === "ENOENT") {
			return { state: "not-resumable", reason: `persisted session file is missing: ${sessionFile}` };
		}
		return { state: "not-resumable", reason: `persisted session file could not be inspected: ${error instanceof Error ? error.message : String(error)}` };
	}
}

function childResumability(run: AsyncRunSummary, step: AsyncRunSummary["steps"][number]): RetainedChildResumability {
	if (run.state === "stopped" || step.status === "stopped") return { state: "not-resumable", reason: "stopped run" };
	if (step.runner?.type === "external-cli" || step.runner?.type === "external-job") return { state: "not-resumable", reason: "external runner" };
	const session = retainedSessionFile(step.sessionFile ?? run.sessionFile);
	if (session.state === "not-resumable") return session;
	let recoveryDescriptor: ReturnType<typeof readAsyncRecoveryDescriptor>;
	try {
		recoveryDescriptor = readAsyncRecoveryDescriptor(run.asyncDir);
		if (!recoveryDescriptor) return { state: "not-resumable", reason: "missing recovery descriptor" };
		if (recoveryDescriptor.sourceRunId !== run.id) return { state: "not-resumable", reason: `recovery descriptor belongs to run ${recoveryDescriptor.sourceRunId}` };
		if (recoveryDescriptor.agent !== step.agent) return { state: "not-resumable", reason: `recovery descriptor belongs to agent ${recoveryDescriptor.agent}` };
	} catch (error) {
		return { state: "not-resumable", reason: `invalid recovery descriptor: ${error instanceof Error ? error.message : String(error)}` };
	}
	let requiredCwd: string | undefined;
	try {
		requiredCwd = resolveRetainedWorktreeCwd(parallelHandoffPath(run.asyncDir), run.id, step.index) ?? recoveryDescriptor.cwd ?? run.cwd;
		if (!requiredCwd || !fs.statSync(requiredCwd).isDirectory()) return { state: "not-resumable", reason: `required cwd is missing: ${requiredCwd ?? "unknown"}` };
	} catch (error) {
		return { state: "not-resumable", reason: `resume dependency unavailable: ${error instanceof Error ? error.message : String(error)}` };
	}
	return session;
}

function boundedTaskSummary(value: string | undefined): string {
	const normalized = value?.replace(/\s+/g, " ").trim() ?? "";
	return normalized.length > MAX_TASK_SUMMARY_LENGTH
		? `${normalized.slice(0, MAX_TASK_SUMMARY_LENGTH - 1)}…`
		: normalized;
}

export function listRetainedChildren(asyncDirRoot: string, sessionId: string): RetainedChild[] {
	const children = listAsyncRuns(asyncDirRoot, { sessionId, states: ["complete", "failed", "paused", "stopped"], entryLimit: MAX_RETAINED_CHILD_CANDIDATES, reconcile: false })
		.flatMap((run) => {
			if (!run.parentWorkflowRunId || run.steps.length !== 1) return [];
			if (!isRetainedChildState(run.state)) return [];
			const step = run.steps[0]!;
			if (!isTerminalStepStatus(step.status)) return [];
			const completedAt = run.endedAt ?? run.lastUpdate;
			if (completedAt === undefined) return [];
			const resumability = childResumability(run, step);
			return [{
				runId: run.id,
				...(run.parentWorkflowRunId ? { parentRunId: run.parentWorkflowRunId } : {}),
				...(run.workflowKey ? { workflowKey: run.workflowKey } : {}),
				state: run.state,
				agent: step.agent,
				taskSummary: boundedTaskSummary(step.description),
				completedAt,
				resumability,
				...(resumability.state === "resumable" ? { sessionPath: resumability.sessionPath } : {}),
				...(step.tokens ?? run.totalTokens ? { tokenTotals: step.tokens ?? run.totalTokens } : {}),
			}];
		})
		.sort((left, right) => right.completedAt - left.completedAt);
	return children;
}

export function formatRetainedChildren(children: RetainedChild[]): string {
	if (children.length === 0) return "No retained workflow children in the active parent session. If a retained-writer challenge is required, launch a same-role fallback challenge and label it as fallback.";
	const retained = children.slice(0, MAX_RETAINED_CHILDREN);
	if (!retained.some((child) => child.resumability.state === "resumable")) {
		const resumable = children.slice(MAX_RETAINED_CHILDREN).find((child) => child.resumability.state === "resumable");
		if (resumable && retained.length === MAX_RETAINED_CHILDREN) retained[MAX_RETAINED_CHILDREN - 1] = resumable;
	}
	const hasResumableChild = retained.some((child) => child.resumability.state === "resumable");
	return [
		`Retained workflow children (up to ${MAX_RETAINED_CHILDREN}; newest first, with a resumable child retained when available):`,
		...retained.flatMap((child) => [
			`- ${child.runId} | ${child.agent} | ${child.state} | ${new Date(child.completedAt).toISOString()}`,
			...(child.parentRunId ? [`  workflow: ${child.parentRunId}${child.workflowKey ? ` (${child.workflowKey})` : ""}`] : []),
			`  task: ${child.taskSummary || "(no task summary)"}`,
			child.resumability.state === "resumable"
				? "  resumability: resumable"
				: `  resumability: not resumable (${child.resumability.reason})`,
			...(child.resumability.state === "resumable" ? [
				`  session: ${child.resumability.sessionPath}`,
				`  resume: subagent({ action: "resume", id: "${child.runId}", message: "..." })`,
			] : []),
			...(child.tokenTotals ? [`  tokens: input ${child.tokenTotals.input}, output ${child.tokenTotals.output}, total ${child.tokenTotals.total}`] : []),
		]),
		...(hasResumableChild ? [] : ["No resumable retained child is listed. Launch a same-role fallback challenge and label it as fallback."]),
	].join("\n");
}

export const MIN_SAFE_ASYNC_RUN_PREFIX_LENGTH = 8;
const FULL_ASYNC_RUN_ID_LENGTH = 36;

/** Full generated ids and longer exact identities never fall back to a root scan. */
export function canScanAsyncRunPrefix(id: string): boolean {
	return id.length >= MIN_SAFE_ASYNC_RUN_PREFIX_LENGTH && id.length < FULL_ASYNC_RUN_ID_LENGTH;
}

import * as fs from "node:fs";
import * as path from "node:path";
import { DIRS, type SubagentState } from "../../shared/types.ts";
import { readStatus } from "../../shared/utils.ts";
import { findAsyncRunPrefixMatches, type AsyncRunLocation } from "./async-resume.ts";
import { resultCandidateFilesForToolCall, resultFilePath, resultPayloadPathForIndexedRun } from "./result-files.ts";
import { readActiveRunToolCallIndex } from "./active-run-index.ts";
import { assertSafeNestedId, findNestedRunMatchesById, type NestedRoute, type NestedRunMatch, type NestedRunResolutionScope } from "../shared/nested-events.ts";

export type ResolvedSubagentRunId =
	| { kind: "foreground"; id: string }
	| { kind: "async"; id: string; location: AsyncRunLocation }
	| { kind: "nested"; id: string; match: NestedRunMatch };

export interface ResolveSubagentRunIdDeps {
	state?: SubagentState;
	asyncDirRoot?: string;
	resultsDir?: string;
	nested?: NestedRunResolutionScope;
}

function exactAsyncLocation(id: string, asyncDirRoot: string, resultsDir: string): AsyncRunLocation | undefined {
	const asyncDir = path.join(asyncDirRoot, id);
	const asyncDirExists = fs.existsSync(asyncDir);
	const resultPath = resultPathFor(resultsDir, id);
	if (!asyncDirExists && !resultPath) return undefined;
	return {
		asyncDir: asyncDirExists ? asyncDir : null,
		resultPath,
		resolvedId: id,
	};
}

type AsyncRunMatch = { id: string; location: AsyncRunLocation };

type WorkflowResultIdentity = {
	id?: string;
	runId?: string;
	toolCallId?: string;
};

function readWorkflowResultIdentity(resultPath: string): WorkflowResultIdentity | undefined {
	let parsed: unknown;
	try {
		parsed = JSON.parse(fs.readFileSync(resultPath, "utf-8")) as unknown;
	} catch {
		return undefined;
	}
	if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return undefined;
	const record = parsed as Record<string, unknown>;
	return {
		...(typeof record.id === "string" ? { id: record.id } : {}),
		...(typeof record.runId === "string" ? { runId: record.runId } : {}),
		...(typeof record.toolCallId === "string" ? { toolCallId: record.toolCallId } : {}),
	};
}

function resultPathFor(resultsDir: string, runId: string): string | null {
	const resultPath = resultPayloadPathForIndexedRun(resultsDir, runId) ?? resultFilePath(resultsDir, runId);
	return fs.existsSync(resultPath) ? resultPath : null;
}

function toolCallIdMatches(value: string | undefined, query: string): boolean {
	return value === query;
}

function indexedToolCallIdAsyncLocations(toolCallId: string, asyncDirRoot: string, resultsDir: string): AsyncRunMatch[] {
	const byId = new Map<string, AsyncRunLocation>();
	for (const entry of readActiveRunToolCallIndex(asyncDirRoot, toolCallId)) {
		const asyncDir = path.join(asyncDirRoot, entry);
		const status = readStatus(asyncDir);
		if (!status || !toolCallIdMatches(status.toolCallId, toolCallId)) continue;
		const runId = status.runId || entry;
		byId.set(runId, { asyncDir, resultPath: resultPathFor(resultsDir, runId), resolvedId: runId });
	}
	for (const entry of resultCandidateFilesForToolCall(resultsDir, toolCallId)) {
		const runIdFromFile = entry.slice(0, -".json".length);
		const resultPath = resultPayloadPathForIndexedRun(resultsDir, runIdFromFile) ?? path.join(resultsDir, entry);
		const identity = readWorkflowResultIdentity(resultPath);
		if (!identity || !toolCallIdMatches(identity.toolCallId, toolCallId)) continue;
		const runId = identity.runId ?? identity.id ?? runIdFromFile;
		const asyncDir = path.join(asyncDirRoot, runId);
		byId.set(runId, { asyncDir: fs.existsSync(asyncDir) ? asyncDir : null, resultPath, resolvedId: runId });
	}
	return [...byId.entries()].map(([id, location]) => ({ id, location }));
}

function foregroundIds(state: SubagentState | undefined): string[] {
	if (!state) return [];
	const remembered = state.currentSessionId
		? [...(state.foregroundRuns?.values() ?? [])]
			.filter((run) => run.sessionId === state.currentSessionId)
			.map((run) => run.runId)
		: [];
	return [...new Set([...state.foregroundControls.keys(), ...remembered])];
}

function hasExactForegroundId(state: SubagentState | undefined, id: string): boolean {
	if (!state) return false;
	if (state.foregroundControls.has(id)) return true;
	const remembered = state.foregroundRuns?.get(id);
	return Boolean(remembered && state.currentSessionId && remembered.sessionId === state.currentSessionId);
}

function exactLiveAsyncToolCallMatch(state: SubagentState | undefined, toolCallId: string, asyncDirRoot: string, resultsDir: string): AsyncRunMatch | undefined {
	if (!state?.asyncJobs) return undefined;
	const matches = [...state.asyncJobs.values()].filter((job) => job.toolCallId === toolCallId);
	if (matches.length > 1) throw new Error(`Subagent tool-call id '${toolCallId}' is ambiguous across async runs. Use the returned asyncId instead.`);
	const match = matches[0];
	if (!match) return undefined;
	return {
		id: match.asyncId,
		location: {
			asyncDir: fs.existsSync(match.asyncDir) ? match.asyncDir : path.join(asyncDirRoot, match.asyncId),
			resultPath: resultPathFor(resultsDir, match.asyncId),
			resolvedId: match.asyncId,
		},
	};
}

function nestedScopeFromState(state: SubagentState | undefined): NestedRunResolutionScope | undefined {
	if (!state) return undefined;
	const routes: NestedRoute[] = [];
	const seen = new Set<string>();
	const add = (route: NestedRoute | undefined) => {
		if (!route) return;
		const key = `${route.rootRunId}:${route.eventSink}:${route.controlInbox}`;
		if (seen.has(key)) return;
		seen.add(key);
		routes.push(route);
	};
	for (const control of state.foregroundControls.values()) add(control.nestedRoute as NestedRoute | undefined);
	for (const job of state.asyncJobs.values()) add(job.nestedRoute as NestedRoute | undefined);
	return { routes };
}

function asyncPrefixMatches(prefix: string, asyncDirRoot: string, resultsDir: string): Array<{ id: string; location: AsyncRunLocation }> {
	return findAsyncRunPrefixMatches(prefix, asyncDirRoot, resultsDir);
}

export function resolveSubagentRunId(id: string, deps: ResolveSubagentRunIdDeps = {}): ResolvedSubagentRunId | undefined {
	assertSafeNestedId("id", id);
	const asyncDirRoot = deps.asyncDirRoot ?? DIRS.async;
	const resultsDir = deps.resultsDir ?? DIRS.results;

	const nestedScope = deps.nested ?? nestedScopeFromState(deps.state);
	if (hasExactForegroundId(deps.state, id)) return { kind: "foreground", id };
	const exactAsync = exactAsyncLocation(id, asyncDirRoot, resultsDir);
	if (exactAsync) return { kind: "async", id, location: exactAsync };
	const exactLiveToolCallMatch = exactLiveAsyncToolCallMatch(deps.state, id, asyncDirRoot, resultsDir);
	if (exactLiveToolCallMatch) return { kind: "async", id: exactLiveToolCallMatch.id, location: exactLiveToolCallMatch.location };
	const exactToolCallIdMatches = indexedToolCallIdAsyncLocations(id, asyncDirRoot, resultsDir);
	if (exactToolCallIdMatches.length > 1) throw new Error(`Subagent tool-call id '${id}' is ambiguous across async runs. Use the returned asyncId instead.`);
	if (exactToolCallIdMatches[0]) return { kind: "async", id: exactToolCallIdMatches[0].id, location: exactToolCallIdMatches[0].location };
	const exactNested = findNestedRunMatchesById(id, nestedScope ? { scope: nestedScope } : {});
	if (exactNested.length > 1) throw new Error(`Nested run id '${id}' is ambiguous across authorized registries. Provide the full id after stale registries are cleaned up.`);
	if (exactNested[0]) return { kind: "nested", id, match: exactNested[0] };

	const matches: ResolvedSubagentRunId[] = [];
	for (const foregroundId of foregroundIds(deps.state).filter((candidate) => candidate.startsWith(id))) {
		matches.push({ kind: "foreground", id: foregroundId });
	}
	for (const match of asyncPrefixMatches(id, asyncDirRoot, resultsDir)) {
		matches.push({ kind: "async", id: match.id, location: match.location });
	}
	for (const match of findNestedRunMatchesById(id, nestedScope ? { prefix: true, scope: nestedScope } : { prefix: true })) {
		matches.push({ kind: "nested", id: match.run.id, match });
	}
	const unique = new Map(matches.map((match) => [`${match.kind}:${match.id}`, match]));
	const values = [...unique.values()];
	if (values.length > 1) {
		throw new Error(`Ambiguous subagent run id prefix '${id}' matched: ${values.map((match) => `${match.kind}:${match.id}`).join(", ")}. Provide a longer id.`);
	}
	return values[0];
}

